class DataConnectorManager:
    """Comprehensive data connector and integration system for real-time geological, meteorological, and seismic data"""
    
    def __init__(self, config_path: Optional[str] = None):
        self.config = self._load_config(config_path)
        self.cache = {}
        self.database_connections = {}
        self.api_clients = {}
        self._initialize_connections()
        
        # Rate limiting for APIs
        self.rate_limits = {
            'usgs': {'requests_per_minute': 30, 'last_requests': []},
            'noaa': {'requests_per_minute': 50, 'last_requests': []},
            'openweather': {'requests_per_minute': 60, 'last_requests': []},
            'iris': {'requests_per_minute': 10, 'last_requests': []}
        }
    
    def _load_config(self, config_path: Optional[str]) -> Dict:
        """Load configuration from file or use defaults"""
        default_config = {
            'cache': {
                'ttl_seconds': 3600,
                'max_size': 1000
            },
            'databases': {
                'sqlite_cache': {
                    'path': 'data_cache.db',
                    'enabled': True
                },
                'postgresql': {
                    'host': 'localhost',
                    'port': 5432,
                    'database': 'geophysics',
                    'enabled': False
                }
            },
            'apis': {
                'usgs_earthquake': {
                    'base_url': 'https://earthquake.usgs.gov/fdsnws/event/1/query',
                    'timeout': 30
                },
                'usgs_geology': {
                    'base_url': 'https://mrdata.usgs.gov/services/sgmc2/wfs',
                    'timeout': 30
                },
                'noaa_weather': {
                    'base_url': 'https://api.weather.gov',
                    'timeout': 15
                },
                'openweather': {
                    'base_url': 'https://api.openweathermap.org/data/2.5',
                    'api_key': os.getenv('OPENWEATHER_API_KEY'),
                    'timeout': 15
                },
                'iris': {
                    'base_url': 'http://service.iris.edu',
                    'timeout': 30
                },
                'macrostrat': {
                    'base_url': 'https://macrostrat.org/api',
                    'timeout': 20
                }
            }
        }
        
        if config_path and os.path.exists(config_path):
            try:
                with open(config_path, 'r') as f:
                    user_config = json.load(f)
                # Merge configurations
                for section, values in user_config.items():
                    if section in default_config:
                        default_config[section].update(values)
                    else:
                        default_config[section] = values
            except Exception as e:
                logging.warning(f"Failed to load config from {config_path}: {e}")
        
        return default_config
    
    def _initialize_connections(self):
        """Initialize database connections and API clients"""
        try:
            # Initialize SQLite cache
            if self.config['databases']['sqlite_cache']['enabled']:
                cache_path = self.config['databases']['sqlite_cache']['path']
                self.database_connections['cache'] = sqlite3.connect(cache_path, check_same_thread=False)
                self._setup_cache_tables()
            
            # Initialize Redis if available
            if REDIS_AVAILABLE:
                try:
                    self.cache['redis'] = redis.Redis(host='localhost', port=6379, decode_responses=True)
                    self.cache['redis'].ping()  # Test connection
                except Exception:
                    self.cache['redis'] = None
                    
        except Exception as e:
            logging.error(f"Failed to initialize data connections: {e}")
    
    def _setup_cache_tables(self):
        """Setup cache tables in SQLite"""
        if 'cache' in self.database_connections:
            conn = self.database_connections['cache']
            cursor = conn.cursor()
            
            # Weather data cache
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS weather_cache (
                    id INTEGER PRIMARY KEY,
                    lat REAL, lon REAL,
                    timestamp TEXT,
                    data TEXT,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
                )
            ''')
            
            # Geological data cache
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS geological_cache (
                    id INTEGER PRIMARY KEY,
                    lat REAL, lon REAL,
                    data TEXT,
                    source TEXT,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
                )
            ''')
            
            conn.commit()
    
    def _check_rate_limit(self, api_name: str) -> bool:
        """Check if API call is within rate limits"""
        if api_name not in self.rate_limits:
            return True
        
        rate_limit = self.rate_limits[api_name]
        current_time = time.time()
        
        # Clean old requests
        rate_limit['last_requests'] = [
            req_time for req_time in rate_limit['last_requests']
            if current_time - req_time < 60  # Within last minute
        ]
        
        return len(rate_limit['last_requests']) < rate_limit['requests_per_minute']
    
    def _record_api_call(self, api_name: str):
        """Record API call for rate limiting"""
        if api_name in self.rate_limits:
            self.rate_limits[api_name]['last_requests'].append(time.time())
    
    async def get_weather_data(self, lat: float, lon: float, timestamp: datetime) -> Dict:
        """Get weather data from multiple sources with fallbacks"""
        cache_key = f"weather_{lat:.4f}_{lon:.4f}_{timestamp.strftime('%Y%m%d%H')}"
        
        # Check cache first
        cached_data = self._get_from_cache(cache_key)
        if cached_data:
            return cached_data
        
        weather_data = {}
        
        # Try OpenWeatherMap first
        if self.config['apis']['openweather']['api_key']:
            try:
                openweather_data = await self._get_openweather_data(lat, lon, timestamp)
                if openweather_data:
                    weather_data.update(openweather_data)
                    weather_data['primary_source'] = 'openweathermap'
            except Exception as e:
                logging.warning(f"OpenWeatherMap API failed: {e}")
        
        # Try NOAA as fallback
        if not weather_data:
            try:
                noaa_data = await self._get_noaa_weather_data(lat, lon, timestamp)
                if noaa_data:
                    weather_data.update(noaa_data)
                    weather_data['primary_source'] = 'noaa'
            except Exception as e:
                logging.warning(f"NOAA API failed: {e}")
        
        # Final fallback to climatology
        if not weather_data:
            weather_data = self._get_climatological_weather_data(lat, lon, timestamp)
            weather_data['primary_source'] = 'climatology'
        
        # Cache the result
        if weather_data:
            self._store_in_cache(cache_key, weather_data, ttl=3600)
        
        return weather_data
    
    async def _get_openweather_data(self, lat: float, lon: float, timestamp: datetime) -> Optional[Dict]:
        """Get data from OpenWeatherMap API"""
        api_config = self.config['apis']['openweather']
        if not api_config.get('api_key'):
            return None
        
        if not self._check_rate_limit('openweather'):
            await asyncio.sleep(60)  # Wait if rate limited
        
        try:
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=api_config['timeout'])) as session:
                # Current weather
                current_url = f"{api_config['base_url']}/weather"
                params = {
                    'lat': lat,
                    'lon': lon,
                    'appid': api_config['api_key'],
                    'units': 'metric'
                }
                
                async with session.get(current_url, params=params) as response:
                    if response.status == 200:
                        current_data = await response.json()
                        self._record_api_call('openweather')
                        
                        return {
                            'temperature_c': current_data.get('main', {}).get('temp'),
                            'pressure_hpa': current_data.get('main', {}).get('pressure'),
                            'humidity_percent': current_data.get('main', {}).get('humidity'),
                            'wind_speed_ms': current_data.get('wind', {}).get('speed'),
                            'wind_direction_deg': current_data.get('wind', {}).get('deg'),
                            'precipitation_mm_1h': current_data.get('rain', {}).get('1h', 0.0),
                            'snow_mm_1h': current_data.get('snow', {}).get('1h', 0.0),
                            'cloud_cover_percent': current_data.get('clouds', {}).get('all'),
                            'visibility_m': current_data.get('visibility'),
                            'weather_description': current_data.get('weather', [{}])[0].get('description'),
                            'timestamp': timestamp.isoformat(),
                            'source': 'openweathermap'
                        }
        
        except Exception as e:
            logging.error(f"OpenWeatherMap API error: {e}")
            return None
    
    async def _get_noaa_weather_data(self, lat: float, lon: float, timestamp: datetime) -> Optional[Dict]:
        """Get weather data from NOAA API"""
        if not self._check_rate_limit('noaa'):
            await asyncio.sleep(60)
        
        try:
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as session:
                # Get nearest weather station
                stations_url = f"{self.config['apis']['noaa_weather']['base_url']}/stations"
                params = {'point': f"{lat},{lon}", 'limit': 1}
                
                async with session.get(stations_url, params=params) as response:
                    if response.status == 200:
                        stations_data = await response.json()
                        if stations_data.get('features'):
                            station_id = stations_data['features'][0]['properties']['stationIdentifier']
                            
                            # Get observations
                            obs_url = f"{self.config['apis']['noaa_weather']['base_url']}/stations/{station_id}/observations/latest"
                            async with session.get(obs_url) as obs_response:
                                if obs_response.status == 200:
                                    obs_data = await obs_response.json()
                                    properties = obs_data.get('properties', {})
                                    
                                    self._record_api_call('noaa')
                                    
                                    return {
                                        'temperature_c': self._convert_temperature(properties.get('temperature')),
                                        'pressure_hpa': self._convert_pressure(properties.get('barometricPressure')),
                                        'humidity_percent': properties.get('relativeHumidity', {}).get('value'),
                                        'wind_speed_ms': self._convert_wind_speed(properties.get('windSpeed')),
                                        'wind_direction_deg': properties.get('windDirection', {}).get('value'),
                                        'precipitation_mm_1h': 0.0,  # Not available in current observations
                                        'visibility_m': self._convert_visibility(properties.get('visibility')),
                                        'timestamp': timestamp.isoformat(),
                                        'source': 'noaa',
                                        'station_id': station_id
                                    }
        
        except Exception as e:
            logging.error(f"NOAA API error: {e}")
            return None
    
    def _get_climatological_weather_data(self, lat: float, lon: float, timestamp: datetime) -> Dict:
        """Get climatological fallback weather data"""
        # Simple climatological model based on latitude and season
        day_of_year = timestamp.timetuple().tm_yday
        season_factor = np.sin(2 * np.pi * (day_of_year - 81) / 365)  # Peak in summer
        
        # Temperature model
        base_temp = 15 - 0.6 * abs(lat)  # Decrease with latitude
        seasonal_temp = 10 * season_factor
        temperature_c = base_temp + seasonal_temp
        
        # Pressure model (decreases with altitude, approximated by latitude effects)
        pressure_hpa = 1013.25 - 0.12 * abs(lat)
        
        return {
            'temperature_c': temperature_c,
            'pressure_hpa': pressure_hpa,
            'humidity_percent': 60.0,  # Average humidity
            'wind_speed_ms': 3.0,  # Light breeze
            'wind_direction_deg': 270.0,  # Westerly
            'precipitation_mm_1h': 0.0,
            'snow_mm_1h': 0.0,
            'cloud_cover_percent': 50.0,
            'visibility_m': 10000.0,
            'weather_description': 'climatological average',
            'timestamp': timestamp.isoformat(),
            'source': 'climatology'
        }
    
    async def get_geological_data(self, lat: float, lon: float) -> Dict:
        """Get geological data from multiple sources"""
        cache_key = f"geology_{lat:.4f}_{lon:.4f}"
        
        cached_data = self._get_from_cache(cache_key)
        if cached_data:
            return cached_data
        
        geological_data = {}
        
        # Try USGS first
        try:
            usgs_data = await self._get_usgs_geology_data(lat, lon)
            if usgs_data:
                geological_data.update(usgs_data)
                geological_data['primary_source'] = 'usgs'
        except Exception as e:
            logging.warning(f"USGS geology API failed: {e}")
        
        # Try Macrostrat as fallback
        if not geological_data:
            try:
                macrostrat_data = await self._get_macrostrat_data(lat, lon)
                if macrostrat_data:
                    geological_data.update(macrostrat_data)
                    geological_data['primary_source'] = 'macrostrat'
            except Exception as e:
                logging.warning(f"Macrostrat API failed: {e}")
        
        # Final fallback to simplified model
        if not geological_data:
            geological_data = self._get_simplified_geological_fallback(lat, lon)
            geological_data['primary_source'] = 'simplified_model'
        
        if geological_data:
            self._store_in_cache(cache_key, geological_data, ttl=86400)  # Cache for 24 hours
        
        return geological_data
    
    async def _get_usgs_geology_data(self, lat: float, lon: float) -> Optional[Dict]:
        """Get geological data from USGS services"""
        try:
            if not self._check_rate_limit('usgs'):
                await asyncio.sleep(60)
            
            # USGS National Geologic Map Database API
            base_url = "https://mrdata.usgs.gov/services/sgmc2/wfs"
            params = {
                'service': 'WFS',
                'version': '1.1.0',
                'request': 'GetFeature',
                'typeName': 'sgmc2:SGMC_Geology',
                'outputFormat': 'application/json',
                'CQL_FILTER': f'INTERSECTS(geom, POINT({lon} {lat}))'
            }
            
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=30)) as session:
                async with session.get(base_url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        self._record_api_call('usgs')
                        
                        if data.get('features'):
                            feature = data['features'][0]
                            properties = feature.get('properties', {})
                            
                            return {
                                'rock_type': properties.get('ROCKTYPE1'),
                                'formation': properties.get('UNIT_NAME'),
                                'age': properties.get('MIN_AGE'),
                                'max_age': properties.get('MAX_AGE'),
                                'lithology': properties.get('LITHOLOGY'),
                                'description': properties.get('DESCRIP'),
                                'source': 'usgs_sgmc'
                            }
        
        except Exception as e:
            logging.error(f"USGS geology API error: {e}")
            return None
    
    async def _get_macrostrat_data(self, lat: float, lon: float) -> Optional[Dict]:
        """Get geological data from Macrostrat API"""
        try:
            if not self._check_rate_limit('usgs'):  # Use same rate limit
                await asyncio.sleep(30)
            
            base_url = f"{self.config['apis']['macrostrat']['base_url']}/geologic_units/map"
            params = {
                'lat': lat,
                'lng': lon,
                'format': 'json'
            }
            
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=20)) as session:
                async with session.get(base_url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        if data.get('success') and data.get('success', {}).get('data'):
                            unit_data = data['success']['data'][0]
                            
                            return {
                                'rock_type': unit_data.get('lith_type'),
                                'formation': unit_data.get('unit_name'),
                                'age': unit_data.get('min_interval_name'),
                                'max_age': unit_data.get('max_interval_name'),
                                'lithology': unit_data.get('lith_class'),
                                'description': unit_data.get('unit_descrip'),
                                'source': 'macrostrat'
                            }
        
        except Exception as e:
            logging.error(f"Macrostrat API error: {e}")
            return None
    
    def _get_simplified_geological_fallback(self, lat: float, lon: float) -> Dict:
        """Simple geological model based on global patterns"""
        # Determine basic geological setting
        if abs(lat) < 30:  # Tropical/equatorial
            if -180 <= lon <= -30:  # Americas
                setting = 'continental_platform'
            elif -30 <= lon <= 60:  # Africa/Europe
                setting = 'continental_shield'
            else:  # Asia/Pacific
                setting = 'oceanic_basin'
        else:  # Higher latitudes
            setting = 'continental_platform'
        
        geological_settings = {
            'continental_platform': {
                'rock_type': 'sedimentary',
                'formation': 'platform_sequence',
                'age': 'Paleozoic',
                'lithology': 'sandstone_limestone'
            },
            'continental_shield': {
                'rock_type': 'igneous',
                'formation': 'precambrian_basement',
                'age': 'Precambrian',
                'lithology': 'granite_gneiss'
            },
            'oceanic_basin': {
                'rock_type': 'igneous',
                'formation': 'oceanic_crust',
                'age': 'Mesozoic',
                'lithology': 'basalt'
            }
        }
        
        setting_data = geological_settings.get(setting, geological_settings['continental_platform'])
        
        return {
            'rock_type': setting_data['rock_type'],
            'formation': setting_data['formation'],
            'age': setting_data['age'],
            'lithology': setting_data['lithology'],
            'description': f'Simplified {setting} model',
            'source': 'geological_fallback'
        }
    
    def _convert_temperature(self, temp_data: Optional[Dict]) -> Optional[float]:
        """Convert temperature with units"""
        if not temp_data or temp_data.get('value') is None:
            return None
        temp_c = temp_data['value']
        # Assume Celsius, could check units
        return temp_c
    
    def _convert_pressure(self, pressure_data: Optional[Dict]) -> Optional[float]:
        """Convert pressure to hPa"""
        if not pressure_data or pressure_data.get('value') is None:
            return None
        pressure_pa = pressure_data['value']
        return pressure_pa / 100.0  # Convert Pa to hPa
    
    def _convert_wind_speed(self, wind_data: Optional[Dict]) -> Optional[float]:
        """Convert wind speed to m/s"""
        if not wind_data or wind_data.get('value') is None:
            return None
        return wind_data['value']  # Assume m/s
    
    def _convert_visibility(self, vis_data: Optional[Dict]) -> Optional[float]:
        """Convert visibility to meters"""
        if not vis_data or vis_data.get('value') is None:
            return None
        return vis_data['value']  # Assume meters
    
    def _get_from_cache(self, key: str) -> Optional[Dict]:
        """Get data from cache"""
        # Try Redis first
        if self.cache.get('redis'):
            try:
                cached_str = self.cache['redis'].get(key)
                if cached_str:
                    return json.loads(cached_str)
            except Exception:
                pass
        
        # Try in-memory cache
        if key in self.cache:
            cache_entry = self.cache[key]
            if time.time() - cache_entry['timestamp'] < cache_entry['ttl']:
                return cache_entry['data']
            else:
                del self.cache[key]
        
        return None
    
    def _store_in_cache(self, key: str, data: Dict, ttl: int = 3600):
        """Store data in cache"""
        # Store in Redis
        if self.cache.get('redis'):
            try:
                self.cache['redis'].setex(key, ttl, json.dumps(data))
            except Exception:
                pass
        
        # Store in memory
        self.cache[key] = {
            'data': data,
            'timestamp': time.time(),
            'ttl': ttl
        }
        
        # Limit memory cache size
        if len(self.cache) > self.config['cache']['max_size']:
            oldest_key = min(self.cache.keys(), key=lambda k: self.cache[k]['timestamp'])
            del self.cache[oldest_key]


@dataclass
class ArrayConfig:
    """Configuration for array processing"""
    sample_rate: float = 50.0
    frequency_range: Tuple[float, float] = (1.0, 10.0)
    slowness_range: Tuple[float, float] = (0.0, 0.3)  # s/km
    azimuth_range: Tuple[float, float] = (0.0, 360.0)  # degrees
    grid_points: int = 101
    beam_window: float = 10.0  # seconds
    overlap_ratio: float = 0.5
    coherence_threshold: float = 0.3
    ml_enhancement: bool = True
    adaptive_weights: bool = True


@dataclass
class ArrayGeometry:
    """Array station geometry"""
    station_coords: np.ndarray  # (n_stations, 2) - [x, y] in km
    station_names: List[str]
    reference_coord: Tuple[float, float] = (0.0, 0.0)
    elevation_coords: Optional[np.ndarray] = None
    
    def __post_init__(self):
        if self.elevation_coords is None:
            self.elevation_coords = np.zeros(len(self.station_names))


@dataclass 
class ModelCheckpoint:
    """Enhanced model checkpoint management"""
    model_name: str
    timestamp: datetime
    epoch: int
    loss: float
    metrics: Dict[str, float]
    state_dict: Dict[str, Any]
    optimizer_state: Optional[Dict[str, Any]] = None
    config: Optional[Dict[str, Any]] = None
    metadata: Optional[Dict[str, Any]] = None
    
    def save(self, checkpoint_dir: Path):
        """Save checkpoint to disk with compression and validation"""
        checkpoint_path = checkpoint_dir / f"{self.model_name}_epoch_{self.epoch}_{self.timestamp.strftime('%Y%m%d_%H%M%S')}.pkl"
        
        try:
            with open(checkpoint_path, 'wb') as f:
                pickle.dump(self, f, protocol=pickle.HIGHEST_PROTOCOL)
            
            # Create checksum for validation
            with open(checkpoint_path.with_suffix('.checksum'), 'w') as f:
                checksum = self._calculate_checksum(checkpoint_path)
                f.write(checksum)
                
            return checkpoint_path
            
        except Exception as e:
            logging.error(f"Failed to save checkpoint {checkpoint_path}: {e}")
            raise
    
    @staticmethod
    def load(checkpoint_path: Path) -> 'ModelCheckpoint':
        """Load and validate checkpoint from disk"""
        try:
            # Validate checksum if available
            checksum_path = checkpoint_path.with_suffix('.checksum')
            if checksum_path.exists():
                with open(checksum_path, 'r') as f:
                    expected_checksum = f.read().strip()
                actual_checksum = ModelCheckpoint._calculate_checksum(checkpoint_path)
                
                if actual_checksum != expected_checksum:
                    raise ValueError(f"Checkpoint corruption detected: {checkpoint_path}")
            
            with open(checkpoint_path, 'rb') as f:
                checkpoint = pickle.load(f)
                
            return checkpoint
            
        except Exception as e:
            logging.error(f"Failed to load checkpoint {checkpoint_path}: {e}")
            raise
    
    @staticmethod
    def _calculate_checksum(file_path: Path) -> str:
        """Calculate SHA256 checksum of file"""
        hash_sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_sha256.update(chunk)
        return hash_sha256.hexdigest()


class ModelManager:
    """Advanced model lifecycle management with versioning and optimization"""
    
    def __init__(self, base_dir: str = "./model_checkpoints"):
        self.base_dir = Path(base_dir)
        self.base_dir.mkdir(parents=True, exist_ok=True)
        self.checkpoints = {}
        self.active_models = {}
        self.performance_history = {}
        self.lock = threading.Lock()
        
        # GPU memory management
        self.gpu_memory_threshold = 0.9  # 90% usage threshold
        self.memory_cleanup_enabled = True
        
        # Distributed processing
        self.process_pool = None
        self.thread_pool = None
        
        self._initialize_logging()
    
    def _initialize_logging(self):
        """Initialize comprehensive logging"""
        log_dir = self.base_dir / "logs"
        log_dir.mkdir(exist_ok=True)
        
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
            handlers=[
                logging.FileHandler(log_dir / "model_manager.log"),
                logging.StreamHandler()
            ]
        )
        self.logger = logging.getLogger(self.__class__.__name__)
    
    def save_checkpoint(self, model: nn.Module, model_name: str, epoch: int, 
                       loss: float, metrics: Dict[str, float], 
                       optimizer: Optional[torch.optim.Optimizer] = None,
                       config: Optional[Dict] = None) -> Path:
        """Save model checkpoint with enhanced metadata"""
        
        with self.lock:
            try:
                # Prepare checkpoint data
                state_dict = {k: v.cpu().clone() for k, v in model.state_dict().items()}
                optimizer_state = optimizer.state_dict() if optimizer else None
                
                checkpoint = ModelCheckpoint(
                    model_name=model_name,
                    timestamp=datetime.now(),
                    epoch=epoch,
                    loss=loss,
                    metrics=metrics,
                    state_dict=state_dict,
                    optimizer_state=optimizer_state,
                    config=config,
                    metadata={
                        'model_class': model.__class__.__name__,
                        'total_params': sum(p.numel() for p in model.parameters()),
                        'trainable_params': sum(p.numel() for p in model.parameters() if p.requires_grad),
                        'device': str(next(model.parameters()).device),
                        'torch_version': torch.__version__ if TORCH_AVAILABLE else None
                    }
                )
                
                # Save checkpoint
                checkpoint_path = checkpoint.save(self.base_dir / model_name)
                
                # Update tracking
                if model_name not in self.checkpoints:
                    self.checkpoints[model_name] = []
                self.checkpoints[model_name].append(checkpoint_path)
                
                # Maintain performance history
                if model_name not in self.performance_history:
                    self.performance_history[model_name] = []
                self.performance_history[model_name].append({
                    'epoch': epoch,
                    'loss': loss,
                    'metrics': metrics.copy(),
                    'timestamp': checkpoint.timestamp
                })
                
                # Cleanup old checkpoints if needed
                self._cleanup_old_checkpoints(model_name)
                
                self.logger.info(f"Saved checkpoint for {model_name} at epoch {epoch}, loss: {loss:.6f}")
                return checkpoint_path
                
            except Exception as e:
                self.logger.error(f"Failed to save checkpoint for {model_name}: {e}")
                raise
    
    def load_best_checkpoint(self, model: nn.Module, model_name: str, 
                           metric: str = 'loss', minimize: bool = True) -> Optional[ModelCheckpoint]:
        """Load the best performing checkpoint based on specified metric"""
        
        try:
            if model_name not in self.performance_history:
                self.logger.warning(f"No performance history found for {model_name}")
                return None
            
            history = self.performance_history[model_name]
            if not history:
                return None
            
            # Find best checkpoint
            if metric == 'loss':
                best_record = min(history, key=lambda x: x['loss'])
            else:
                best_record = min(history, key=lambda x: x['metrics'].get(metric, float('inf'))) if minimize else \
                             max(history, key=lambda x: x['metrics'].get(metric, -float('inf')))
            
            # Find corresponding checkpoint file
            best_epoch = best_record['epoch']
            checkpoint_files = self.checkpoints.get(model_name, [])
            
            best_checkpoint_path = None
            for path in checkpoint_files:
                if f"epoch_{best_epoch}" in str(path):
                    best_checkpoint_path = path
                    break
            
            if best_checkpoint_path and best_checkpoint_path.exists():
                checkpoint = ModelCheckpoint.load(best_checkpoint_path)
                
                # Load state into model
                model.load_state_dict(checkpoint.state_dict)
                
                self.logger.info(f"Loaded best checkpoint for {model_name} from epoch {best_epoch}")
                return checkpoint
            else:
                self.logger.warning(f"Best checkpoint file not found for {model_name}")
                return None
                
        except Exception as e:
            self.logger.error(f"Failed to load best checkpoint for {model_name}: {e}")
            raise
    
    def optimize_gpu_memory(self):
        """Advanced GPU memory optimization and cleanup"""
        if not TORCH_AVAILABLE or not torch.cuda.is_available():
            return
        
        try:
            # Get current memory usage
            memory_allocated = torch.cuda.memory_allocated()
            memory_reserved = torch.cuda.memory_reserved()
            max_memory = torch.cuda.max_memory_allocated()
            
            usage_ratio = memory_allocated / max_memory if max_memory > 0 else 0
            
            if usage_ratio > self.gpu_memory_threshold:
                self.logger.info(f"GPU memory usage at {usage_ratio:.2%}, initiating cleanup")
                
                # Clear PyTorch cache
                torch.cuda.empty_cache()
                
                # Force garbage collection
                import gc
                gc.collect()
                
                # Log memory stats after cleanup
                new_allocated = torch.cuda.memory_allocated()
                freed_memory = memory_allocated - new_allocated
                
                self.logger.info(f"Freed {freed_memory / 1024**2:.2f} MB of GPU memory")
            
            # Log current memory status
            self.logger.debug(f"GPU Memory - Allocated: {memory_allocated / 1024**2:.2f} MB, "
                             f"Reserved: {memory_reserved / 1024**2:.2f} MB")
            
        except Exception as e:
            self.logger.error(f"GPU memory optimization failed: {e}")
    
    def _cleanup_old_checkpoints(self, model_name: str, keep_last: int = 5):
        """Remove old checkpoints, keeping only the most recent ones"""
        
        try:
            if model_name not in self.checkpoints:
                return
            
            checkpoints = self.checkpoints[model_name]
            if len(checkpoints) <= keep_last:
                return
            
            # Sort by modification time and remove oldest
            checkpoints.sort(key=lambda x: x.stat().st_mtime, reverse=True)
            
            for old_checkpoint in checkpoints[keep_last:]:
                try:
                    old_checkpoint.unlink()  # Remove file
                    checksum_file = old_checkpoint.with_suffix('.checksum')
                    if checksum_file.exists():
                        checksum_file.unlink()
                    
                    self.logger.info(f"Removed old checkpoint: {old_checkpoint.name}")
                except Exception as e:
                    self.logger.warning(f"Failed to remove old checkpoint {old_checkpoint}: {e}")
            
            # Update tracking
            self.checkpoints[model_name] = checkpoints[:keep_last]
            
        except Exception as e:
            self.logger.error(f"Checkpoint cleanup failed for {model_name}: {e}")
    
    def get_model_performance_summary(self, model_name: str) -> Dict[str, Any]:
        """Get comprehensive performance summary for a model"""
        
        if model_name not in self.performance_history:
            return {}
        
        history = self.performance_history[model_name]
        if not history:
            return {}
        
        try:
            losses = [record['loss'] for record in history]
            epochs = [record['epoch'] for record in history]
            
            # Extract all metric names
            all_metrics = set()
            for record in history:
                all_metrics.update(record['metrics'].keys())
            
            # Calculate statistics for each metric
            metric_stats = {}
            for metric in all_metrics:
                values = [record['metrics'].get(metric) for record in history if metric in record['metrics']]
                if values:
                    metric_stats[metric] = {
                        'best': min(values) if 'loss' in metric.lower() else max(values),
                        'latest': values[-1],
                        'mean': np.mean(values),
                        'std': np.std(values),
                        'trend': 'improving' if values[-1] < values[0] else 'degrading' if 'loss' in metric.lower() else 
                                'improving' if values[-1] > values[0] else 'stable'
                    }
            
            return {
                'model_name': model_name,
                'total_epochs': len(history),
                'best_loss': min(losses),
                'latest_loss': losses[-1],
                'loss_trend': 'improving' if losses[-1] < losses[0] else 'degrading',
                'metric_statistics': metric_stats,
                'training_duration': history[-1]['timestamp'] - history[0]['timestamp'],
                'last_updated': history[-1]['timestamp']
            }
            
        except Exception as e:
            self.logger.error(f"Failed to generate performance summary for {model_name}: {e}")
            return {'error': str(e)}
    
    def initialize_distributed_processing(self, max_workers: Optional[int] = None):
        """Initialize distributed processing capabilities"""
        
        try:
            # Initialize process pool for CPU-intensive tasks
            cpu_count = mp.cpu_count()
            process_workers = min(max_workers or cpu_count, cpu_count)
            self.process_pool = ProcessPoolExecutor(max_workers=process_workers)
            
            # Initialize thread pool for I/O intensive tasks
            thread_workers = min((max_workers or cpu_count) * 2, 32)
            self.thread_pool = ThreadPoolExecutor(max_workers=thread_workers)
            
            self.logger.info(f"Initialized distributed processing: {process_workers} processes, {thread_workers} threads")
            
        except Exception as e:
            self.logger.error(f"Failed to initialize distributed processing: {e}")
            raise
    
    def shutdown_distributed_processing(self):
        """Gracefully shutdown distributed processing"""
        
        try:
            if self.process_pool:
                self.process_pool.shutdown(wait=True)
                self.process_pool = None
            
            if self.thread_pool:
                self.thread_pool.shutdown(wait=True)
                self.thread_pool = None
            
            self.logger.info("Distributed processing shutdown completed")
            
        except Exception as e:
            self.logger.error(f"Error during distributed processing shutdown: {e}")
    
    def __del__(self):
        """Cleanup resources on deletion"""
        self.shutdown_distributed_processing()


class AdvancedGPUMemoryManager:
    """Advanced GPU memory management and optimization system"""
    
    def __init__(self, memory_fraction: float = 0.8, enable_monitoring: bool = True):
        self.memory_fraction = memory_fraction
        self.enable_monitoring = enable_monitoring
        self.memory_stats_history = []
        self.peak_memory_usage = 0
        self.optimization_events = []
        
        # Memory pressure thresholds
        self.warning_threshold = 0.85
        self.critical_threshold = 0.95
        self.cleanup_threshold = 0.80
        
        # Monitoring thread
        self.monitoring_thread = None
        self.monitoring_active = False
        self.monitoring_interval = 1.0  # seconds
        
        self.logger = logging.getLogger(self.__class__.__name__)
        
        if TORCH_AVAILABLE and torch.cuda.is_available():
            self._initialize_gpu_memory_management()
    
    def _initialize_gpu_memory_management(self):
        """Initialize GPU memory management settings"""
        try:
            # Set memory fraction for PyTorch
            if hasattr(torch.cuda, 'set_memory_fraction'):
                torch.cuda.set_memory_fraction(self.memory_fraction)
            
            # Enable memory mapping for large tensors
            if hasattr(torch.backends.cuda, 'enable_memory_efficient_attention'):
                torch.backends.cuda.enable_memory_efficient_attention(True)
            
            # Get GPU properties for optimization
            device_props = torch.cuda.get_device_properties(0)
            total_memory = device_props.total_memory
            
            self.logger.info(f"Initialized GPU memory management for {device_props.name}")
            self.logger.info(f"Total GPU memory: {total_memory / 1024**3:.2f} GB")
            self.logger.info(f"Memory fraction limit: {self.memory_fraction * 100:.1f}%")
            
            # Start monitoring if enabled
            if self.enable_monitoring:
                self.start_memory_monitoring()
                
        except Exception as e:
            self.logger.error(f"Failed to initialize GPU memory management: {e}")
    
    def get_memory_info(self) -> Dict[str, float]:
        """Get comprehensive GPU memory information"""
        if not TORCH_AVAILABLE or not torch.cuda.is_available():
            return {}
        
        try:
            allocated = torch.cuda.memory_allocated()
            reserved = torch.cuda.memory_reserved()
            max_allocated = torch.cuda.max_memory_allocated()
            max_reserved = torch.cuda.max_memory_reserved()
            
            # Get device properties
            device_props = torch.cuda.get_device_properties(0)
            total_memory = device_props.total_memory
            
            # Calculate percentages
            allocated_pct = (allocated / total_memory) * 100
            reserved_pct = (reserved / total_memory) * 100
            
            return {
                'allocated_bytes': allocated,
                'reserved_bytes': reserved,
                'max_allocated_bytes': max_allocated,
                'max_reserved_bytes': max_reserved,
                'total_bytes': total_memory,
                'allocated_percent': allocated_pct,
                'reserved_percent': reserved_pct,
                'free_percent': 100 - reserved_pct,
                'fragmentation_ratio': reserved / max(allocated, 1),
                'device_name': device_props.name,
                'device_count': torch.cuda.device_count()
            }
            
        except Exception as e:
            self.logger.error(f"Failed to get GPU memory info: {e}")
            return {}
    
    def optimize_memory_allocation(self, aggressive: bool = False) -> Dict[str, Any]:
        """Advanced memory optimization with different levels of aggressiveness"""
        
        optimization_results = {
            'initial_memory': self.get_memory_info(),
            'optimizations_performed': [],
            'memory_freed': 0,
            'success': False
        }
        
        try:
            initial_allocated = torch.cuda.memory_allocated() if TORCH_AVAILABLE and torch.cuda.is_available() else 0
            
            # Level 1: Standard cleanup
            torch.cuda.empty_cache()
            optimization_results['optimizations_performed'].append('cache_cleanup')
            
            # Level 2: Garbage collection
            import gc
            collected = gc.collect()
            if collected > 0:
                optimization_results['optimizations_performed'].append(f'garbage_collection_{collected}_objects')
            
            # Level 3: Aggressive optimization
            if aggressive:
                # Force synchronization
                if TORCH_AVAILABLE and torch.cuda.is_available():
                    torch.cuda.synchronize()
                    optimization_results['optimizations_performed'].append('gpu_synchronization')
                
                # Clear all caches
                if hasattr(torch.cuda, 'reset_accumulated_memory_stats'):
                    torch.cuda.reset_accumulated_memory_stats()
                    optimization_results['optimizations_performed'].append('reset_memory_stats')
                
                # Additional cleanup
                if hasattr(torch.cuda, 'ipc_collect'):
                    torch.cuda.ipc_collect()
                    optimization_results['optimizations_performed'].append('ipc_cleanup')
            
            # Calculate memory freed
            final_allocated = torch.cuda.memory_allocated() if TORCH_AVAILABLE and torch.cuda.is_available() else 0
            memory_freed = initial_allocated - final_allocated
            
            optimization_results.update({
                'final_memory': self.get_memory_info(),
                'memory_freed': memory_freed,
                'memory_freed_mb': memory_freed / 1024**2,
                'success': True
            })
            
            self.optimization_events.append({
                'timestamp': datetime.now(),
                'type': 'aggressive' if aggressive else 'standard',
                'memory_freed': memory_freed,
                'optimizations': optimization_results['optimizations_performed']
            })
            
            self.logger.info(f"Memory optimization completed: freed {memory_freed / 1024**2:.2f} MB")
            
        except Exception as e:
            self.logger.error(f"Memory optimization failed: {e}")
            optimization_results['error'] = str(e)
        
        return optimization_results
    
    def start_memory_monitoring(self):
        """Start continuous memory monitoring in background thread"""
        
        if self.monitoring_active or not TORCH_AVAILABLE or not torch.cuda.is_available():
            return
        
        def monitoring_loop():
            self.logger.info("Started GPU memory monitoring")
            
            while self.monitoring_active:
                try:
                    memory_info = self.get_memory_info()
                    if memory_info:
                        # Store memory statistics
                        memory_stat = {
                            'timestamp': datetime.now(),
                            'allocated_percent': memory_info['allocated_percent'],
                            'reserved_percent': memory_info['reserved_percent'],
                            'fragmentation_ratio': memory_info['fragmentation_ratio']
                        }
                        self.memory_stats_history.append(memory_stat)
                        
                        # Keep only recent history (last 1000 measurements)
                        if len(self.memory_stats_history) > 1000:
                            self.memory_stats_history = self.memory_stats_history[-1000:]
                        
                        # Update peak usage
                        current_usage = memory_info['reserved_percent']
                        if current_usage > self.peak_memory_usage:
                            self.peak_memory_usage = current_usage
                        
                        # Check for memory pressure and trigger cleanup
                        if current_usage > self.critical_threshold * 100:
                            self.logger.warning(f"Critical GPU memory usage: {current_usage:.1f}%")
                            self.optimize_memory_allocation(aggressive=True)
                        elif current_usage > self.warning_threshold * 100:
                            self.logger.warning(f"High GPU memory usage: {current_usage:.1f}%")
                            if current_usage > self.cleanup_threshold * 100:
                                self.optimize_memory_allocation(aggressive=False)
                    
                    time.sleep(self.monitoring_interval)
                    
                except Exception as e:
                    self.logger.error(f"Error in memory monitoring loop: {e}")
                    time.sleep(self.monitoring_interval * 2)  # Back off on error
        
        self.monitoring_active = True
        self.monitoring_thread = threading.Thread(target=monitoring_loop, daemon=True)
        self.monitoring_thread.start()
    
    def stop_memory_monitoring(self):
        """Stop memory monitoring"""
        
        if self.monitoring_active:
            self.monitoring_active = False
            if self.monitoring_thread and self.monitoring_thread.is_alive():
                self.monitoring_thread.join(timeout=5.0)
            self.logger.info("Stopped GPU memory monitoring")
    
    def get_memory_analysis(self) -> Dict[str, Any]:
        """Generate comprehensive memory usage analysis"""
        
        if not self.memory_stats_history:
            return {'error': 'No memory statistics available'}
        
        try:
            # Extract time series data
            timestamps = [stat['timestamp'] for stat in self.memory_stats_history]
            allocated_pcts = [stat['allocated_percent'] for stat in self.memory_stats_history]
            reserved_pcts = [stat['reserved_percent'] for stat in self.memory_stats_history]
            fragmentation_ratios = [stat['fragmentation_ratio'] for stat in self.memory_stats_history]
            
            # Calculate statistics
            analysis = {
                'monitoring_period': {
                    'start': min(timestamps),
                    'end': max(timestamps),
                    'duration': max(timestamps) - min(timestamps),
                    'samples': len(self.memory_stats_history)
                },
                'allocated_memory': {
                    'current': allocated_pcts[-1],
                    'mean': np.mean(allocated_pcts),
                    'max': np.max(allocated_pcts),
                    'min': np.min(allocated_pcts),
                    'std': np.std(allocated_pcts)
                },
                'reserved_memory': {
                    'current': reserved_pcts[-1],
                    'mean': np.mean(reserved_pcts),
                    'max': np.max(reserved_pcts),
                    'min': np.min(reserved_pcts),
                    'std': np.std(reserved_pcts)
                },
                'fragmentation': {
                    'current': fragmentation_ratios[-1],
                    'mean': np.mean(fragmentation_ratios),
                    'max': np.max(fragmentation_ratios),
                    'min': np.min(fragmentation_ratios)
                },
                'peak_usage': self.peak_memory_usage,
                'optimization_events': len(self.optimization_events),
                'memory_pressure_events': sum(1 for pct in reserved_pcts if pct > self.warning_threshold * 100),
                'current_memory_info': self.get_memory_info()
            }
            
            # Add trend analysis
            if len(allocated_pcts) > 10:
                recent_trend = np.mean(allocated_pcts[-10:]) - np.mean(allocated_pcts[:10])
                analysis['memory_trend'] = 'increasing' if recent_trend > 1.0 else 'decreasing' if recent_trend < -1.0 else 'stable'
            
            return analysis
            
        except Exception as e:
            self.logger.error(f"Failed to generate memory analysis: {e}")
            return {'error': str(e)}
    
    def __del__(self):
        """Cleanup on deletion"""
        self.stop_memory_monitoring()


class DistributedTrainingManager:
    """Advanced distributed training coordination and fault tolerance"""
    
    def __init__(self, world_size: int = 1, rank: int = 0, backend: str = 'nccl'):
        self.world_size = world_size
        self.rank = rank
        self.backend = backend
        self.is_distributed = world_size > 1
        self.device_manager = None
        self.fault_tolerance_enabled = True
        
        self.logger = logging.getLogger(self.__class__.__name__)
        
        if self.is_distributed and TORCH_AVAILABLE:
            self._initialize_distributed_training()
    
    def _initialize_distributed_training(self):
        """Initialize distributed training environment"""
        
        try:
            if not torch.distributed.is_available():
                self.logger.warning("PyTorch distributed training not available")
                return
            
            # Initialize process group
            if not torch.distributed.is_initialized():
                torch.distributed.init_process_group(
                    backend=self.backend,
                    world_size=self.world_size,
                    rank=self.rank
                )
            
            # Set device for current process
            if torch.cuda.is_available():
                local_rank = self.rank % torch.cuda.device_count()
                torch.cuda.set_device(local_rank)
                self.device = torch.device(f'cuda:{local_rank}')
            else:
                self.device = torch.device('cpu')
            
            self.logger.info(f"Initialized distributed training: rank {self.rank}/{self.world_size}, device {self.device}")
            
        except Exception as e:
            self.logger.error(f"Failed to initialize distributed training: {e}")
            self.is_distributed = False
    
    def wrap_model_for_distributed(self, model: nn.Module, find_unused_parameters: bool = False) -> nn.Module:
        """Wrap model for distributed training with fault tolerance"""
        
        if not self.is_distributed or not TORCH_AVAILABLE:
            return model.to(self.device if hasattr(self, 'device') else 'cpu')
        
        try:
            # Move model to appropriate device
            model = model.to(self.device)
            
            # Wrap with DistributedDataParallel
            if hasattr(torch.nn.parallel, 'DistributedDataParallel'):
                model = torch.nn.parallel.DistributedDataParallel(
                    model,
                    device_ids=[self.device.index] if self.device.type == 'cuda' else None,
                    find_unused_parameters=find_unused_parameters
                )
            
            self.logger.info(f"Wrapped model for distributed training on rank {self.rank}")
            return model
            
        except Exception as e:
            self.logger.error(f"Failed to wrap model for distributed training: {e}")
            return model.to(self.device if hasattr(self, 'device') else 'cpu')
    
    def all_reduce_metrics(self, metrics: Dict[str, torch.Tensor]) -> Dict[str, torch.Tensor]:
        """Aggregate metrics across all processes"""
        
        if not self.is_distributed or not torch.distributed.is_initialized():
            return metrics
        
        try:
            aggregated_metrics = {}
            
            for key, value in metrics.items():
                if isinstance(value, torch.Tensor):
                    # Clone to avoid modifying original
                    aggregated_value = value.clone().detach()
                    
                    # Ensure tensor is on correct device
                    if hasattr(self, 'device'):
                        aggregated_value = aggregated_value.to(self.device)
                    
                    # All-reduce operation
                    torch.distributed.all_reduce(aggregated_value, op=torch.distributed.ReduceOp.SUM)
                    
                    # Average across processes
                    aggregated_value /= self.world_size
                    
                    aggregated_metrics[key] = aggregated_value
                else:
                    # Non-tensor values remain unchanged
                    aggregated_metrics[key] = value
            
            return aggregated_metrics
            
        except Exception as e:
            self.logger.error(f"Failed to aggregate metrics: {e}")
            return metrics
    
    def barrier(self, timeout: Optional[float] = None):
        """Synchronize all processes with optional timeout"""
        
        if not self.is_distributed or not torch.distributed.is_initialized():
            return
        
        try:
            if timeout is not None and hasattr(torch.distributed, 'barrier'):
                # Use timeout if available
                torch.distributed.barrier(timeout=timedelta(seconds=timeout))
            else:
                torch.distributed.barrier()
                
        except Exception as e:
            self.logger.error(f"Distributed barrier failed: {e}")
            if self.fault_tolerance_enabled:
                self.logger.warning("Continuing despite barrier failure")
            else:
                raise
    
    def cleanup_distributed(self):
        """Cleanup distributed training resources"""
        
        if self.is_distributed and torch.distributed.is_initialized():
            try:
                torch.distributed.destroy_process_group()
                self.logger.info("Cleaned up distributed training")
            except Exception as e:
                self.logger.error(f"Error cleaning up distributed training: {e}")
    
    def __del__(self):
        """Cleanup on deletion"""
        self.cleanup_distributed()


class TransformerAttention(nn.Module):
    """Multi-head self-attention for seismic array data"""
    
    def __init__(self, embed_dim: int, n_heads: int = 8, dropout: float = 0.1):
        super().__init__()
        self.embed_dim = embed_dim
        self.n_heads = n_heads
        self.head_dim = embed_dim // n_heads
        
        assert self.head_dim * n_heads == embed_dim
        
        self.q_proj = nn.Linear(embed_dim, embed_dim)
        self.k_proj = nn.Linear(embed_dim, embed_dim)
        self.v_proj = nn.Linear(embed_dim, embed_dim)
        self.out_proj = nn.Linear(embed_dim, embed_dim)
        
        self.dropout = nn.Dropout(dropout)
        self.layer_norm = nn.LayerNorm(embed_dim)
        
    def forward(self, x: torch.Tensor, mask: Optional[torch.Tensor] = None) -> torch.Tensor:
        batch_size, seq_len, embed_dim = x.shape
        
        # Generate queries, keys, values
        q = self.q_proj(x).view(batch_size, seq_len, self.n_heads, self.head_dim).transpose(1, 2)
        k = self.k_proj(x).view(batch_size, seq_len, self.n_heads, self.head_dim).transpose(1, 2)
        v = self.v_proj(x).view(batch_size, seq_len, self.n_heads, self.head_dim).transpose(1, 2)
        
        # Compute attention scores
        scores = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(self.head_dim)
        
        if mask is not None:
            scores = scores.masked_fill(mask == 0, -1e9)
        
        attn_weights = F.softmax(scores, dim=-1)
        attn_weights = self.dropout(attn_weights)
        
        # Apply attention to values
        attn_output = torch.matmul(attn_weights, v)
        attn_output = attn_output.transpose(1, 2).contiguous().view(batch_size, seq_len, embed_dim)
        
        # Output projection and residual connection
        output = self.out_proj(attn_output)
        return self.layer_norm(x + self.dropout(output))

class PhysicsInformedBlock(nn.Module):
    """Physics-informed neural network block for seismic wave propagation"""
    
    def __init__(self, input_dim: int, hidden_dim: int, physics_dim: int):
        super().__init__()
        self.physics_encoder = nn.Sequential(
            nn.Linear(physics_dim, hidden_dim // 2),
            nn.GELU(),
            nn.Linear(hidden_dim // 2, hidden_dim)
        )
        
        self.data_encoder = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.GELU(),
            nn.Linear(hidden_dim, hidden_dim)
        )
        
        self.fusion_layer = nn.Sequential(
            nn.Linear(hidden_dim * 2, hidden_dim),
            nn.GELU(),
            nn.Dropout(0.1),
            nn.Linear(hidden_dim, hidden_dim)
        )
        
        self.physics_constraint_layer = nn.Linear(hidden_dim, physics_dim)
        
    def forward(self, data: torch.Tensor, physics_params: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
        # Encode data and physics separately
        data_features = self.data_encoder(data)
        physics_features = self.physics_encoder(physics_params)
        
        # Fuse data and physics information
        fused_features = self.fusion_layer(torch.cat([data_features, physics_features], dim=-1))
        
        # Generate physics constraints
        physics_residual = self.physics_constraint_layer(fused_features)
        
        return fused_features, physics_residual

class UncertaintyQuantificationBlock(nn.Module):
    """Bayesian uncertainty quantification for seismic analysis"""
    
    def __init__(self, input_dim: int, output_dim: int, n_samples: int = 10):
        super().__init__()
        self.n_samples = n_samples
        
        # Variational layers for epistemic uncertainty
        self.mean_layer = nn.Linear(input_dim, output_dim)
        self.logvar_layer = nn.Linear(input_dim, output_dim)
        
        # Monte Carlo Dropout for aleatoric uncertainty
        self.dropout_layers = nn.ModuleList([
            nn.Dropout(0.1) for _ in range(3)
        ])
        
        self.hidden_layers = nn.ModuleList([
            nn.Linear(input_dim, input_dim // 2),
            nn.Linear(input_dim // 2, input_dim // 4),
            nn.Linear(input_dim // 4, output_dim)
        ])
        
    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        # Epistemic uncertainty through variational inference
        mean = self.mean_layer(x)
        logvar = self.logvar_layer(x)
        std = torch.exp(0.5 * logvar)
        
        # Sample from posterior distribution
        if self.training:
            eps = torch.randn_like(std)
            epistemic_samples = mean + eps * std
        else:
            epistemic_samples = mean
        
        # Aleatoric uncertainty through Monte Carlo Dropout
        aleatoric_samples = []
        for _ in range(self.n_samples):
            h = x
            for dropout, linear in zip(self.dropout_layers, self.hidden_layers[:-1]):
                h = F.gelu(linear(dropout(h)))
            output = self.hidden_layers[-1](self.dropout_layers[-1](h))
            aleatoric_samples.append(output)
        
        aleatoric_samples = torch.stack(aleatoric_samples, dim=0)
        aleatoric_mean = aleatoric_samples.mean(dim=0)
        aleatoric_std = aleatoric_samples.std(dim=0)
        
        # Combined uncertainty
        total_uncertainty = torch.sqrt(std**2 + aleatoric_std**2)
        
        return epistemic_samples, aleatoric_mean, total_uncertainty

class MLBeamformer(nn.Module):
    """Advanced Machine Learning enhanced beamformer with transformer attention and physics constraints"""
    
    def __init__(self, n_stations: int, frequency_bins: int, embed_dim: int = 256):
        super().__init__()
        self.n_stations = n_stations
        self.frequency_bins = frequency_bins
        self.embed_dim = embed_dim
        
        # Input embedding layers
        self.spatial_embedding = nn.Linear(n_stations * 2, embed_dim)  # Station coordinates
        self.temporal_embedding = nn.Linear(frequency_bins, embed_dim)
        self.positional_encoding = nn.Parameter(torch.randn(n_stations, embed_dim))
        
        # Multi-head self-attention layers
        self.spatial_attention = TransformerAttention(embed_dim, n_heads=8)
        self.temporal_attention = TransformerAttention(embed_dim, n_heads=8)
        self.cross_attention = TransformerAttention(embed_dim, n_heads=8)
        
        # Physics-informed processing
        self.physics_block = PhysicsInformedBlock(
            input_dim=embed_dim, 
            hidden_dim=embed_dim, 
            physics_dim=6  # [P-velocity, S-velocity, density, Qp, Qs, attenuation]
        )
        
        # Uncertainty quantification
        self.uncertainty_block = UncertaintyQuantificationBlock(
            input_dim=embed_dim,
            output_dim=n_stations,
            n_samples=20
        )
        
        # Advanced coherence analysis with graph neural networks
        self.coherence_gnn = nn.ModuleList([
            nn.Linear(embed_dim, embed_dim),
            nn.GELU(),
            nn.Linear(embed_dim, embed_dim)
        ])
        
        # Adaptive frequency weighting with attention
        self.frequency_attention = nn.MultiheadAttention(embed_dim, num_heads=8, batch_first=True)
        
        # Advanced source discrimination with transformer
        self.source_discriminator = nn.Sequential(
            nn.Linear(embed_dim, 512),
            nn.GELU(),
            nn.Dropout(0.2),
            nn.Linear(512, 256),
            nn.GELU(),
            nn.Dropout(0.2),
            nn.Linear(256, 128),
            nn.GELU(),
            nn.Linear(128, 6)  # Local, Regional, Teleseismic, Noise, Surface, Converted
        )
        
        # Output projection layers
        self.spatial_weight_proj = nn.Sequential(
            nn.Linear(embed_dim, embed_dim // 2),
            nn.GELU(),
            nn.Linear(embed_dim // 2, n_stations),
            nn.Softmax(dim=-1)
        )
        
        self.frequency_weight_proj = nn.Sequential(
            nn.Linear(embed_dim, embed_dim // 2),
            nn.GELU(), 
            nn.Linear(embed_dim // 2, frequency_bins),
            nn.Sigmoid()
        )
        
        # Learnable physics parameters
        self.physics_params = nn.Parameter(torch.randn(6))  # [Vp, Vs, rho, Qp, Qs, atten]
    
    def forward(self, data: torch.Tensor, geometry: torch.Tensor, 
                slowness_vector: torch.Tensor) -> Dict[str, torch.Tensor]:
        """
        Advanced forward pass with transformer attention and physics constraints
        
        Args:
            data: (batch, stations, time) - seismic waveform data
            geometry: (stations, 2) - station coordinates [x, y] in km
            slowness_vector: (batch, 3) - [sx, sy, magnitude] in s/km
        """
        batch_size, n_stations, n_time = data.shape
        device = data.device
        
        # 1. Input embeddings with positional encoding
        geometry_flat = geometry.flatten().expand(batch_size, -1)
        spatial_embed = self.spatial_embedding(geometry_flat)  # (batch, embed_dim)
        
        # Transform data to frequency domain for temporal embedding
        freq_data = torch.fft.rfft(data, dim=-1)  # (batch, stations, freq_bins)
        freq_magnitude = torch.abs(freq_data)
        
        # Create temporal embeddings
        temporal_embed = self.temporal_embedding(freq_magnitude.mean(dim=1))  # (batch, embed_dim)
        
        # Add positional encoding for stations
        station_embeds = spatial_embed.unsqueeze(1).repeat(1, n_stations, 1)  # (batch, stations, embed_dim)
        station_embeds = station_embeds + self.positional_encoding.unsqueeze(0).repeat(batch_size, 1, 1)
        
        # 2. Multi-head self-attention processing
        spatial_attended = self.spatial_attention(station_embeds)  # (batch, stations, embed_dim)
        
        temporal_input = temporal_embed.unsqueeze(1).repeat(1, n_stations, 1)
        temporal_attended = self.temporal_attention(temporal_input)  # (batch, stations, embed_dim)
        
        # Cross-attention between spatial and temporal features
        cross_attended = self.cross_attention(
            spatial_attended + temporal_attended
        )  # (batch, stations, embed_dim)
        
        # 3. Physics-informed processing
        physics_params_expanded = self.physics_params.unsqueeze(0).repeat(batch_size, 1)
        physics_features, physics_residual = self.physics_block(
            cross_attended.mean(dim=1), physics_params_expanded
        )
        
        # 4. Advanced frequency weighting with attention
        freq_query = physics_features.unsqueeze(1)  # (batch, 1, embed_dim)
        freq_key_value = cross_attended  # (batch, stations, embed_dim)
        
        freq_attended, freq_attention_weights = self.frequency_attention(
            freq_query, freq_key_value, freq_key_value
        )
        
        # 5. Graph neural network for coherence analysis
        coherence_features = cross_attended
        for gnn_layer in self.coherence_gnn:
            if isinstance(gnn_layer, nn.Linear):
                coherence_features = gnn_layer(coherence_features)
            else:
                coherence_features = gnn_layer(coherence_features)
        
        # 6. Uncertainty quantification
        uncertainty_input = cross_attended.mean(dim=1)  # (batch, embed_dim)
        epistemic_weights, aleatoric_weights, total_uncertainty = self.uncertainty_block(uncertainty_input)
        
        # 7. Generate adaptive weights
        spatial_weights = self.spatial_weight_proj(cross_attended.mean(dim=1))  # (batch, n_stations)
        frequency_weights = self.frequency_weight_proj(freq_attended.squeeze(1))  # (batch, freq_bins)
        
        # 8. Advanced coherence weighting
        coherence_weights = torch.softmax(
            torch.sum(coherence_features * cross_attended, dim=-1), dim=-1
        )  # (batch, stations)
        
        # 9. Combine all weights with uncertainty
        combined_spatial_weights = spatial_weights * coherence_weights * epistemic_weights
        
        # Apply frequency-domain processing
        enhanced_freq_data = freq_data * frequency_weights.unsqueeze(1)  # Apply freq weights
        enhanced_freq_data = enhanced_freq_data * combined_spatial_weights.unsqueeze(-1)  # Apply spatial weights
        
        # Transform back to time domain
        enhanced_data = torch.fft.irfft(enhanced_freq_data, n=n_time, dim=-1)
        
        # 10. Advanced source discrimination
        source_features = torch.cat([
            physics_features,
            coherence_features.mean(dim=1),
            freq_attended.squeeze(1),
            slowness_vector
        ], dim=-1)
        
        # Project to embed_dim for discriminator
        source_input = nn.Linear(source_features.shape[-1], self.embed_dim).to(device)(source_features)
        source_classification = self.source_discriminator(source_input)
        
        # 11. Calculate advanced array response
        array_response = self._calculate_physics_based_array_response(
            geometry, slowness_vector, self.physics_params
        )
        
        # 12. Advanced spectral analysis
        spectral_analysis = self._advanced_spectral_analysis(
            data, enhanced_data, geometry, slowness_vector, physics_params_expanded
        )
        
        return {
            'enhanced_data': enhanced_data,
            'spatial_weights': combined_spatial_weights,
            'frequency_weights': frequency_weights,
            'coherence_weights': coherence_weights,
            'source_classification': F.softmax(source_classification, dim=-1),
            'array_response': array_response,
            'spectral_analysis': spectral_analysis,
            'physics_residual': physics_residual,
            'epistemic_uncertainty': torch.exp(0.5 * self.uncertainty_block.logvar_layer(uncertainty_input)),
            'aleatoric_uncertainty': total_uncertainty,
            'attention_weights': {
                'spatial': spatial_attended,
                'temporal': temporal_attended,
                'cross': cross_attended,
                'frequency': freq_attention_weights
            },
            'physics_parameters': self.physics_params.detach()
        }
    
    def _calculate_physics_based_array_response(self, geometry: torch.Tensor, 
                                              slowness_vector: torch.Tensor, 
                                              physics_params: torch.Tensor) -> torch.Tensor:
        """Calculate physics-informed array response matrix"""
        batch_size = slowness_vector.shape[0]
        n_stations = geometry.shape[0]
        
        # Extract physics parameters
        vp, vs, rho, qp, qs, attenuation = physics_params[:6]
        
        # Calculate wave speeds and attenuation effects
        freq = torch.linspace(0.1, 25.0, 100, device=geometry.device)  # Frequency range
        
        # Plane wave delays with physics-based corrections
        sx, sy = slowness_vector[:, :2].T  # s/km
        
        # Calculate time delays for each station
        delays = (geometry[:, 0].unsqueeze(0) * sx.unsqueeze(1) + 
                 geometry[:, 1].unsqueeze(0) * sy.unsqueeze(1))  # (batch, stations)
        
        # Phase delays in frequency domain
        phase_delays = 2 * math.pi * freq.unsqueeze(0).unsqueeze(0) * delays.unsqueeze(-1)
        
        # Attenuation effects
        distances = torch.norm(geometry.unsqueeze(0) - geometry.mean(dim=0).unsqueeze(0).unsqueeze(0), dim=-1)
        attenuation_factor = torch.exp(-attenuation * distances.unsqueeze(0).unsqueeze(-1) * freq.unsqueeze(0).unsqueeze(0))
        
        # Complex array response
        array_response = attenuation_factor * torch.exp(-1j * phase_delays)
        
        return array_response
    
    def _advanced_spectral_analysis(self, original_data: torch.Tensor, enhanced_data: torch.Tensor,
                                   geometry: torch.Tensor, slowness_vector: torch.Tensor,
                                   physics_params: torch.Tensor) -> Dict:
        """Advanced spectral analysis with physics constraints"""
        batch_size, n_stations, n_time = original_data.shape
        
        # Multi-taper spectral estimation
        original_spectrum = torch.fft.rfft(original_data, dim=-1)
        enhanced_spectrum = torch.fft.rfft(enhanced_data, dim=-1)
        
        freqs = torch.fft.rfftfreq(n_time, device=original_data.device)
        
        # Cross-spectral density matrix
        cross_spectrum = torch.zeros(batch_size, n_stations, n_stations, len(freqs), 
                                   dtype=torch.complex64, device=original_data.device)
        
        for i in range(n_stations):
            for j in range(n_stations):
                cross_spectrum[:, i, j, :] = (enhanced_spectrum[:, i, :] * 
                                            torch.conj(enhanced_spectrum[:, j, :]))
        
        # Coherence analysis
        coherence = torch.abs(cross_spectrum)**2 / (
            torch.abs(enhanced_spectrum.unsqueeze(2))**2 * 
            torch.abs(enhanced_spectrum.unsqueeze(1))**2 + 1e-10
        )
        
        # Phase velocity estimation
        phase_diff = torch.angle(cross_spectrum)
        station_distances = torch.norm(
            geometry.unsqueeze(1) - geometry.unsqueeze(0), dim=-1
        )
        
        phase_velocities = 2 * math.pi * freqs.unsqueeze(0).unsqueeze(0).unsqueeze(0) * station_distances.unsqueeze(0).unsqueeze(-1) / (phase_diff + 1e-10)
        
        # Signal-to-noise ratio improvement
        original_power = torch.mean(torch.abs(original_spectrum)**2, dim=1)
        enhanced_power = torch.mean(torch.abs(enhanced_spectrum)**2, dim=1)
        snr_improvement = enhanced_power / (original_power + 1e-10)
        
        return {
            'coherence_matrix': coherence,
            'phase_velocities': phase_velocities,
            'snr_improvement': snr_improvement,
            'cross_spectrum': cross_spectrum,
            'frequency_bins': freqs,
            'power_spectra': {
                'original': torch.abs(original_spectrum)**2,
                'enhanced': torch.abs(enhanced_spectrum)**2
            }
        }

class RealTimeStreamProcessor:
    """Real-time seismic data streaming and processing with ML enhancement"""
    
    def __init__(self, array_geometry: ArrayGeometry, ml_beamformer: MLBeamformer):
        self.geometry = array_geometry
        self.ml_beamformer = ml_beamformer
        self.buffer_size = 4096  # samples
        self.overlap = 0.5  # 50% overlap
        self.sample_rate = 100.0  # Hz
        
        # Initialize circular buffers for each station
        self.data_buffers = {}
        self.processed_buffers = {}
        self.metadata_buffers = {}
        
        # Initialize processing parameters
        self.processing_active = False
        self.processing_thread = None
        self.processing_queue = queue.Queue(maxsize=100)
        self.result_queue = queue.Queue(maxsize=50)
        
        # Advanced signal processing components
        self.adaptive_filters = {}
        self.noise_estimators = {}
        self.quality_monitors = {}
        
        # Real-time ML inference
        self.ml_inference_enabled = True
        self.batch_inference_size = 8
        self.inference_latency_target = 0.1  # seconds
        
        # Performance monitoring
        self.performance_metrics = {
            'processing_latency': [],
            'detection_latency': [],
            'throughput': [],
            'memory_usage': [],
            'gpu_utilization': []
        }
        
        self._initialize_processing_components()
    
    def _initialize_processing_components(self):
        """Initialize real-time processing components"""
        n_stations = len(self.geometry.station_names)
        
        for i, station_name in enumerate(self.geometry.station_names):
            # Initialize data buffers
            self.data_buffers[station_name] = np.zeros(self.buffer_size * 2)  # Double buffer
            self.processed_buffers[station_name] = np.zeros(self.buffer_size)
            self.metadata_buffers[station_name] = deque(maxlen=1000)
            
            # Initialize adaptive filters
            self.adaptive_filters[station_name] = AdaptiveFilter(
                filter_length=64, 
                learning_rate=0.01
            )
            
            # Initialize noise estimators
            self.noise_estimators[station_name] = NoiseEstimator(
                window_length=256,
                update_rate=0.1
            )
            
            # Initialize quality monitors
            self.quality_monitors[station_name] = DataQualityMonitor(
                sample_rate=self.sample_rate,
                quality_threshold=0.8
            )
    
    async def start_streaming(self, data_source_config: Dict):
        """Start real-time data streaming and processing"""
        self.processing_active = True
        
        # Start data ingestion coroutine
        data_task = asyncio.create_task(
            self._data_ingestion_coroutine(data_source_config)
        )
        
        # Start processing coroutine
        processing_task = asyncio.create_task(
            self._processing_coroutine()
        )
        
        # Start ML inference coroutine
        ml_task = asyncio.create_task(
            self._ml_inference_coroutine()
        )
        
        # Start monitoring coroutine
        monitoring_task = asyncio.create_task(
            self._monitoring_coroutine()
        )
        
        # Wait for all tasks
        await asyncio.gather(data_task, processing_task, ml_task, monitoring_task)
    
    async def _data_ingestion_coroutine(self, data_source_config: Dict):
        """Async data ingestion from multiple sources"""
        try:
            if data_source_config['type'] == 'seedlink':
                await self._ingest_from_seedlink(data_source_config)
            elif data_source_config['type'] == 'kafka':
                await self._ingest_from_kafka(data_source_config)
            elif data_source_config['type'] == 'websocket':
                await self._ingest_from_websocket(data_source_config)
            elif data_source_config['type'] == 'file_stream':
                await self._ingest_from_file_stream(data_source_config)
            else:
                raise ValueError(f"Unsupported data source type: {data_source_config['type']}")
                
        except Exception as e:
            logging.error(f"Data ingestion error: {e}")
            self.processing_active = False
    
    async def _ingest_from_seedlink(self, config: Dict):
        """Ingest data from SeedLink servers"""
        import asyncio
        import aiohttp
        
        async with aiohttp.ClientSession() as session:
            while self.processing_active:
                try:
                    # Connect to SeedLink server
                    url = f"http://{config['host']}:{config['port']}/fdsnws/dataselect/1/query"
                    
                    for station_name in self.geometry.station_names:
                        params = {
                            'network': config.get('network', '*'),
                            'station': station_name,
                            'channel': config.get('channel', '*'),
                            'starttime': (datetime.utcnow() - timedelta(seconds=1)).isoformat(),
                            'endtime': datetime.utcnow().isoformat()
                        }
                        
                        async with session.get(url, params=params) as response:
                            if response.status == 200:
                                data = await response.read()
                                # Parse MiniSEED data
                                parsed_data = self._parse_miniseed(data)
                                await self._add_data_to_buffer(station_name, parsed_data)
                    
                    # Wait before next request
                    await asyncio.sleep(0.1)
                    
                except Exception as e:
                    logging.warning(f"SeedLink ingestion error: {e}")
                    await asyncio.sleep(1.0)
    
    async def _ingest_from_kafka(self, config: Dict):
        """Ingest data from Kafka streams"""
        try:
            from aiokafka import AIOKafkaConsumer
            
            consumer = AIOKafkaConsumer(
                config['topic'],
                bootstrap_servers=config['bootstrap_servers'],
                group_id=config.get('group_id', 'prometheus_seismic')
            )
            
            await consumer.start()
            
            try:
                async for msg in consumer:
                    if not self.processing_active:
                        break
                    
                    # Parse Kafka message
                    data_packet = json.loads(msg.value.decode('utf-8'))
                    station_name = data_packet['station']
                    waveform_data = np.array(data_packet['data'])
                    
                    await self._add_data_to_buffer(station_name, waveform_data)
                    
            finally:
                await consumer.stop()
                
        except ImportError:
            logging.error("aiokafka not available for Kafka streaming")
        except Exception as e:
            logging.error(f"Kafka ingestion error: {e}")
    
    async def _processing_coroutine(self):
        """Main processing coroutine"""
        while self.processing_active:
            try:
                # Check if we have enough data for processing
                if self._check_buffer_readiness():
                    # Extract synchronized data from all stations
                    synchronized_data = self._extract_synchronized_data()
                    
                    if synchronized_data is not None:
                        # Apply preprocessing
                        processed_data = await self._preprocess_data(synchronized_data)
                        
                        # Add to processing queue for ML inference
                        if not self.processing_queue.full():
                            await asyncio.get_event_loop().run_in_executor(
                                None, self.processing_queue.put, processed_data
                            )
                
                await asyncio.sleep(0.01)  # 10ms processing cycle
                
            except Exception as e:
                logging.error(f"Processing coroutine error: {e}")
                await asyncio.sleep(0.1)
    
    async def _ml_inference_coroutine(self):
        """ML inference coroutine with batch processing"""
        while self.processing_active:
            try:
                if not self.processing_queue.empty():
                    # Collect batch of data for efficient GPU processing
                    batch_data = []
                    batch_metadata = []
                    
                    for _ in range(min(self.batch_inference_size, self.processing_queue.qsize())):
                        if not self.processing_queue.empty():
                            data_item = await asyncio.get_event_loop().run_in_executor(
                                None, self.processing_queue.get
                            )
                            batch_data.append(data_item['data'])
                            batch_metadata.append(data_item['metadata'])
                    
                    if batch_data:
                        # Run ML inference
                        inference_start = time.time()
                        results = await self._run_ml_inference_batch(batch_data, batch_metadata)
                        inference_time = time.time() - inference_start
                        
                        # Update performance metrics
                        self.performance_metrics['detection_latency'].append(inference_time)
                        
                        # Add results to output queue
                        for result in results:
                            if not self.result_queue.full():
                                await asyncio.get_event_loop().run_in_executor(
                                    None, self.result_queue.put, result
                                )
                
                await asyncio.sleep(0.005)  # 5ms inference cycle
                
            except Exception as e:
                logging.error(f"ML inference coroutine error: {e}")
                await asyncio.sleep(0.1)
    
    async def _monitoring_coroutine(self):
        """System monitoring and performance tracking"""
        while self.processing_active:
            try:
                # Monitor system resources
                import psutil
                
                # CPU and memory usage
                cpu_usage = psutil.cpu_percent(interval=None)
                memory_usage = psutil.virtual_memory().percent
                
                # GPU utilization (if available)
                gpu_usage = 0
                if torch.cuda.is_available():
                    gpu_usage = torch.cuda.utilization()
                
                # Buffer status
                buffer_fill_levels = {}
                for station_name in self.geometry.station_names:
                    buffer_fill = len(self.metadata_buffers[station_name]) / 1000.0
                    buffer_fill_levels[station_name] = buffer_fill
                
                # Queue status
                processing_queue_size = self.processing_queue.qsize()
                result_queue_size = self.result_queue.qsize()
                
                # Update metrics
                self.performance_metrics['memory_usage'].append(memory_usage)
                self.performance_metrics['gpu_utilization'].append(gpu_usage)
                
                # Log status periodically
                if len(self.performance_metrics['memory_usage']) % 100 == 0:
                    logging.info(f"System Status - CPU: {cpu_usage}%, Memory: {memory_usage}%, "
                               f"GPU: {gpu_usage}%, Proc Queue: {processing_queue_size}, "
                               f"Result Queue: {result_queue_size}")
                
                await asyncio.sleep(1.0)  # Monitor every second
                
            except Exception as e:
                logging.error(f"Monitoring coroutine error: {e}")
                await asyncio.sleep(5.0)
    
    async def _run_ml_inference_batch(self, batch_data: List, batch_metadata: List) -> List:
        """Run ML inference on a batch of data"""
        try:
            # Convert to torch tensors
            data_tensor = torch.tensor(np.array(batch_data), dtype=torch.float32)
            geometry_tensor = torch.tensor(self.geometry.station_coords, dtype=torch.float32)
            
            # Generate advanced slowness vectors using ML-enhanced multi-source approach
            batch_size = data_tensor.shape[0]
            slowness_vectors = await self._generate_advanced_slowness_vectors(
                data_tensor, geometry_tensor, batch_metadata, batch_size
            )
            
            # Run ML beamformer inference
            if torch.cuda.is_available() and self.ml_inference_enabled:
                data_tensor = data_tensor.cuda()
                geometry_tensor = geometry_tensor.cuda()
                slowness_vectors = slowness_vectors.cuda()
                
                with torch.no_grad():
                    results = self.ml_beamformer(data_tensor, geometry_tensor, slowness_vectors)
            
            # Process results
            processed_results = []
            for i in range(batch_size):
                result = {
                    'timestamp': batch_metadata[i]['timestamp'],
                    'station_weights': results['spatial_weights'][i].cpu().numpy(),
                    'source_classification': results['source_classification'][i].cpu().numpy(),
                    'uncertainty': results['aleatoric_uncertainty'][i].cpu().numpy(),
                    'enhanced_data': results['enhanced_data'][i].cpu().numpy(),
                    'spectral_analysis': {
                        key: value[i].cpu().numpy() if torch.is_tensor(value) else value
                        for key, value in results['spectral_analysis'].items()
                    }
                }
                processed_results.append(result)
            
            return processed_results
            
        except Exception as e:
            logging.error(f"ML inference batch error: {e}")
            return []

class AdaptiveFilter:
    """Advanced multi-algorithm adaptive filtering with ML-enhanced noise suppression"""
    
    def __init__(self, filter_length: int, learning_rate: float = 0.01, algorithm: str = 'hybrid'):
        self.filter_length = filter_length
        self.learning_rate = learning_rate
        self.algorithm = algorithm
        
        # Multi-algorithm filter weights
        self.lms_weights = np.zeros(filter_length)
        self.nlms_weights = np.zeros(filter_length)
        self.rls_weights = np.zeros(filter_length)
        self.kalman_weights = np.zeros(filter_length)
        
        # Input buffers for each algorithm
        self.input_buffer = np.zeros(filter_length)
        self.error_history = np.zeros(100)  # Error tracking for adaptation
        
        # RLS algorithm parameters
        self.rls_lambda = 0.99  # Forgetting factor
        self.rls_P = np.eye(filter_length) * 1000  # Inverse correlation matrix
        
        # Kalman filter parameters
        self.kalman_Q = np.eye(filter_length) * 1e-5  # Process noise covariance
        self.kalman_R = 1e-3  # Measurement noise variance
        self.kalman_P = np.eye(filter_length) * 1e-2  # Error covariance
        
        # Adaptive algorithm selection
        self.algorithm_performance = {
            'lms': {'error_sum': 0, 'count': 0, 'weight': 0.25},
            'nlms': {'error_sum': 0, 'count': 0, 'weight': 0.25},
            'rls': {'error_sum': 0, 'count': 0, 'weight': 0.25},
            'kalman': {'error_sum': 0, 'count': 0, 'weight': 0.25}
        }
        
        # Advanced noise characteristics learning
        self.noise_profile = {
            'spectral_density': np.zeros(filter_length),
            'correlation_matrix': np.eye(filter_length),
            'update_count': 0
        }
        
        # Database integration for historical noise patterns
        self.db_integration = self._initialize_db_connection()
        self.model_manager = self._initialize_model_manager()
        
        # ML-enhanced noise prediction
        self.noise_predictor_model = None
        self.feature_extractor = self._initialize_feature_extractor()
        
    def _initialize_db_connection(self):
        """Initialize database connection for noise pattern storage"""
        try:
            from .database_integration import PostgreSQLGISManager
            return PostgreSQLGISManager()
        except Exception:
            return None
            
    def _initialize_model_manager(self):
        """Initialize model manager for ML components"""
        try:
            from .model_manager import ModelManager
            return ModelManager()
        except Exception:
            return None
            
    def _initialize_feature_extractor(self):
        """Initialize advanced feature extraction for noise characterization"""
        return {
            'spectral_features': True,
            'statistical_moments': True,
            'wavelet_coefficients': True,
            'entropy_measures': True
        }
        
    def update(self, input_sample: float, desired_signal: float, geological_context: Dict = None) -> Dict:
        """Advanced multi-algorithm adaptive filtering with geological context integration"""
        try:
            # Shift input buffer
            self.input_buffer[1:] = self.input_buffer[:-1]
            self.input_buffer[0] = input_sample
            
            # Extract advanced features for ML-enhanced filtering
            features = self._extract_advanced_features(geological_context)
            
            # Multi-algorithm processing
            outputs = self._compute_multi_algorithm_outputs(input_sample, desired_signal)
            
            # Adaptive algorithm weighting based on performance
            weighted_output = self._compute_adaptive_weighted_output(outputs)
            
            # Update noise profile with geological context
            self._update_noise_profile(input_sample, desired_signal, geological_context)
            
            # ML-enhanced noise prediction and compensation
            predicted_noise = self._predict_noise_ml(features)
            compensated_output = weighted_output - predicted_noise
            
            # Performance tracking and database logging
            self._log_performance_metrics(outputs, weighted_output, geological_context)
            
            return {
                'filtered_signal': compensated_output,
                'algorithm_contributions': outputs,
                'noise_prediction': predicted_noise,
                'confidence_score': self._calculate_confidence_score(),
                'geological_adaptation': self._get_geological_adaptation_info()
            }
            
        except Exception as e:
            # Fallback to basic LMS
            return self._fallback_lms_filter(input_sample, desired_signal)
            
    def _extract_advanced_features(self, geological_context: Dict = None) -> np.ndarray:
        """Extract comprehensive features for ML-enhanced filtering"""
        features = []
        
        # Statistical features
        if len(self.input_buffer) > 0:
            features.extend([
                np.mean(self.input_buffer),
                np.std(self.input_buffer),
                np.var(self.input_buffer),
                np.median(self.input_buffer),
                np.percentile(self.input_buffer, 25),
                np.percentile(self.input_buffer, 75)
            ])
            
        # Spectral features using FFT
        if len(self.input_buffer) > 1:
            fft_coeffs = np.fft.fft(self.input_buffer)
            features.extend([
                np.mean(np.abs(fft_coeffs)),
                np.std(np.abs(fft_coeffs)),
                np.argmax(np.abs(fft_coeffs))  # Dominant frequency
            ])
            
        # Geological context integration
        if geological_context:
            features.extend([
                geological_context.get('tectonic_activity_level', 0.5),
                geological_context.get('seismic_velocity_contrast', 0.5),
                geological_context.get('structural_complexity', 0.5),
                geological_context.get('noise_environment_type', 0.5)
            ])
        else:
            features.extend([0.5, 0.5, 0.5, 0.5])  # Default values
            
        return np.array(features, dtype=np.float32)
        
    def _compute_multi_algorithm_outputs(self, input_sample: float, desired_signal: float) -> Dict:
        """Compute outputs from multiple adaptive algorithms"""
        outputs = {}
        error = desired_signal - np.dot(self.lms_weights, self.input_buffer)
        
        # LMS Algorithm
        lms_output = np.dot(self.lms_weights, self.input_buffer)
        self.lms_weights += self.learning_rate * error * self.input_buffer
        outputs['lms'] = lms_output
        
        # NLMS Algorithm (Normalized LMS)
        norm_factor = np.dot(self.input_buffer, self.input_buffer) + 1e-8
        nlms_output = np.dot(self.nlms_weights, self.input_buffer)
        self.nlms_weights += (self.learning_rate / norm_factor) * error * self.input_buffer
        outputs['nlms'] = nlms_output
        
        # RLS Algorithm (Recursive Least Squares)
        k = (self.rls_P @ self.input_buffer) / (self.rls_lambda + self.input_buffer.T @ self.rls_P @ self.input_buffer)
        rls_output = np.dot(self.rls_weights, self.input_buffer)
        rls_error = desired_signal - rls_output
        self.rls_weights += k * rls_error
        self.rls_P = (self.rls_P - np.outer(k, self.input_buffer.T @ self.rls_P)) / self.rls_lambda
        outputs['rls'] = rls_output
        
        # Kalman Filter Algorithm
        # Prediction step
        kalman_output = np.dot(self.kalman_weights, self.input_buffer)
        self.kalman_P += self.kalman_Q
        
        # Update step
        kalman_error = desired_signal - kalman_output
        S = np.dot(self.input_buffer.T, np.dot(self.kalman_P, self.input_buffer)) + self.kalman_R
        K = np.dot(self.kalman_P, self.input_buffer) / S
        self.kalman_weights += K * kalman_error
        self.kalman_P -= np.outer(K, np.dot(self.input_buffer.T, self.kalman_P))
        outputs['kalman'] = kalman_output
        
        # Update performance metrics
        for alg, output in outputs.items():
            alg_error = abs(desired_signal - output)
            self.algorithm_performance[alg]['error_sum'] += alg_error
            self.algorithm_performance[alg]['count'] += 1
            
        return outputs
        
    def _compute_adaptive_weighted_output(self, outputs: Dict) -> float:
        """Compute adaptive weighted combination of algorithm outputs"""
        # Update algorithm weights based on recent performance
        total_weight = 0
        for alg in self.algorithm_performance:
            if self.algorithm_performance[alg]['count'] > 0:
                avg_error = self.algorithm_performance[alg]['error_sum'] / self.algorithm_performance[alg]['count']
                # Lower error = higher weight (inverse relationship)
                self.algorithm_performance[alg]['weight'] = 1.0 / (1.0 + avg_error)
                total_weight += self.algorithm_performance[alg]['weight']
                
        # Normalize weights
        if total_weight > 0:
            for alg in self.algorithm_performance:
                self.algorithm_performance[alg]['weight'] /= total_weight
        
        # Compute weighted output
        weighted_output = 0
        for alg, output in outputs.items():
            weight = self.algorithm_performance[alg]['weight']
            weighted_output += weight * output
            
        return weighted_output
        
    def _update_noise_profile(self, input_sample: float, desired_signal: float, geological_context: Dict = None):
        """Update noise profile with geological context"""
        self.noise_profile['update_count'] += 1
        
        # Update spectral density estimate
        if self.noise_profile['update_count'] > self.filter_length:
            fft_buffer = np.fft.fft(self.input_buffer)
            alpha = 0.1  # Smoothing factor
            self.noise_profile['spectral_density'] = (1 - alpha) * self.noise_profile['spectral_density'] + alpha * np.abs(fft_buffer)
            
        # Update correlation matrix
        if self.noise_profile['update_count'] % 10 == 0:  # Update every 10 samples
            correlation_update = np.outer(self.input_buffer, self.input_buffer)
            alpha_corr = 0.05
            self.noise_profile['correlation_matrix'] = (1 - alpha_corr) * self.noise_profile['correlation_matrix'] + alpha_corr * correlation_update
            
    def _predict_noise_ml(self, features: np.ndarray) -> float:
        """ML-enhanced noise prediction"""
        try:
            if self.model_manager and self.noise_predictor_model is None:
                # Load or initialize noise prediction model
                self.noise_predictor_model = self.model_manager.load_model('adaptive_noise_predictor_v2.1')
                
            if self.noise_predictor_model:
                # Predict noise using ML model
                prediction = self.noise_predictor_model.predict(features.reshape(1, -1))[0]
                return float(prediction)
            else:
                # Fallback to statistical prediction
                return self._statistical_noise_prediction()
                
        except Exception:
            return 0.0
            
    def _statistical_noise_prediction(self) -> float:
        """Fallback statistical noise prediction"""
        if len(self.error_history) > 10:
            # Use recent error history for prediction
            recent_errors = self.error_history[-10:]
            return np.mean(recent_errors) + 0.5 * np.std(recent_errors)
        return 0.0
        
    def _calculate_confidence_score(self) -> float:
        """Calculate confidence score for filtering performance"""
        # Base confidence on algorithm agreement
        if len(self.algorithm_performance) == 0:
            return 0.5
            
        # Calculate variance in algorithm performance
        weights = [perf['weight'] for perf in self.algorithm_performance.values()]
        weight_variance = np.var(weights)
        
        # Lower variance = higher confidence
        confidence = 1.0 / (1.0 + weight_variance * 10)
        return min(max(confidence, 0.0), 1.0)
        
    def _get_geological_adaptation_info(self) -> Dict:
        """Get information about geological adaptation"""
        return {
            'noise_profile_updates': self.noise_profile['update_count'],
            'dominant_algorithm': max(self.algorithm_performance, key=lambda x: self.algorithm_performance[x]['weight']),
            'adaptation_stability': self._calculate_confidence_score()
        }
        
    def _log_performance_metrics(self, outputs: Dict, final_output: float, geological_context: Dict = None):
        """Log performance metrics to database"""
        try:
            if self.db_integration and geological_context:
                metrics = {
                    'timestamp': datetime.now(),
                    'algorithm_outputs': outputs,
                    'final_output': final_output,
                    'geological_context': geological_context,
                    'performance_weights': {alg: perf['weight'] for alg, perf in self.algorithm_performance.items()}
                }
                # Log to database (non-blocking)
                self.db_integration.log_adaptive_filter_performance(metrics)
        except Exception:
            pass  # Non-critical logging failure
            
    def _fallback_lms_filter(self, input_sample: float, desired_signal: float) -> Dict:
        """Fallback basic LMS filter"""
        output = np.dot(self.lms_weights, self.input_buffer)
        error = desired_signal - output
        self.lms_weights += self.learning_rate * error * self.input_buffer
        
        return {
            'filtered_signal': output,
            'algorithm_contributions': {'lms': output},
            'noise_prediction': 0.0,
            'confidence_score': 0.5,
            'geological_adaptation': {'status': 'fallback_mode'}
        }

class NoiseEstimator:
    """Real-time noise level estimation"""
    
    def __init__(self, window_length: int, update_rate: float = 0.1):
        self.window_length = window_length
        self.update_rate = update_rate
        self.noise_buffer = np.zeros(window_length)
        self.noise_level = 0.0
        self.signal_level = 0.0
        
    def update(self, signal: np.ndarray):
        """Update noise estimates"""
        # Add new data to buffer
        if len(signal) >= self.window_length:
            self.noise_buffer = signal[-self.window_length:]
        else:
            shift_amount = len(signal)
            self.noise_buffer[:-shift_amount] = self.noise_buffer[shift_amount:]
            self.noise_buffer[-shift_amount:] = signal
        
        # Estimate noise level using robust statistics
        current_noise = np.median(np.abs(self.noise_buffer))
        self.noise_level = (1 - self.update_rate) * self.noise_level + self.update_rate * current_noise
        
        # Estimate signal level
        current_signal = np.std(self.noise_buffer)
        self.signal_level = (1 - self.update_rate) * self.signal_level + self.update_rate * current_signal
    
    def get_snr(self) -> float:
        """Enhanced signal-to-noise ratio calculation"""
        return self._calculate_advanced_snr()['traditional_snr']
        
    def _calculate_advanced_snr(self) -> Dict:
        """Calculate multiple SNR metrics"""
        snr_metrics = {
            'traditional_snr': 0.0,
            'spectral_snr': 0.0,
            'coherent_snr': 0.0,
            'adaptive_snr': 0.0
        }
        
        if self.noise_statistics['level'] > 0 and self.signal_statistics['level'] > 0:
            # Traditional SNR
            snr_metrics['traditional_snr'] = 20 * np.log10(self.signal_statistics['level'] / self.noise_statistics['level'])
            
            # Spectral SNR (frequency domain)
            if len(self.frequency_buffer) > 0:
                signal_power = np.mean(self.frequency_buffer**2)
                noise_power = self.noise_statistics['variance']
                if noise_power > 0:
                    snr_metrics['spectral_snr'] = 10 * np.log10(signal_power / noise_power)
                    
            # Coherent SNR (based on signal coherence)
            coherence_factor = max(self.signal_statistics['coherence'], 0.1)
            snr_metrics['coherent_snr'] = snr_metrics['traditional_snr'] * coherence_factor
            
            # Adaptive SNR (geological context weighted)
            geological_weight = 1.0  # Default
            snr_metrics['adaptive_snr'] = snr_metrics['traditional_snr'] * geological_weight
            
        return snr_metrics
        
    def _calculate_geological_noise_adjustment(self, geological_context: Dict) -> Dict:
        """Calculate noise adjustments based on geological context"""
        adjustments = {
            'level': 1.0,
            'variance': 1.0,
            'skewness': 1.0,
            'kurtosis': 1.0,
            'fractal_dimension': 1.0
        }
        
        if geological_context:
            # Tectonic activity increases noise level and variance
            tectonic_factor = geological_context.get('tectonic_activity_level', 0.5)
            adjustments['level'] *= (1.0 + tectonic_factor * 0.5)
            adjustments['variance'] *= (1.0 + tectonic_factor * 0.3)
            
            # Structural complexity affects fractal dimension
            complexity_factor = geological_context.get('structural_complexity', 0.5)
            adjustments['fractal_dimension'] *= (1.0 + complexity_factor * 0.2)
            
        return adjustments
        
    def _optimize_detection_thresholds(self, geological_context: Dict = None) -> Dict:
        """Optimize detection thresholds based on current conditions"""
        optimized = self.adaptive_thresholds.copy()
        
        try:
            # Adjust based on current noise characteristics
            current_noise_level = self.noise_statistics['level']
            if current_noise_level > 0:
                # Dynamic detection threshold
                noise_margin = 3.0 * np.sqrt(self.noise_statistics.get('variance', 1.0))
                optimized['detection_threshold'] = 20 * np.log10(current_noise_level + noise_margin)
                
            # Geological context adjustments
            if geological_context:
                tectonic_activity = geological_context.get('tectonic_activity_level', 0.5)
                cultural_noise = geological_context.get('cultural_noise_probability', 0.5)
                
                # Lower thresholds in high tectonic activity areas
                if tectonic_activity > 0.7:
                    optimized['detection_threshold'] -= 5.0
                    optimized['snr_threshold'] *= 0.8
                    
                # Raise thresholds in high cultural noise areas
                if cultural_noise > 0.7:
                    optimized['detection_threshold'] += 3.0
                    optimized['quality_threshold'] += 0.1
                    
        except Exception:
            pass  # Keep default thresholds
            
        return optimized
        
    def _analyze_geological_coherence(self, geological_context: Dict = None) -> Dict:
        """Analyze coherence with geological expectations"""
        coherence_analysis = {
            'tectonic_coherence': 0.5,
            'structural_coherence': 0.5,
            'temporal_coherence': 0.5,
            'overall_coherence': 0.5
        }
        
        if geological_context:
            # Check if noise patterns match geological expectations
            expected_activity = geological_context.get('tectonic_activity_level', 0.5)
            observed_activity = min(self.noise_statistics['level'] / 100.0, 1.0)  # Normalize
            
            coherence_analysis['tectonic_coherence'] = 1.0 - abs(expected_activity - observed_activity)
            
            # Structural complexity vs signal complexity
            expected_complexity = geological_context.get('structural_complexity', 0.5)
            observed_complexity = min(self.noise_statistics.get('fractal_dimension', 1.5) / 2.0, 1.0)
            
            coherence_analysis['structural_coherence'] = 1.0 - abs(expected_complexity - observed_complexity)
            
            # Temporal coherence based on signal stability
            coherence_analysis['temporal_coherence'] = self.signal_statistics.get('coherence', 0.5)
            
            # Overall coherence
            coherence_analysis['overall_coherence'] = np.mean([
                coherence_analysis['tectonic_coherence'],
                coherence_analysis['structural_coherence'],
                coherence_analysis['temporal_coherence']
            ])
            
        return coherence_analysis
        
    def _heuristic_source_classification(self, geological_context: Dict = None):
        """Heuristic-based noise source classification fallback"""
        # Reset probabilities
        for key in self.source_probabilities:
            self.source_probabilities[key] = 0.0
            
        # Frequency-based heuristics
        if len(self.frequency_buffer) > 0:
            peak_freq = np.argmax(self.frequency_buffer)
            dominant_freq = peak_freq / len(self.frequency_buffer)  # Normalized frequency
            
            # Low frequency: likely seismic
            if dominant_freq < 0.1:
                self.source_probabilities['seismic_events'] += 0.6
                
            # Mid frequency: cultural or environmental
            elif 0.1 <= dominant_freq < 0.5:
                self.source_probabilities['cultural_activity'] += 0.4
                self.source_probabilities['environmental_factors'] += 0.3
                
            # High frequency: likely instrumental
            else:
                self.source_probabilities['instrumental_artifacts'] += 0.5
                
        # Amplitude-based heuristics
        noise_level = self.noise_statistics.get('level', 0.0)
        if noise_level > 100:  # High amplitude
            self.source_probabilities['cultural_activity'] += 0.3
        elif noise_level < 10:  # Low amplitude
            self.source_probabilities['instrumental_artifacts'] += 0.2
            
        # Geological context heuristics
        if geological_context:
            tectonic_activity = geological_context.get('tectonic_activity_level', 0.5)
            self.source_probabilities['seismic_events'] += tectonic_activity * 0.4
            
            cultural_proximity = geological_context.get('cultural_noise_probability', 0.5)
            self.source_probabilities['cultural_activity'] += cultural_proximity * 0.3
            
        # Normalize probabilities
        total_prob = sum(self.source_probabilities.values())
        if total_prob > 0:
            for key in self.source_probabilities:
                self.source_probabilities[key] /= total_prob
        else:
            self.source_probabilities['unknown'] = 1.0
            
    def _update_performance_metrics(self, noise_analysis: Dict, signal_analysis: Dict):
        """Update advanced performance tracking metrics with ML validation and data integration"""
        try:
            # Initialize comprehensive metrics framework
            if not hasattr(self, '_metrics_framework_initialized'):
                self._initialize_advanced_metrics_framework()
            
            # Advanced prediction accuracy with multi-dimensional error analysis
            prediction_metrics = self._calculate_advanced_prediction_accuracy(
                noise_analysis, signal_analysis
            )
            
            # Integrate with model manager for cross-validation
            model_validation_metrics = self._integrate_model_manager_validation(
                noise_analysis, signal_analysis, prediction_metrics
            )
            
            # Data integration pipeline validation
            pipeline_validation_metrics = self._validate_against_data_pipeline(
                noise_analysis, signal_analysis
            )
            
            # Combine all metrics with uncertainty quantification
            combined_metrics = self._combine_metrics_with_uncertainty(
                prediction_metrics, model_validation_metrics, pipeline_validation_metrics
            )
            
            # Update performance metrics with advanced tracking
            self._update_comprehensive_performance_tracking(combined_metrics)
            
            # Statistical significance testing
            self._perform_statistical_significance_analysis(combined_metrics)
            
            # Classification confidence with ensemble validation
            self._update_advanced_classification_confidence()
            
        except Exception as e:
            logging.error(f"Error updating performance metrics: {e}")
            # Fallback to simplified metrics
            self._update_fallback_performance_metrics(noise_analysis, signal_analysis)
    
    def _initialize_advanced_metrics_framework(self):
        """Initialize comprehensive metrics framework with ML integration"""
        try:
            # Initialize metrics storage with advanced structures
            self.performance_metrics.update({
                'prediction_accuracy': {'mean': 0.5, 'std': 0.0, 'history': []},
                'classification_confidence': {'ensemble_mean': 0.5, 'variance': 0.0, 'individual_models': {}},
                'model_validation': {'cross_validation_score': 0.0, 'out_of_sample_accuracy': 0.0},
                'temporal_stability': {'drift_detection': False, 'trend_analysis': {}},
                'uncertainty_quantification': {'epistemic': 0.0, 'aleatoric': 0.0, 'total': 0.0},
                'data_quality_metrics': {'completeness': 0.0, 'consistency': 0.0, 'validity': 0.0},
                'computational_efficiency': {'processing_time': 0.0, 'memory_usage': 0.0, 'cpu_utilization': 0.0}
            })
            
            # Initialize statistical tracking
            self.metrics_history = {
                'timestamps': [],
                'accuracy_evolution': [],
                'confidence_evolution': [],
                'error_patterns': {}
            }
            
            # Initialize connection pools for external validation
            self._initialize_validation_connections()
            
            self._metrics_framework_initialized = True
            logging.info("Advanced metrics framework initialized successfully")
            
        except Exception as e:
            logging.error(f"Error initializing metrics framework: {e}")
            self._metrics_framework_initialized = False
    
    def _calculate_advanced_prediction_accuracy(self, noise_analysis: Dict, signal_analysis: Dict) -> Dict:
        """Calculate multi-dimensional prediction accuracy with uncertainty quantification"""
        try:
            accuracy_metrics = {}
            
            # Multi-level prediction accuracy analysis
            if 'level' in noise_analysis and 'level' in signal_analysis:
                # Advanced error metrics
                prediction_error = abs(noise_analysis['level'] - signal_analysis['level'])
                relative_error = prediction_error / max(abs(signal_analysis['level']), 1e-6)
                
                # Robust accuracy measures
                accuracy_metrics['absolute_accuracy'] = 1.0 / (1.0 + prediction_error)
                accuracy_metrics['relative_accuracy'] = 1.0 / (1.0 + relative_error)
                accuracy_metrics['log_accuracy'] = 1.0 / (1.0 + np.log1p(prediction_error))
                
                # Uncertainty-weighted accuracy
                noise_uncertainty = noise_analysis.get('uncertainty', 0.1)
                signal_uncertainty = signal_analysis.get('uncertainty', 0.1)
                combined_uncertainty = np.sqrt(noise_uncertainty**2 + signal_uncertainty**2)
                accuracy_metrics['uncertainty_weighted'] = accuracy_metrics['absolute_accuracy'] / (1.0 + combined_uncertainty)
            
            # Spectral accuracy analysis if frequency data available
            if 'spectrum' in noise_analysis and 'spectrum' in signal_analysis:
                spectral_correlation = self._calculate_spectral_correlation(
                    noise_analysis['spectrum'], signal_analysis['spectrum']
                )
                accuracy_metrics['spectral_accuracy'] = spectral_correlation
            
            # Spatial coherence accuracy for array data
            if 'spatial_pattern' in noise_analysis and 'spatial_pattern' in signal_analysis:
                spatial_accuracy = self._calculate_spatial_pattern_accuracy(
                    noise_analysis['spatial_pattern'], signal_analysis['spatial_pattern']
                )
                accuracy_metrics['spatial_accuracy'] = spatial_accuracy
            
            # Temporal consistency accuracy
            if hasattr(self, 'previous_predictions') and self.previous_predictions:
                temporal_consistency = self._calculate_temporal_consistency_accuracy(
                    noise_analysis, signal_analysis
                )
                accuracy_metrics['temporal_consistency'] = temporal_consistency
            
            return accuracy_metrics
            
        except Exception as e:
            logging.error(f"Error calculating advanced prediction accuracy: {e}")
            return {'absolute_accuracy': 0.5}
    
    async def _integrate_model_manager_validation(self, noise_analysis: Dict, signal_analysis: Dict, 
                                                 prediction_metrics: Dict) -> Dict:
        """Integrate with model manager for comprehensive validation"""
        try:
            validation_metrics = {}
            
            # Initialize model manager connection if available
            if not hasattr(self, 'model_manager'):
                await self._initialize_model_manager_connection()
            
            if hasattr(self, 'model_manager') and self.model_manager:
                # Cross-validation against trained models
                cross_val_score = await self.model_manager.validate_prediction_accuracy(
                    noise_analysis, signal_analysis, prediction_metrics
                )
                validation_metrics['cross_validation_score'] = cross_val_score
                
                # Out-of-sample validation
                oos_accuracy = await self.model_manager.evaluate_out_of_sample(
                    {**noise_analysis, **signal_analysis}
                )
                validation_metrics['out_of_sample_accuracy'] = oos_accuracy
                
                # Ensemble model validation
                ensemble_metrics = await self.model_manager.get_ensemble_validation_metrics()
                validation_metrics.update(ensemble_metrics)
                
                # Model uncertainty estimation
                model_uncertainty = await self.model_manager.estimate_prediction_uncertainty(
                    noise_analysis, signal_analysis
                )
                validation_metrics['model_uncertainty'] = model_uncertainty
            else:
                # Fallback validation using internal models
                validation_metrics = self._perform_internal_model_validation(
                    noise_analysis, signal_analysis, prediction_metrics
                )
            
            return validation_metrics
            
        except Exception as e:
            logging.error(f"Error integrating model manager validation: {e}")
            return {'cross_validation_score': 0.5}
    
    async def _validate_against_data_pipeline(self, noise_analysis: Dict, signal_analysis: Dict) -> Dict:
        """Validate predictions against data integration pipeline"""
        try:
            pipeline_metrics = {}
            
            # Initialize data pipeline connection
            if not hasattr(self, 'data_pipeline'):
                await self._initialize_data_pipeline_connection()
            
            if hasattr(self, 'data_pipeline') and self.data_pipeline:
                # Validate against ground truth data from pipeline
                ground_truth_validation = await self.data_pipeline.validate_against_ground_truth({
                    'noise_analysis': noise_analysis,
                    'signal_analysis': signal_analysis
                })
                pipeline_metrics.update(ground_truth_validation)
                
                # Data quality assessment
                data_quality = await self.data_pipeline.assess_input_data_quality({
                    'noise_analysis': noise_analysis,
                    'signal_analysis': signal_analysis
                })
                pipeline_metrics['data_quality'] = data_quality
                
                # Consistency check against historical patterns
                consistency_check = await self.data_pipeline.check_historical_consistency(
                    noise_analysis, signal_analysis
                )
                pipeline_metrics['historical_consistency'] = consistency_check
                
                # Anomaly detection validation
                anomaly_score = await self.data_pipeline.detect_prediction_anomalies({
                    'noise_analysis': noise_analysis,
                    'signal_analysis': signal_analysis
                })
                pipeline_metrics['anomaly_score'] = anomaly_score
            else:
                # Internal pipeline validation
                pipeline_metrics = self._perform_internal_pipeline_validation(
                    noise_analysis, signal_analysis
                )
            
            return pipeline_metrics
            
        except Exception as e:
            logging.error(f"Error validating against data pipeline: {e}")
