    def _combine_metrics_with_uncertainty(self, prediction_metrics: Dict, 
                                        model_validation_metrics: Dict, 
                                        pipeline_validation_metrics: Dict) -> Dict:
        """Combine all metrics with comprehensive uncertainty quantification"""
        try:
            combined_metrics = {}
            
            # Weighted ensemble of all accuracy metrics
            accuracy_sources = [
                ('prediction', prediction_metrics.get('absolute_accuracy', 0.5), 0.4),
                ('model_validation', model_validation_metrics.get('cross_validation_score', 0.5), 0.35),
                ('pipeline_validation', pipeline_validation_metrics.get('pipeline_validation_score', 0.5), 0.25)
            ]
            
            # Calculate weighted accuracy with uncertainty propagation
            weighted_accuracy = 0.0
            total_weight = 0.0
            accuracy_variance = 0.0
            
            for source, accuracy, weight in accuracy_sources:
                if accuracy > 0:  # Only include valid metrics
                    weighted_accuracy += accuracy * weight
                    total_weight += weight
                    
                    # Propagate uncertainty based on source reliability
                    source_uncertainty = self._estimate_source_uncertainty(source, accuracy)
                    accuracy_variance += (weight * source_uncertainty) ** 2
            
            if total_weight > 0:
                combined_metrics['weighted_accuracy'] = weighted_accuracy / total_weight
                combined_metrics['accuracy_uncertainty'] = np.sqrt(accuracy_variance) / total_weight
            else:
                combined_metrics['weighted_accuracy'] = 0.5
                combined_metrics['accuracy_uncertainty'] = 0.3
            
            # Epistemic uncertainty (model uncertainty)
            epistemic_uncertainty = self._calculate_epistemic_uncertainty(
                prediction_metrics, model_validation_metrics
            )
            combined_metrics['epistemic_uncertainty'] = epistemic_uncertainty
            
            # Aleatoric uncertainty (data uncertainty)
            aleatoric_uncertainty = self._calculate_aleatoric_uncertainty(
                pipeline_validation_metrics
            )
            combined_metrics['aleatoric_uncertainty'] = aleatoric_uncertainty
            
            # Total uncertainty
            combined_metrics['total_uncertainty'] = np.sqrt(
                epistemic_uncertainty**2 + aleatoric_uncertainty**2
            )
            
            # Reliability score combining accuracy and uncertainty
            combined_metrics['reliability_score'] = (
                combined_metrics['weighted_accuracy'] * 
                (1.0 - combined_metrics['total_uncertainty'])
            )
            
            # Confidence intervals
            accuracy = combined_metrics['weighted_accuracy']
            uncertainty = combined_metrics['total_uncertainty']
            combined_metrics['confidence_intervals'] = {
                '68%': (max(0, accuracy - uncertainty), min(1, accuracy + uncertainty)),
                '95%': (max(0, accuracy - 2*uncertainty), min(1, accuracy + 2*uncertainty))
            }
            
            return combined_metrics
            
        except Exception as e:
            logging.error(f"Error combining metrics with uncertainty: {e}")
            return {'weighted_accuracy': 0.5, 'total_uncertainty': 0.3}
    
    def _update_comprehensive_performance_tracking(self, combined_metrics: Dict):
        """Update comprehensive performance tracking with temporal analysis"""
        try:
            current_time = datetime.now()
            
            # Update main performance metrics
            for metric_name, value in combined_metrics.items():
                if isinstance(value, (int, float)):
                    if metric_name not in self.performance_metrics:
                        self.performance_metrics[metric_name] = {'mean': value, 'history': []}
                    
                    # Exponential moving average update
                    alpha = 0.1  # Smoothing factor
                    current_mean = self.performance_metrics[metric_name].get('mean', value)
                    self.performance_metrics[metric_name]['mean'] = (
                        alpha * value + (1 - alpha) * current_mean
                    )
                    
                    # Track history for trend analysis
                    self.performance_metrics[metric_name]['history'].append({
                        'timestamp': current_time,
                        'value': value
                    })
                    
                    # Limit history to last 1000 entries
                    if len(self.performance_metrics[metric_name]['history']) > 1000:
                        self.performance_metrics[metric_name]['history'] = \
                            self.performance_metrics[metric_name]['history'][-1000:]
            
            # Update metrics history for trend analysis
            self.metrics_history['timestamps'].append(current_time)
            self.metrics_history['accuracy_evolution'].append(
                combined_metrics.get('weighted_accuracy', 0.5)
            )
            self.metrics_history['confidence_evolution'].append(
                combined_metrics.get('reliability_score', 0.5)
            )
            
            # Limit history size
            if len(self.metrics_history['timestamps']) > 1000:
                for key in self.metrics_history:
                    if isinstance(self.metrics_history[key], list):
                        self.metrics_history[key] = self.metrics_history[key][-1000:]
            
            # Detect performance trends
            self._detect_performance_trends(combined_metrics)
            
        except Exception as e:
            logging.error(f"Error updating comprehensive performance tracking: {e}")
    
    def _perform_statistical_significance_analysis(self, combined_metrics: Dict):
        """Perform statistical significance testing on metrics"""
        try:
            # Ensure sufficient data for statistical analysis
            if len(self.metrics_history['accuracy_evolution']) < 10:
                return
            
            recent_accuracy = self.metrics_history['accuracy_evolution'][-10:]
            historical_accuracy = self.metrics_history['accuracy_evolution'][:-10] if len(
                self.metrics_history['accuracy_evolution']) > 10 else []
            
            if len(historical_accuracy) < 5:
                return
            
            # Statistical tests for performance changes
            from scipy import stats
            
            # T-test for mean accuracy change
            if len(historical_accuracy) >= 5 and len(recent_accuracy) >= 5:
                t_stat, p_value = stats.ttest_ind(recent_accuracy, historical_accuracy)
                
                self.performance_metrics['statistical_tests'] = {
                    'accuracy_t_test': {
                        't_statistic': float(t_stat),
                        'p_value': float(p_value),
                        'significant_change': p_value < 0.05,
                        'improvement': np.mean(recent_accuracy) > np.mean(historical_accuracy)
                    }
                }
            
            # Trend analysis using linear regression
            if len(self.metrics_history['accuracy_evolution']) >= 20:
                x = np.arange(len(self.metrics_history['accuracy_evolution']))
                y = np.array(self.metrics_history['accuracy_evolution'])
                
                slope, intercept, r_value, p_value, std_err = stats.linregress(x, y)
                
                self.performance_metrics['trend_analysis'] = {
                    'slope': float(slope),
                    'r_squared': float(r_value**2),
                    'p_value': float(p_value),
                    'trend_significant': p_value < 0.05,
                    'trend_direction': 'improving' if slope > 0 else 'declining' if slope < 0 else 'stable'
                }
            
        except Exception as e:
            logging.error(f"Error performing statistical significance analysis: {e}")
    
    def _update_advanced_classification_confidence(self):
        """Update classification confidence with ensemble validation"""
        try:
            # Ensemble confidence from multiple sources
            confidence_sources = []
            
            # Source probability confidence
            if self.source_probabilities:
                max_source_prob = max(self.source_probabilities.values())
                entropy = -sum(p * np.log(p + 1e-10) for p in self.source_probabilities.values() if p > 0)
                normalized_entropy = entropy / np.log(len(self.source_probabilities))
                confidence_sources.append({
                    'source': 'probability_based',
                    'confidence': max_source_prob,
                    'uncertainty': normalized_entropy,
                    'weight': 0.4
                })
            
            # Model validation confidence
            if 'model_validation' in self.performance_metrics:
                model_confidence = self.performance_metrics['model_validation'].get('cross_validation_score', 0.5)
                confidence_sources.append({
                    'source': 'model_validation',
                    'confidence': model_confidence,
                    'uncertainty': 1.0 - model_confidence,
                    'weight': 0.35
                })
            
            # Data pipeline confidence
            if 'data_quality_metrics' in self.performance_metrics:
                data_quality = self.performance_metrics['data_quality_metrics']
                pipeline_confidence = np.mean([
                    data_quality.get('completeness', 0.5),
                    data_quality.get('consistency', 0.5),
                    data_quality.get('validity', 0.5)
                ])
                confidence_sources.append({
                    'source': 'data_pipeline',
                    'confidence': pipeline_confidence,
                    'uncertainty': 1.0 - pipeline_confidence,
                    'weight': 0.25
                })
            
            # Calculate weighted ensemble confidence
            if confidence_sources:
                total_weight = sum(source['weight'] for source in confidence_sources)
                weighted_confidence = sum(
                    source['confidence'] * source['weight'] 
                    for source in confidence_sources
                ) / total_weight
                
                weighted_uncertainty = sum(
                    source['uncertainty'] * source['weight'] 
                    for source in confidence_sources
                ) / total_weight
                
                # Update classification confidence metrics
                self.performance_metrics['classification_confidence'] = {
                    'ensemble_mean': weighted_confidence,
                    'ensemble_uncertainty': weighted_uncertainty,
                    'individual_sources': {
                        source['source']: {
                            'confidence': source['confidence'],
                            'uncertainty': source['uncertainty'],
                            'weight': source['weight']
                        } for source in confidence_sources
                    },
                    'confidence_score': weighted_confidence * (1.0 - weighted_uncertainty)
                }
            else:
                # Fallback confidence
                self.performance_metrics['classification_confidence'] = {
                    'ensemble_mean': 0.5,
                    'ensemble_uncertainty': 0.3,
                    'confidence_score': 0.35
                }
            
        except Exception as e:
            logging.error(f"Error updating advanced classification confidence: {e}")
            # Fallback to simple confidence
            if self.source_probabilities:
                max_prob = max(self.source_probabilities.values())
                self.performance_metrics['classification_confidence'] = {
                    'ensemble_mean': max_prob,
                    'confidence_score': max_prob
                }
    
    def _update_fallback_performance_metrics(self, noise_analysis: Dict, signal_analysis: Dict):
        """Fallback simplified performance metrics update"""
        try:
            # Basic prediction accuracy (fallback)
            if 'level' in noise_analysis and 'level' in signal_analysis:
                prediction_error = abs(noise_analysis['level'] - signal_analysis['level'])
                accuracy = 1.0 / (1.0 + prediction_error)
                self.performance_metrics['prediction_accuracy'] = \
                    0.9 * self.performance_metrics.get('prediction_accuracy', 0.5) + 0.1 * accuracy
                    
            # Basic classification confidence
            max_source_prob = max(self.source_probabilities.values()) if self.source_probabilities else 0.5
            self.performance_metrics['classification_confidence'] = max_source_prob
            
        except Exception as e:
            logging.error(f"Error in fallback performance metrics: {e}")
    
