    async def _fetch_usgs_data(self, bbox: List[float], url_template: str) -> Optional[np.ndarray]:
        """Fetch real USGS 3DEP elevation data"""
        try:
            if not self.data_connector:
                return self._generate_realistic_dem(bbox, resolution_m=10, terrain_type='continental')
            
            # USGS 3D Elevation Program (3DEP) Web Coverage Service
            wcs_url = "https://elevation.nationalmap.gov/arcgis/services/3DEPElevation/ImageServer/WCSServer"
            
            # Convert bbox to proper CRS format
            west, south, east, north = bbox
            
            params = {
                'SERVICE': 'WCS',
                'VERSION': '2.0.1', 
                'REQUEST': 'GetCoverage',
                'COVERAGEID': '3DEPElevation',
                'SUBSET': [f'Long({west},{east})', f'Lat({south},{north})'],
                'FORMAT': 'GeoTIFF',
                'OUTPUTCRS': 'EPSG:4326'
            }
            
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=60)) as session:
                async with session.get(wcs_url, params=params) as response:
                    if response.status == 200:
                        # Read the GeoTIFF data
                        geotiff_data = await response.read()
                        
                        # Save temporarily and read with rasterio if available
                        try:
                            import rasterio
                            import tempfile
                            
                            with tempfile.NamedTemporaryFile(suffix='.tiff') as tmp_file:
                                tmp_file.write(geotiff_data)
                                tmp_file.flush()
                                
                                with rasterio.open(tmp_file.name) as src:
                                    elevation_data = src.read(1)
                                    return elevation_data
                                    
                        except ImportError:
                            # Fallback if rasterio not available
                            logging.warning("rasterio not available, using simulated DEM")
                            return self._generate_realistic_dem(bbox, resolution_m=10, terrain_type='continental')
                    else:
                        logging.warning(f"USGS 3DEP request failed: {response.status}")
                        return self._generate_realistic_dem(bbox, resolution_m=10, terrain_type='continental')
                        
        except Exception as e:
            logging.warning(f"USGS data fetch failed: {e}")
            return self._generate_realistic_dem(bbox, resolution_m=10, terrain_type='continental')
    
