    def _query_usgs_geology(self, lat: float, lon: float) -> Optional[Dict]:
        """Query USGS geological data APIs"""
        try:
            import requests
            
            # USGS GeoDataPortal API
            base_url = "https://cida.usgs.gov/gdp/process/WebProcessingService"
            
            params = {
                'service': 'WPS',
                'version': '1.0.0',
                'request': 'Execute',
                'identifier': 'gov.usgs.cida.gdp.wps.algorithm.FeatureWeightedGridStatisticsAlgorithm',
                'DataInputs': f'FEATURE_COLLECTION=POINT({lon} {lat})'
            }
            
            response = requests.get(base_url, params=params, timeout=10)
            if response.status_code == 200:
                return self._parse_usgs_geological_response(response.text)
                
        except Exception as e:
            print(f"USGS geology query error: {e}")
        return None
    
    def _query_onegeology(self, lat: float, lon: float) -> Optional[Dict]:
        """Query OneGeology global geological portal"""
        try:
            import requests
            
            # OneGeology WFS service
            base_url = "https://portal.onegeology.org/OnegeologyGlobal/wfs"
            
            params = {
                'service': 'WFS',
                'version': '2.0.0',
                'request': 'GetFeature',
                'typeName': 'OneG:geology_5M',
                'outputFormat': 'application/json',
                'cql_filter': f'INTERSECTS(geom, POINT({lon} {lat}))'
            }
            
            response = requests.get(base_url, params=params, timeout=15)
            if response.status_code == 200:
                return self._parse_onegeology_response(response.json())
                
        except Exception as e:
            print(f"OneGeology query error: {e}")
        return None
    
