    def _classify_error_type(self, error: str) -> str:
        """Classify error type for enhanced logging"""
        error_lower = error.lower()
        if 'connection' in error_lower or 'timeout' in error_lower:
            return 'connection_error'
        elif 'database' in error_lower or 'query' in error_lower:
            return 'database_error'
        elif 'memory' in error_lower:
            return 'memory_error'
        else:
            return 'unknown_error'
    
    def _assess_error_severity(self, error: str) -> str:
        """Assess error severity level"""
        critical_keywords = ['critical', 'fatal', 'crash', 'corruption']
        high_keywords = ['failed', 'error', 'exception', 'timeout']
        
        error_lower = error.lower()
        if any(keyword in error_lower for keyword in critical_keywords):
            return 'critical'
        elif any(keyword in error_lower for keyword in high_keywords):
            return 'high'
        else:
            return 'medium'
    
    def _generate_error_resolution(self, error: str) -> str:
        """Generate error resolution suggestions"""
        error_type = self._classify_error_type(error)
        resolutions = {
            'connection_error': 'Check network connectivity and database availability',
            'database_error': 'Verify database schema and query syntax',
            'memory_error': 'Increase available memory or optimize data processing',
            'unknown_error': 'Review logs and system state for more information'
        }
        return resolutions.get(error_type, 'Contact system administrator')
    
    def _get_memory_usage(self) -> Dict:
        """Get current memory usage statistics"""
        try:
            import psutil
            process = psutil.Process()
            memory_info = process.memory_info()
            return {
                'rss_mb': memory_info.rss / 1024 / 1024,
                'vms_mb': memory_info.vms / 1024 / 1024,
                'percent': process.memory_percent()
            }
        except Exception:
            return {'rss_mb': 0, 'vms_mb': 0, 'percent': 0}

