    # Additional helper methods for geological data processing
    
    def _determine_geological_region(self, lat: float, lon: float) -> str:
        """Determine geological region for specialized database queries"""
        if 25 <= lat <= 83 and -170 <= lon <= -50:
            return 'north_america'
        elif 35 <= lat <= 71 and -10 <= lon <= 70:
            return 'europe'
        elif -44 <= lat <= -10 and 112 <= lon <= 154:
            return 'australia'
        elif -35 <= lat <= 5 and -82 <= lon <= -35:
            return 'south_america'
        elif 5 <= lat <= 75 and 60 <= lon <= 180:
            return 'asia'
        else:
            return 'global'
    
