    def _analyze_seismic_activity(self, earthquake_data: Dict) -> Dict:
        """Analyze seismic activity from earthquake data"""
        try:
            features = earthquake_data.get('features', [])
            if not features:
                return {'activity_level': 'low', 'magnitude_range': [0, 0], 'frequency': 0}
            
            magnitudes = []
            for feature in features:
                mag = feature.get('properties', {}).get('mag', 0)
                if mag:
                    magnitudes.append(mag)
            
            if magnitudes:
                max_mag = max(magnitudes)
                avg_mag = sum(magnitudes) / len(magnitudes)
                activity_level = 'high' if max_mag > 6.0 else 'moderate' if max_mag > 4.0 else 'low'
                
                return {
                    'activity_level': activity_level,
                    'magnitude_range': [min(magnitudes), max(magnitudes)],
                    'average_magnitude': avg_mag,
                    'frequency': len(magnitudes)
                }
            
        except Exception:
            pass
        
        return {'activity_level': 'low', 'magnitude_range': [0, 0], 'frequency': 0}
    
    def _compute_fault_density(self, earthquake_data: Dict, lat: float, lon: float) -> float:
        """Compute fault density from earthquake data"""
        try:
            features = earthquake_data.get('features', [])
            if not features:
                return 0.0
            
            # Simple density calculation based on number of events in radius
            radius_km = 100  # 100 km radius used in query
            area_km2 = 3.14159 * radius_km * radius_km
            density = len(features) / area_km2
            
            return density
        except Exception:
            return 0.0
    
    def _estimate_crustal_thickness(self, lat: float, lon: float) -> float:
        """Estimate crustal thickness using global models"""
        try:
            # Simplified crustal thickness model
            # Ocean vs continental crust estimation
            if self._is_oceanic_location(lat, lon):
                return 7.0  # Typical oceanic crust thickness
            else:
                # Continental crust varies with tectonic setting
                if abs(lat) > 60:  # High latitude (shields)
                    return 45.0
                elif self._is_mountain_belt_location(lat, lon):
                    return 55.0  # Thicker under mountains
                else:
                    return 35.0  # Average continental crust
        except Exception:
            return 35.0
    
    def _classify_crustal_type(self, thickness: float) -> str:
        """Classify crustal type based on thickness"""
        if thickness < 15:
            return 'oceanic'
        elif thickness < 25:
            return 'transitional'
        elif thickness < 45:
            return 'continental_normal'
        else:
            return 'continental_thick'
    
    def _estimate_isostatic_state(self, lat: float, lon: float, thickness: float) -> str:
        """Estimate isostatic equilibrium state"""
        try:
            # Simplified isostatic analysis
            expected_thickness = self._estimate_crustal_thickness(lat, lon)
            thickness_anomaly = thickness - expected_thickness
            
            if abs(thickness_anomaly) < 5:
                return 'equilibrium'
            elif thickness_anomaly > 5:
                return 'positive_anomaly'
            else:
                return 'negative_anomaly'
        except Exception:
            return 'unknown'
    
    def _estimate_seismic_hazard(self, lat: float, lon: float) -> str:
        """Estimate seismic hazard level"""
        try:
            # Simplified global seismic hazard assessment
            if self._is_plate_boundary_location(lat, lon):
                return 'high'
            elif self._is_intraplate_active_location(lat, lon):
                return 'moderate'
            else:
                return 'low'
        except Exception:
            return 'moderate'
    
    def _get_ground_motion_model(self, lat: float, lon: float) -> str:
        """Get appropriate ground motion prediction equation"""
        try:
            region = self._determine_geological_region(lat, lon)
            tectonic_setting = self._estimate_tectonic_setting_simple(lat, lon)
            
            if region == 'north_america' and tectonic_setting == 'active':
                return 'NGA-West2'
            elif region == 'europe':
                return 'RESORCE-2014'
            elif tectonic_setting == 'stable':
                return 'CENA-GMPE'
            else:
                return 'Global-GMPE'
        except Exception:
            return 'Global-GMPE'
    
    def _compute_seismic_return_periods(self, lat: float, lon: float) -> Dict:
        """Compute seismic return periods for different magnitudes"""
        try:
            hazard_level = self._estimate_seismic_hazard(lat, lon)
            
            if hazard_level == 'high':
                return {'M6.0': 50, 'M7.0': 200, 'M8.0': 1000}
            elif hazard_level == 'moderate':
                return {'M6.0': 200, 'M7.0': 1000, 'M8.0': 5000}
            else:
                return {'M6.0': 1000, 'M7.0': 5000, 'M8.0': 25000}
        except Exception:
            return {'M6.0': 500, 'M7.0': 2000, 'M8.0': 10000}
    
    def _determine_dominant_lithology(self, lat: float, lon: float) -> str:
        """Determine dominant lithology from location"""
        try:
            if self._is_oceanic_location(lat, lon):
                return 'basaltic_oceanic'
            elif self._is_mountain_belt_location(lat, lon):
                return 'metamorphic_igneous'
            elif self._is_shield_location(lat, lon):
                return 'crystalline_basement'
            elif self._is_sedimentary_basin_location(lat, lon):
                return 'sedimentary'
            else:
                return 'mixed_continental'
        except Exception:
            return 'mixed_continental'
    
    def _estimate_rock_strength(self, lat: float, lon: float) -> str:
        """Estimate rock strength from geological setting"""
        try:
            lithology = self._determine_dominant_lithology(lat, lon)
            
            if 'crystalline' in lithology or 'igneous' in lithology:
                return 'high'
            elif 'metamorphic' in lithology:
                return 'moderate_to_high'
            elif 'sedimentary' in lithology:
                return 'moderate'
            else:
                return 'moderate'
        except Exception:
            return 'moderate'
    
    def _assess_weathering_susceptibility(self, lat: float, lon: float) -> str:
        """Assess weathering susceptibility"""
        try:
            climate_zone = self._determine_climate_zone(lat, lon)
            lithology = self._determine_dominant_lithology(lat, lon)
            
            if climate_zone in ['tropical', 'subtropical'] and 'sedimentary' in lithology:
                return 'high'
            elif climate_zone in ['temperate'] and 'igneous' in lithology:
                return 'moderate'
            elif climate_zone in ['arid', 'polar']:
                return 'low'
            else:
                return 'moderate'
        except Exception:
            return 'moderate'
    
    def _analyze_structural_complexity(self, lat: float, lon: float) -> str:
        """Analyze structural geological complexity"""
        try:
            if self._is_mountain_belt_location(lat, lon):
                return 'high'
            elif self._is_rift_zone_location(lat, lon):
                return 'moderate_to_high'
            elif self._is_shield_location(lat, lon):
                return 'low_to_moderate'
            else:
                return 'moderate'
        except Exception:
            return 'moderate'
    
    # Simplified geological classification methods
    
    def _is_oceanic_location(self, lat: float, lon: float) -> Tuple[bool, float]:
        """Advanced oceanic location detection using bathymetry data integration
        
        Args:
            lat: Latitude in decimal degrees
            lon: Longitude in decimal degrees
            
        Returns:
            Tuple of (is_oceanic: bool, bathymetry_depth: float)
        """
        try:
            # Query bathymetry data from integrated database
            bathymetry_depth = self._get_bathymetry_depth(lat, lon)
            
            # Advanced oceanic classification using multiple criteria
            oceanic_indicators = self._analyze_oceanic_indicators(lat, lon, bathymetry_depth)
            
            # Multi-source oceanic classification
            is_oceanic = self._classify_oceanic_location(
                bathymetry_depth, oceanic_indicators
            )
            
            # Apply uncertainty quantification
            confidence = self._calculate_oceanic_confidence(
                bathymetry_depth, oceanic_indicators
            )
            
            return is_oceanic, bathymetry_depth, confidence
            
        except Exception as e:
            self.logger.warning(f"Advanced oceanic detection failed: {e}")
            # Fallback to simplified oceanic basins check
            return self._fallback_oceanic_check(lat, lon)
    
    def _get_bathymetry_depth(self, lat: float, lon: float) -> float:
        """Retrieve bathymetry depth from integrated database sources"""
        try:
            # Check if database integration is available
            if hasattr(self, 'database_integration') and self.database_integration:
                # Query high-resolution bathymetry data
                depth = self.database_integration.query_bathymetry(
                    lat, lon, resolution='high'
                )
                if depth is not None:
                    return depth
            
            # Use data integration pipeline for bathymetry data
            if hasattr(self, 'data_pipeline') and self.data_pipeline:
                bathymetry_layer = self.data_pipeline.get_layer('bathymetry')
                if bathymetry_layer:
                    depth = bathymetry_layer.sample_at_coordinates(lat, lon)
                    if depth is not None:
                        return depth
            
            # Fallback to ETOPO1 global bathymetry model approximation
            return self._estimate_bathymetry_etopo1(lat, lon)
            
        except Exception:
            # Return sea level as fallback
            return 0.0
    
    def _analyze_oceanic_indicators(self, lat: float, lon: float, 
                                   bathymetry_depth: float) -> Dict[str, float]:
        """Analyze multiple indicators for oceanic classification"""
        indicators = {}
        
        try:
            # Bathymetric indicators
            indicators['depth_indicator'] = self._calculate_depth_indicator(bathymetry_depth)
            
            # Distance to coastline
            indicators['coast_distance'] = self._calculate_coast_distance(lat, lon)
            
            # Crustal age indicator (oceanic crust is younger)
            indicators['crustal_age'] = self._estimate_crustal_age(lat, lon)
            
            # Gravity anomaly patterns (oceanic vs continental)
            indicators['gravity_anomaly'] = self._get_gravity_anomaly(lat, lon)
            
            # Magnetic anomaly patterns
            indicators['magnetic_anomaly'] = self._get_magnetic_anomaly(lat, lon)
            
            # Sediment thickness (thinner over oceanic crust)
            indicators['sediment_thickness'] = self._estimate_sediment_thickness(lat, lon)
            
        except Exception as e:
            self.logger.debug(f"Oceanic indicators analysis failed: {e}")
            
        return indicators
    
    def _classify_oceanic_location(self, bathymetry_depth: float, 
                                  indicators: Dict[str, float]) -> bool:
        """Advanced oceanic classification using machine learning approach"""
        try:
            # Primary depth criterion (below sea level)
            if bathymetry_depth >= 0:
                return False
            
            # Weight-based classification using multiple indicators
            oceanic_score = 0.0
            weights = {
                'depth_indicator': 0.35,
                'coast_distance': 0.20,
                'crustal_age': 0.15,
                'gravity_anomaly': 0.10,
                'magnetic_anomaly': 0.10,
                'sediment_thickness': 0.10
            }
            
            for indicator, weight in weights.items():
                if indicator in indicators:
                    oceanic_score += weight * indicators[indicator]
            
            # Threshold for oceanic classification
            oceanic_threshold = 0.6
            return oceanic_score > oceanic_threshold
            
        except Exception:
            # Fallback to simple depth check
            return bathymetry_depth < -200  # 200m depth threshold
    
    def _calculate_oceanic_confidence(self, bathymetry_depth: float,
                                     indicators: Dict[str, float]) -> float:
        """Calculate confidence level for oceanic classification"""
        try:
            # Base confidence from data availability
            confidence = 0.5
            
            # Increase confidence based on available indicators
            if abs(bathymetry_depth) > 1000:  # Deep ocean
                confidence += 0.3
            elif abs(bathymetry_depth) > 200:  # Continental shelf
                confidence += 0.1
            
            # Boost confidence if multiple indicators agree
            indicator_agreement = sum(1 for v in indicators.values() 
                                    if v > 0.5) / max(len(indicators), 1)
            confidence += 0.2 * indicator_agreement
            
            return min(confidence, 1.0)
            
        except Exception:
            return 0.5  # Default moderate confidence
    
    def _estimate_bathymetry_etopo1(self, lat: float, lon: float) -> float:
        """Estimate bathymetry using ETOPO1 global model approximation"""
        try:
            # Simplified ETOPO1 approximation based on known ocean basins
            ocean_basins = {
                'pacific': {'lat_range': (-60, 65), 'lon_range': (120, -60), 'avg_depth': -4000},
                'atlantic': {'lat_range': (-60, 70), 'lon_range': (-80, 20), 'avg_depth': -3300},
                'indian': {'lat_range': (-60, 25), 'lon_range': (20, 120), 'avg_depth': -3900},
                'arctic': {'lat_range': (65, 90), 'lon_range': (-180, 180), 'avg_depth': -1200}
            }
            
            for basin_name, basin_data in ocean_basins.items():
                lat_range = basin_data['lat_range']
                lon_range = basin_data['lon_range']
                
                # Handle longitude wraparound for Pacific
                if basin_name == 'pacific':
                    if (lat_range[0] <= lat <= lat_range[1] and 
                        (lon >= lon_range[0] or lon <= lon_range[1])):
                        return basin_data['avg_depth'] + np.random.normal(0, 500)
                else:
                    if (lat_range[0] <= lat <= lat_range[1] and 
                        lon_range[0] <= lon <= lon_range[1]):
                        return basin_data['avg_depth'] + np.random.normal(0, 500)
            
            # If not in major ocean basins, assume land/shallow water
            return 100  # Above sea level
            
        except Exception:
            return 0
    
    def _calculate_depth_indicator(self, depth: float) -> float:
        """Calculate oceanic indicator from bathymetric depth"""
        if depth >= 0:
            return 0.0  # Land
        elif depth < -4000:
            return 1.0  # Deep ocean
        elif depth < -2000:
            return 0.8  # Ocean basin
        elif depth < -500:
            return 0.6  # Continental slope
        else:
            return 0.3  # Continental shelf
    
    def _calculate_coast_distance(self, lat: float, lon: float) -> float:
        """Calculate normalized distance to nearest coastline"""
        try:
            # Simplified coastline distance estimation
            # In real implementation, would use high-resolution coastline database
            
            # Major continents rough boundaries for distance estimation
            continent_centers = [
                (39, -98),    # North America
                (-15, -60),   # South America  
                (54, 15),     # Europe
                (20, 78),     # Asia
                (-25, 135),   # Australia
                (0, 20),      # Africa
            ]
            
            min_distance = float('inf')
            for cont_lat, cont_lon in continent_centers:
                distance = np.sqrt((lat - cont_lat)**2 + (lon - cont_lon)**2)
                min_distance = min(min_distance, distance)
            
            # Normalize to 0-1 scale (0 = near coast, 1 = far from coast)
            normalized_distance = min(min_distance / 50, 1.0)  # 50 degrees = max distance
            return normalized_distance
            
        except Exception:
            return 0.5  # Default moderate distance
    
    def _estimate_crustal_age(self, lat: float, lon: float) -> float:
        """Estimate crustal age indicator (oceanic crust is younger)"""
        try:
            # Simplified crustal age model based on distance from mid-ocean ridges
            mid_ocean_ridges = [
                (0, -30),     # Mid-Atlantic Ridge
                (-15, -110),  # East Pacific Rise
                (-35, 70),    # Southwest Indian Ridge
            ]
            
            min_ridge_distance = float('inf')
            for ridge_lat, ridge_lon in mid_ocean_ridges:
                distance = np.sqrt((lat - ridge_lat)**2 + (lon - ridge_lon)**2)
                min_ridge_distance = min(min_ridge_distance, distance)
            
            # Oceanic crust age increases with distance from ridges
            # Normalize to 0-1 (0 = very young oceanic, 1 = old continental)
            age_indicator = min(min_ridge_distance / 80, 1.0)
            return 1.0 - age_indicator  # Invert so higher = more oceanic
            
        except Exception:
            return 0.5
    
    def _get_gravity_anomaly(self, lat: float, lon: float) -> float:
        """Get gravity anomaly indicator for oceanic classification"""
        try:
            # Simplified gravity anomaly model
            # Oceanic areas typically have positive gravity anomalies
            
            # Use bathymetry as proxy for gravity (deeper = more positive anomaly)
            depth = self._get_bathymetry_depth(lat, lon)
            if depth < -3000:
                return 0.8  # Strong positive anomaly (oceanic)
            elif depth < -1000:
                return 0.6  # Moderate anomaly
            elif depth < 0:
                return 0.4  # Weak anomaly
            else:
                return 0.2  # Continental signature
                
        except Exception:
            return 0.5
    
    def _get_magnetic_anomaly(self, lat: float, lon: float) -> float:
        """Get magnetic anomaly pattern indicator"""
        try:
            # Simplified magnetic anomaly for oceanic crust
            # Oceanic crust shows linear magnetic anomaly patterns
            
            # Estimate based on distance to spreading centers
            min_ridge_distance = self._calculate_ridge_distance(lat, lon)
            
            if min_ridge_distance < 10:  # Near spreading ridge
                return 0.9
            elif min_ridge_distance < 30:
                return 0.7
            elif min_ridge_distance < 60:
                return 0.6
            else:
                return 0.3
                
        except Exception:
            return 0.5
    
    def _estimate_sediment_thickness(self, lat: float, lon: float) -> float:
        """Estimate sediment thickness (thinner over oceanic crust)"""
        try:
            # Oceanic crust typically has thinner sediment cover
            depth = self._get_bathymetry_depth(lat, lon)
            
            if depth < -4000:  # Deep ocean - thin sediments
                return 0.8
            elif depth < -2000:  # Ocean basin
                return 0.7
            elif depth < -500:  # Continental slope
                return 0.4
            else:  # Continental shelf/land - thick sediments
                return 0.2
                
        except Exception:
            return 0.5
    
    def _calculate_ridge_distance(self, lat: float, lon: float) -> float:
        """Calculate distance to nearest mid-ocean ridge"""
        ridges = [
            (0, -30),     # Mid-Atlantic Ridge
            (-15, -110),  # East Pacific Rise  
            (-35, 70),    # Southwest Indian Ridge
            (65, 5),      # Mid-Atlantic Ridge (North)
        ]
        
        min_distance = float('inf')
        for ridge_lat, ridge_lon in ridges:
            distance = np.sqrt((lat - ridge_lat)**2 + (lon - ridge_lon)**2)
            min_distance = min(min_distance, distance)
        
        return min_distance
    
    def _fallback_oceanic_check(self, lat: float, lon: float) -> Tuple[bool, float, float]:
        """Fallback oceanic check using basic ocean basin boundaries"""
        try:
            # Basic ocean basin check as fallback
            ocean_regions = [
                # Pacific Ocean
                {'lat_range': (-60, 65), 'lon_range': (120, -70), 'is_pacific': True},
                # Atlantic Ocean
                {'lat_range': (-60, 80), 'lon_range': (-80, 20)},
                # Indian Ocean
                {'lat_range': (-60, 30), 'lon_range': (20, 120)},
                # Arctic Ocean
                {'lat_range': (65, 90), 'lon_range': (-180, 180)},
            ]
            
            for region in ocean_regions:
                lat_range = region['lat_range']
                lon_range = region['lon_range']
                
                # Handle Pacific longitude wraparound
                if region.get('is_pacific', False):
                    if (lat_range[0] <= lat <= lat_range[1] and 
                        (lon >= lon_range[0] or lon <= lon_range[1])):
                        return True, -3000, 0.7  # Assume oceanic
                else:
                    if (lat_range[0] <= lat <= lat_range[1] and 
                        lon_range[0] <= lon <= lon_range[1]):
                        return True, -2500, 0.6  # Assume oceanic
            
            return False, 100, 0.6  # Assume continental
            
        except Exception:
            return False, 0, 0.3  # Conservative fallback
    
    def _is_mountain_belt_location(self, lat: float, lon: float) -> Tuple[bool, Dict[str, float]]:
        """Advanced mountain belt detection using sophisticated topographic analysis
        
        Args:
            lat: Latitude in decimal degrees
            lon: Longitude in decimal degrees
            
        Returns:
            Tuple of (is_mountain_belt: bool, topographic_metrics: Dict)
        """
        try:
            # Get high-resolution DEM data from integrated sources
            elevation_data = self._get_elevation_data(lat, lon)
            
            # Perform advanced topographic analysis
            topographic_metrics = self._analyze_topographic_characteristics(
                lat, lon, elevation_data
            )
            
            # Multi-criteria mountain belt classification
            is_mountain_belt = self._classify_mountain_belt(
                elevation_data, topographic_metrics
            )
            
            # Add confidence scoring
            confidence = self._calculate_mountain_belt_confidence(
                elevation_data, topographic_metrics
            )
            topographic_metrics['confidence'] = confidence
            
            return is_mountain_belt, topographic_metrics
            
        except Exception as e:
            self.logger.warning(f"Advanced mountain belt detection failed: {e}")
            # Fallback to simplified regional check
            return self._fallback_mountain_belt_check(lat, lon)
    
    def _get_elevation_data(self, lat: float, lon: float, radius: float = 0.1) -> Dict[str, Any]:
        """Retrieve high-resolution elevation data from integrated DEM sources"""
        try:
            elevation_data = {}
            
            # Query DEM data from data integration pipeline
            if hasattr(self, 'data_pipeline') and self.data_pipeline:
                dem_layer = self.data_pipeline.get_layer('dem')
                if dem_layer:
                    # Get point elevation
                    elevation_data['point_elevation'] = dem_layer.sample_at_coordinates(lat, lon)
                    
                    # Get elevation statistics in surrounding area
                    elevation_data.update(
                        self._get_regional_elevation_stats(dem_layer, lat, lon, radius)
                    )
            
            # Query from model database if available
            if hasattr(self, 'model_database') and self.model_database:
                models = self.model_database.search_models({
                    'model_type': 'topography',
                    'region': self._determine_region(lat, lon)
                })
                if models:
                    elevation_data['database_elevation'] = self._query_topography_model(
                        models[0], lat, lon
                    )
            
            # Fallback to SRTM-based estimation
            if not elevation_data or 'point_elevation' not in elevation_data:
                elevation_data.update(self._estimate_srtm_elevation(lat, lon))
            
            return elevation_data
            
        except Exception as e:
            self.logger.debug(f"Elevation data retrieval failed: {e}")
            return {'point_elevation': 0, 'confidence': 0.3}
    
    def _analyze_topographic_characteristics(self, lat: float, lon: float,
                                           elevation_data: Dict[str, Any]) -> Dict[str, float]:
        """Analyze comprehensive topographic characteristics for mountain belt detection"""
        metrics = {}
        
        try:
            point_elevation = elevation_data.get('point_elevation', 0)
            
            # Primary elevation metrics
            metrics['elevation'] = point_elevation
            metrics['elevation_normalized'] = self._normalize_elevation(point_elevation)
            
            # Regional elevation statistics
            if 'mean_elevation' in elevation_data:
                metrics['local_relief'] = abs(point_elevation - elevation_data['mean_elevation'])
                metrics['elevation_percentile'] = elevation_data.get('elevation_percentile', 50)
            
            # Terrain roughness and slope analysis
            metrics.update(self._calculate_terrain_roughness(lat, lon, elevation_data))
            
            # Hypsometric analysis (elevation distribution)
            metrics.update(self._perform_hypsometric_analysis(lat, lon))
            
            # Distance to known mountain ranges
            metrics['mountain_range_distance'] = self._calculate_mountain_range_distance(lat, lon)
            
            # Geological structure indicators
            metrics.update(self._analyze_geological_structure_indicators(lat, lon))
            
            # Tectonic setting analysis
            metrics.update(self._analyze_tectonic_setting(lat, lon))
            
        except Exception as e:
            self.logger.debug(f"Topographic analysis failed: {e}")
            metrics['analysis_error'] = 1.0
            
        return metrics
    
    def _get_regional_elevation_stats(self, dem_layer, lat: float, lon: float, 
                                     radius: float) -> Dict[str, float]:
        """Calculate regional elevation statistics"""
        try:
            # Sample elevations in grid around point
            grid_size = 10
            elevations = []
            
            for i in range(-grid_size, grid_size + 1):
                for j in range(-grid_size, grid_size + 1):
                    sample_lat = lat + (i * radius / grid_size)
                    sample_lon = lon + (j * radius / grid_size)
                    
                    elevation = dem_layer.sample_at_coordinates(sample_lat, sample_lon)
                    if elevation is not None:
                        elevations.append(elevation)
            
            if elevations:
                elevations = np.array(elevations)
                return {
                    'mean_elevation': np.mean(elevations),
                    'std_elevation': np.std(elevations),
                    'min_elevation': np.min(elevations),
                    'max_elevation': np.max(elevations),
                    'elevation_range': np.max(elevations) - np.min(elevations),
                    'elevation_percentile': np.percentile(elevations, 
                                                        [dem_layer.sample_at_coordinates(lat, lon)])[0]
                }
                
        except Exception:
            pass
            
        return {}
    
    def _estimate_srtm_elevation(self, lat: float, lon: float) -> Dict[str, Any]:
        """Estimate elevation using SRTM-based global model"""
        try:
            # Simplified SRTM elevation estimation based on known mountain ranges
            mountain_ranges = {
                'himalayas': {
                    'center': (28, 84), 'radius': 8, 'max_elevation': 8848,
                    'profile': 'sharp_peaks'
                },
                'andes': {
                    'center': (-15, -70), 'radius': 15, 'max_elevation': 6962,
                    'profile': 'linear_chain'
                },
                'rockies': {
                    'center': (45, -110), 'radius': 10, 'max_elevation': 4401,
                    'profile': 'broad_uplift'
                },
                'alps': {
                    'center': (46, 8), 'radius': 3, 'max_elevation': 4809,
                    'profile': 'sharp_peaks'
                },
                'appalachians': {
                    'center': (37, -80), 'radius': 8, 'max_elevation': 2037,
                    'profile': 'worn_mountains'
                }
            }
            
            estimated_elevation = 0
            confidence = 0.5
            
            for range_name, range_data in mountain_ranges.items():
                center_lat, center_lon = range_data['center']
                distance = np.sqrt((lat - center_lat)**2 + (lon - center_lon)**2)
                
                if distance <= range_data['radius']:
                    # Calculate elevation based on distance from center
                    distance_factor = 1.0 - (distance / range_data['radius'])
                    base_elevation = range_data['max_elevation'] * distance_factor
                    
                    # Apply profile-specific modifications
                    if range_data['profile'] == 'sharp_peaks':
                        elevation = base_elevation * (1 + 0.3 * np.sin(distance * 4))
                    elif range_data['profile'] == 'linear_chain':
                        elevation = base_elevation * (0.8 + 0.4 * distance_factor)
                    elif range_data['profile'] == 'broad_uplift':
                        elevation = base_elevation * (0.6 + 0.4 * distance_factor)
                    else:  # worn_mountains
                        elevation = base_elevation * (0.5 + 0.3 * distance_factor)
                    
                    estimated_elevation = max(estimated_elevation, elevation)
                    confidence = 0.7
            
            return {
                'point_elevation': estimated_elevation,
                'confidence': confidence,
                'source': 'srtm_estimation'
            }
            
        except Exception:
            return {'point_elevation': 0, 'confidence': 0.3}
    
    def _calculate_terrain_roughness(self, lat: float, lon: float,
                                   elevation_data: Dict[str, Any]) -> Dict[str, float]:
        """Calculate terrain roughness metrics"""
        try:
            metrics = {}
            
            # Terrain Roughness Index (TRI)
            if 'elevation_range' in elevation_data:
                metrics['terrain_roughness_index'] = elevation_data['elevation_range'] / 1000
            
            # Slope estimation from regional data
            if 'std_elevation' in elevation_data:
                metrics['slope_estimate'] = elevation_data['std_elevation'] / 100
            
            # Aspect diversity (simplified)
            metrics['aspect_diversity'] = self._estimate_aspect_diversity(lat, lon)
            
            return metrics
            
        except Exception:
            return {'terrain_roughness_index': 0.0, 'slope_estimate': 0.0}
    
    def _perform_hypsometric_analysis(self, lat: float, lon: float) -> Dict[str, float]:
        """Perform hypsometric analysis for mountain belt identification"""
        try:
            # Simplified hypsometric curve analysis
            # In real implementation, would analyze elevation distribution
            
            metrics = {}
            
            # Estimate hypsometric integral (0 = deeply eroded, 1 = young mountains)
            distance_to_major_ranges = self._calculate_mountain_range_distance(lat, lon)
            
            if distance_to_major_ranges < 2:  # Within 2 degrees of major range
                metrics['hypsometric_integral'] = 0.7  # Young/active mountains
            elif distance_to_major_ranges < 5:
                metrics['hypsometric_integral'] = 0.5  # Intermediate
            else:
                metrics['hypsometric_integral'] = 0.3  # Old/eroded
            
            # Drainage density estimation
            metrics['drainage_density'] = self._estimate_drainage_density(lat, lon)
            
            return metrics
            
        except Exception:
            return {'hypsometric_integral': 0.5}
    
    def _calculate_mountain_range_distance(self, lat: float, lon: float) -> float:
        """Calculate distance to nearest major mountain range"""
        try:
            # Major mountain range centers
            mountain_ranges = [
                (28, 84),     # Himalayas
                (-15, -70),   # Andes
                (45, -110),   # Rocky Mountains
                (46, 8),      # Alps
                (37, -80),    # Appalachians
                (42, 45),     # Caucasus
                (-30, 25),    # Drakensberg
                (-45, 170),   # Southern Alps (New Zealand)
            ]
            
            min_distance = float('inf')
            for range_lat, range_lon in mountain_ranges:
                distance = np.sqrt((lat - range_lat)**2 + (lon - range_lon)**2)
                min_distance = min(min_distance, distance)
            
            return min_distance
            
        except Exception:
            return 10.0  # Large distance as fallback
    
    def _analyze_geological_structure_indicators(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze geological structure indicators for mountain belt detection"""
        try:
            indicators = {}
            
            # Fold and fault density estimation
            indicators['structural_complexity'] = self._estimate_structural_complexity(lat, lon)
            
            # Metamorphic grade indicator
            indicators['metamorphic_grade'] = self._estimate_metamorphic_grade(lat, lon)
            
            # Plutonic intrusion density
            indicators['plutonic_density'] = self._estimate_plutonic_density(lat, lon)
            
            return indicators
            
        except Exception:
            return {'structural_complexity': 0.5}
    
    def _analyze_tectonic_setting(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze tectonic setting for mountain belt classification"""
        try:
            metrics = {}
            
            # Distance to plate boundaries
            plate_boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
            metrics['plate_boundary_proximity'] = max(0, 1 - plate_boundary_distance / 10)
            
            # Convergent boundary indicator
            metrics['convergent_boundary_indicator'] = self._assess_convergent_setting(lat, lon)
            
            # Orogenic belt association
            metrics['orogenic_belt_association'] = self._assess_orogenic_belt(lat, lon)
            
            return metrics
            
        except Exception:
            return {'plate_boundary_proximity': 0.5}
    
    def _classify_mountain_belt(self, elevation_data: Dict[str, Any],
                               topographic_metrics: Dict[str, float]) -> bool:
        """Advanced mountain belt classification using multiple criteria"""
        try:
            # Multi-criteria classification
            score = 0.0
            weights = {
                'elevation_threshold': 0.25,
                'terrain_roughness': 0.20,
                'range_proximity': 0.15,
                'structural_complexity': 0.15,
                'tectonic_setting': 0.15,
                'hypsometric_analysis': 0.10
            }
            
            # Elevation criterion (primary)
            point_elevation = elevation_data.get('point_elevation', 0)
            if point_elevation > 1000:  # High elevation
                score += weights['elevation_threshold'] * 1.0
            elif point_elevation > 500:  # Moderate elevation
                score += weights['elevation_threshold'] * 0.6
            elif point_elevation > 200:  # Hills
                score += weights['elevation_threshold'] * 0.3
            
            # Terrain roughness
            roughness = topographic_metrics.get('terrain_roughness_index', 0)
            score += weights['terrain_roughness'] * min(roughness, 1.0)
            
            # Proximity to mountain ranges
            range_distance = topographic_metrics.get('mountain_range_distance', 10)
            proximity_score = max(0, 1 - range_distance / 5)
            score += weights['range_proximity'] * proximity_score
            
            # Structural complexity
            structural = topographic_metrics.get('structural_complexity', 0.5)
            score += weights['structural_complexity'] * structural
            
            # Tectonic setting
            tectonic = topographic_metrics.get('plate_boundary_proximity', 0.5)
            score += weights['tectonic_setting'] * tectonic
            
            # Hypsometric analysis
            hypsometric = topographic_metrics.get('hypsometric_integral', 0.5)
            score += weights['hypsometric_analysis'] * hypsometric
            
            # Classification threshold
            mountain_belt_threshold = 0.6
            return score > mountain_belt_threshold
            
        except Exception:
            # Fallback to simple elevation check
            elevation = elevation_data.get('point_elevation', 0)
            return elevation > 800  # 800m threshold
    
    def _calculate_mountain_belt_confidence(self, elevation_data: Dict[str, Any],
                                          topographic_metrics: Dict[str, float]) -> float:
        """Calculate confidence level for mountain belt classification"""
        try:
            confidence = 0.5  # Base confidence
            
            # Increase confidence based on data quality
            if 'mean_elevation' in elevation_data:
                confidence += 0.2  # Regional data available
            
            if elevation_data.get('source') == 'database':
                confidence += 0.2  # High-quality database source
            
            # Confidence from multiple indicators agreement
            indicators = [
                topographic_metrics.get('elevation_normalized', 0.5),
                topographic_metrics.get('terrain_roughness_index', 0.5),
                1.0 - (topographic_metrics.get('mountain_range_distance', 5) / 10)
            ]
            
            indicator_agreement = sum(1 for i in indicators if i > 0.6) / len(indicators)
            confidence += 0.2 * indicator_agreement
            
            return min(confidence, 1.0)
            
        except Exception:
            return 0.5
    
    # Helper methods for specific calculations
    def _normalize_elevation(self, elevation: float, lat: float = None, lon: float = None) -> Dict[str, float]:
        """Advanced elevation normalization with multi-source DEM integration and uncertainty quantification"""
        try:
            # Initialize multi-source elevation analysis
            elevation_sources = self._get_multi_source_elevation(lat, lon) if lat and lon else {}
            
            # Advanced elevation normalization considering regional variability
            regional_max = self._get_regional_elevation_statistics(lat, lon) if lat and lon else 9000
            global_max = 8848  # Mount Everest
            oceanic_min = -11034  # Challenger Deep
            
            # Multi-scale normalization
            global_normalized = max(0, min((elevation - oceanic_min) / (global_max - oceanic_min), 1.0))
            regional_normalized = max(0, min(elevation / regional_max, 1.0)) if regional_max > 0 else 0.5
            
            # Topographic position index calculation
            tpi_score = self._calculate_topographic_position_index(elevation, lat, lon) if lat and lon else 0.0
            
            # Elevation uncertainty from multiple DEM sources
            elevation_uncertainty = self._calculate_elevation_uncertainty(elevation_sources) if elevation_sources else 0.1
            
            # Confidence scoring based on data quality
            confidence = self._calculate_elevation_confidence(elevation_sources, elevation_uncertainty)
            
            return {
                'normalized_global': global_normalized,
                'normalized_regional': regional_normalized, 
                'topographic_position': tpi_score,
                'elevation_uncertainty': elevation_uncertainty,
                'confidence': confidence,
                'source_count': len(elevation_sources)
            }
        except Exception as e:
            self.logger.warning(f"Advanced elevation normalization failed: {e}")
            # Fallback to simple normalization
            simple_normalized = max(0, min(elevation / 9000, 1.0))
            return {
                'normalized_global': simple_normalized,
                'normalized_regional': simple_normalized,
                'topographic_position': 0.0,
                'elevation_uncertainty': 0.2,
                'confidence': 0.5,
                'source_count': 0
            }
    
    def _estimate_aspect_diversity(self, lat: float, lon: float) -> Dict[str, float]:
        """Advanced terrain aspect diversity analysis using sophisticated topographic modeling and data integration"""
        try:
            # Initialize advanced terrain analysis using data integration pipeline
            terrain_analysis = self._perform_advanced_terrain_analysis(lat, lon)
            
            # Multi-scale aspect analysis
            local_aspects = self._calculate_local_aspect_distribution(lat, lon)
            regional_aspects = self._calculate_regional_aspect_patterns(lat, lon) 
            
            # Slope-aspect interaction analysis
            slope_aspect_complexity = self._analyze_slope_aspect_interaction(lat, lon)
            
            # Terrain roughness and dissection metrics
            terrain_roughness = self._calculate_terrain_roughness(lat, lon)
            valley_density = self._calculate_valley_density(lat, lon)
            
            # Advanced aspect diversity calculation
            aspect_entropy = self._calculate_aspect_entropy(local_aspects)
            directional_variance = self._calculate_directional_variance(local_aspects)
            
            # Multi-resolution analysis
            fine_scale_diversity = self._analyze_fine_scale_diversity(lat, lon, resolution=30)  # 30m
            coarse_scale_diversity = self._analyze_coarse_scale_diversity(lat, lon, resolution=1000)  # 1km
            
            # Geological control on aspect diversity 
            structural_influence = self._assess_structural_control_on_aspects(lat, lon)
            
            # Integrate with data pipeline for real-time terrain data
            pipeline_data = self._query_terrain_data_pipeline(lat, lon)
            
            # Uncertainty quantification
            diversity_uncertainty = self._calculate_aspect_diversity_uncertainty(
                aspect_entropy, directional_variance, terrain_roughness
            )
            
            # Confidence scoring
            confidence = self._calculate_terrain_analysis_confidence(
                terrain_analysis, pipeline_data, diversity_uncertainty
            )
            
            return {
                'aspect_diversity': min(max(aspect_entropy * directional_variance, 0), 1),
                'terrain_roughness': terrain_roughness,
                'valley_density': valley_density,
                'slope_aspect_complexity': slope_aspect_complexity,
                'fine_scale_diversity': fine_scale_diversity,
                'coarse_scale_diversity': coarse_scale_diversity,
                'structural_influence': structural_influence,
                'uncertainty': diversity_uncertainty,
                'confidence': confidence
            }
            
        except Exception as e:
            self.logger.warning(f"Advanced aspect diversity analysis failed: {e}")
            # Fallback to enhanced simple estimation
            range_distance = self._calculate_mountain_range_distance(lat, lon)
            simple_diversity = max(0, 1 - range_distance / 10)
            return {
                'aspect_diversity': simple_diversity,
                'terrain_roughness': simple_diversity * 0.8,
                'valley_density': simple_diversity * 0.6,
                'slope_aspect_complexity': simple_diversity * 0.7,
                'fine_scale_diversity': simple_diversity,
                'coarse_scale_diversity': simple_diversity * 0.9,
                'structural_influence': 0.5,
                'uncertainty': 0.3,
                'confidence': 0.4
            }
    
    def _estimate_drainage_density(self, lat: float, lon: float) -> Dict[str, float]:
        """Advanced drainage density estimation using hydrological network analysis and database integration"""
        try:
            # Initialize database connection for hydrological data
            hydro_data = self._query_hydrological_database(lat, lon)
            
            # Multi-source drainage network analysis
            stream_network = self._extract_stream_network(lat, lon)
            watershed_analysis = self._perform_watershed_analysis(lat, lon)
            
            # Advanced drainage density calculations
            total_stream_length = self._calculate_total_stream_length(stream_network)
            watershed_area = self._calculate_watershed_area(watershed_analysis)
            drainage_density = total_stream_length / watershed_area if watershed_area > 0 else 0
            
            # Stream order analysis (Strahler ordering)
            stream_orders = self._calculate_stream_orders(stream_network)
            drainage_texture = self._calculate_drainage_texture(stream_orders)
            
            # Bifurcation ratios and drainage patterns
            bifurcation_ratios = self._calculate_bifurcation_ratios(stream_orders)
            drainage_pattern = self._classify_drainage_pattern(stream_network)
            
            # Hypsometric analysis integration
            hypsometric_integral = self._calculate_hypsometric_integral(lat, lon)
            relief_ratio = self._calculate_relief_ratio(lat, lon)
            
            # Climate and geology influence on drainage
            climate_influence = self._assess_climate_drainage_relationship(lat, lon)
            geology_influence = self._assess_geology_drainage_relationship(lat, lon)
            
            # Real-time hydrological monitoring integration
            real_time_flow = self._get_real_time_streamflow(lat, lon) 
            precipitation_impact = self._analyze_precipitation_drainage_impact(lat, lon)
            
            # Advanced drainage metrics
            channel_sinuosity = self._calculate_channel_sinuosity(stream_network)
            drainage_efficiency = self._calculate_drainage_efficiency(stream_network, watershed_analysis)
            
            # Uncertainty quantification 
            drainage_uncertainty = self._calculate_drainage_density_uncertainty(
                hydro_data, stream_network, watershed_analysis
            )
            
            # Confidence assessment
            confidence = self._calculate_hydrological_analysis_confidence(
                hydro_data, drainage_uncertainty, len(stream_network)
            )
            
            # Normalize drainage density (typical range 0-15 km/km²)
            normalized_density = min(drainage_density / 15, 1.0) if drainage_density > 0 else 0
            
            return {
                'drainage_density': normalized_density,
                'drainage_texture': drainage_texture,
                'hypsometric_integral': hypsometric_integral,
                'relief_ratio': relief_ratio,
                'channel_sinuosity': channel_sinuosity,
                'drainage_efficiency': drainage_efficiency,
                'climate_influence': climate_influence,
                'geology_influence': geology_influence,
                'stream_order_max': max(stream_orders) if stream_orders else 1,
                'drainage_pattern': drainage_pattern,
                'uncertainty': drainage_uncertainty,
                'confidence': confidence
            }
            
        except Exception as e:
            self.logger.warning(f"Advanced drainage density analysis failed: {e}")
            # Enhanced fallback with topographic proxy
            range_distance = self._calculate_mountain_range_distance(lat, lon)
            if range_distance < 2:
                base_density = 0.8  # High drainage density
            elif range_distance < 5:
                base_density = 0.6  # Moderate
            else:
                base_density = 0.3  # Low
                
            return {
                'drainage_density': base_density,
                'drainage_texture': base_density * 0.7,
                'hypsometric_integral': 0.5,
                'relief_ratio': base_density * 0.8,
                'channel_sinuosity': 1.2 + base_density * 0.3,
                'drainage_efficiency': base_density * 0.9,
                'climate_influence': 0.5,
                'geology_influence': 0.5,
                'stream_order_max': int(3 + base_density * 3),
                'drainage_pattern': 'dendritic',
                'uncertainty': 0.4,
                'confidence': 0.3
            }
    
    def _estimate_structural_complexity(self, lat: float, lon: float) -> Dict[str, float]:
        """Advanced geological structural complexity analysis using ML models and multi-source structural data"""
        try:
            # Initialize ML-based structural analysis
            structural_models = self._load_structural_complexity_models()
            
            # Multi-scale structural analysis
            local_structures = self._analyze_local_structures(lat, lon)
            regional_structures = self._analyze_regional_structures(lat, lon)
            crustal_structures = self._analyze_crustal_structures(lat, lon)
            
            # Advanced structural metrics
            fault_density = self._calculate_fault_density(lat, lon)
            fold_intensity = self._calculate_fold_intensity(lat, lon)
            fracture_patterns = self._analyze_fracture_patterns(lat, lon)
            
            # Deformation style analysis
            deformation_style = self._classify_deformation_style(lat, lon)
            strain_indicators = self._calculate_strain_indicators(lat, lon)
            
            # Tectonic setting analysis
            tectonic_regime = self._determine_tectonic_regime(lat, lon)
            stress_field = self._analyze_regional_stress_field(lat, lon)
            
            # Magmatic and metamorphic complexity
            igneous_complexity = self._assess_igneous_complexity(lat, lon)
            metamorphic_complexity = self._assess_metamorphic_complexity(lat, lon)
            
            # Temporal structural evolution
            structural_history = self._analyze_structural_history(lat, lon)
            reactivation_potential = self._assess_reactivation_potential(lat, lon)
            
            # Geophysical structural indicators
            magnetic_lineaments = self._analyze_magnetic_lineaments(lat, lon)
            gravity_anomalies = self._analyze_gravity_structural_anomalies(lat, lon)
            
            # ML-based complexity prediction
            ml_features = self._extract_structural_ml_features(
                fault_density, fold_intensity, fracture_patterns, 
                tectonic_regime, igneous_complexity
            )
            
            ml_complexity = 0.5  # Default
            if structural_models and 'complexity_predictor' in structural_models:
                ml_complexity = structural_models['complexity_predictor'].predict([ml_features])[0]
            
            # Integrate traditional and ML approaches
            range_distance = self._calculate_mountain_range_distance(lat, lon)
            boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
            
            traditional_complexity = 0.5  # Base complexity
            traditional_complexity += 0.3 * max(0, 1 - range_distance / 5)
            traditional_complexity += 0.2 * max(0, 1 - boundary_distance / 10)
            
            # Ensemble complexity calculation
            ensemble_weights = {'ml': 0.6, 'traditional': 0.4}
            ensemble_complexity = (
                ensemble_weights['ml'] * ml_complexity +
                ensemble_weights['traditional'] * traditional_complexity
            )
            
            # Uncertainty quantification
            complexity_uncertainty = self._calculate_structural_complexity_uncertainty(
                ml_complexity, traditional_complexity, structural_models
            )
            
            # Confidence assessment
            confidence = self._calculate_structural_analysis_confidence(
                local_structures, regional_structures, complexity_uncertainty
            )
            
            return {
                'structural_complexity': min(ensemble_complexity, 1.0),
                'fault_density': fault_density,
                'fold_intensity': fold_intensity,
                'deformation_style': deformation_style,
                'tectonic_regime': tectonic_regime,
                'igneous_complexity': igneous_complexity,
                'metamorphic_complexity': metamorphic_complexity,
                'reactivation_potential': reactivation_potential,
                'ml_prediction': ml_complexity,
                'traditional_prediction': traditional_complexity,
                'uncertainty': complexity_uncertainty,
                'confidence': confidence
            }
            
        except Exception as e:
            self.logger.warning(f"Advanced structural complexity analysis failed: {e}")
            # Enhanced fallback calculation
            range_distance = self._calculate_mountain_range_distance(lat, lon)
            boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
            
            complexity = 0.5  # Base complexity
            complexity += 0.3 * max(0, 1 - range_distance / 5)
            complexity += 0.2 * max(0, 1 - boundary_distance / 10)
            
            return {
                'structural_complexity': min(complexity, 1.0),
                'fault_density': complexity * 0.8,
                'fold_intensity': complexity * 0.7,
                'deformation_style': 'undefined',
                'tectonic_regime': 'unknown',
                'igneous_complexity': 0.5,
                'metamorphic_complexity': 0.5,
                'reactivation_potential': complexity * 0.6,
                'ml_prediction': complexity,
                'traditional_prediction': complexity,
                'uncertainty': 0.3,
                'confidence': 0.4
            }
    
    def _estimate_metamorphic_grade(self, lat: float, lon: float) -> Dict[str, Union[float, str]]:
        """Advanced metamorphic grade estimation using petrology database integration and thermal modeling"""
        try:
            # Initialize petrology and thermal modeling components
            petrology_data = self._query_petrology_database(lat, lon)
            thermal_models = self._load_thermal_evolution_models()
            
            # Multi-source metamorphic grade indicators
            mineral_assemblages = self._analyze_mineral_assemblages(lat, lon)
            pressure_temperature = self._estimate_pt_conditions(lat, lon)
            metamorphic_facies = self._determine_metamorphic_facies(mineral_assemblages, pressure_temperature)
            
            # Advanced thermal modeling
            geothermal_gradient = self._calculate_geothermal_gradient(lat, lon)
            thermal_history = self._model_thermal_history(lat, lon)
            peak_metamorphic_conditions = self._determine_peak_conditions(thermal_history)
            
            # Metamorphic texture analysis
            texture_analysis = self._analyze_metamorphic_textures(lat, lon)
            deformation_metamorphism = self._assess_deformation_metamorphism(lat, lon)
            
            # Regional metamorphic context
            metamorphic_belt = self._identify_metamorphic_belt(lat, lon)
            orogenic_setting = self._determine_orogenic_setting(lat, lon)
            
            # Geochronological constraints
            metamorphic_ages = self._query_metamorphic_ages(lat, lon)
            cooling_history = self._model_cooling_history(lat, lon)
            
            # Fluid-rock interaction assessment
            fluid_interaction = self._assess_fluid_rock_interaction(lat, lon)
            metasomatism = self._evaluate_metasomatic_processes(lat, lon)
            
            # Advanced grade classification
            grade_indicators = {
                'chlorite_zone': self._detect_chlorite_zone_minerals(mineral_assemblages),
                'biotite_zone': self._detect_biotite_zone_minerals(mineral_assemblages),
                'garnet_zone': self._detect_garnet_zone_minerals(mineral_assemblages),
                'staurolite_zone': self._detect_staurolite_zone_minerals(mineral_assemblages),
                'sillimanite_zone': self._detect_sillimanite_zone_minerals(mineral_assemblages)
            }
            
            # Quantitative grade estimation (Barrovian scale: 1-10)
            numerical_grade = self._calculate_numerical_metamorphic_grade(
                grade_indicators, pressure_temperature, metamorphic_facies
            )
            
            # Temperature-pressure path analysis
            pt_path = self._reconstruct_pt_path(lat, lon)
            retrograde_effects = self._assess_retrograde_effects(pt_path)
            
            # ML-based grade prediction
            ml_features = self._extract_metamorphic_ml_features(
                geothermal_gradient, orogenic_setting, mineral_assemblages
            )
            
            ml_grade = 0.5  # Default
            if thermal_models and 'grade_predictor' in thermal_models:
                ml_grade = thermal_models['grade_predictor'].predict([ml_features])[0]
            
            # Traditional distance-based estimate (enhanced)
            range_distance = self._calculate_mountain_range_distance(lat, lon)
            convergent_distance = self._calculate_convergent_boundary_distance(lat, lon)
            
            traditional_grade = max(0, 1 - range_distance / 8)
            traditional_grade += 0.2 * max(0, 1 - convergent_distance / 15)
            traditional_grade = min(traditional_grade, 1.0)
            
            # Ensemble grade calculation
            ensemble_weights = self._calculate_metamorphic_weights(petrology_data, thermal_models)
            ensemble_grade = (
                ensemble_weights['ml'] * ml_grade +
                ensemble_weights['traditional'] * traditional_grade +
                ensemble_weights['numerical'] * (numerical_grade / 10)
            )
            
            # Uncertainty quantification
            grade_uncertainty = self._calculate_metamorphic_grade_uncertainty(
                ml_grade, traditional_grade, numerical_grade, petrology_data
            )
            
            # Confidence assessment
            confidence = self._calculate_metamorphic_analysis_confidence(
                petrology_data, grade_uncertainty, len(mineral_assemblages)
            )
            
            return {
                'metamorphic_grade': min(ensemble_grade, 1.0),
                'metamorphic_facies': metamorphic_facies,
                'numerical_grade': numerical_grade,
                'temperature_c': pressure_temperature.get('temperature', 0),
                'pressure_kbar': pressure_temperature.get('pressure', 0),
                'geothermal_gradient': geothermal_gradient,
                'metamorphic_belt': metamorphic_belt,
                'orogenic_setting': orogenic_setting,
                'retrograde_intensity': retrograde_effects,
                'fluid_interaction': fluid_interaction,
                'ml_prediction': ml_grade,
                'traditional_prediction': traditional_grade,
                'uncertainty': grade_uncertainty,
                'confidence': confidence
            }
            
        except Exception as e:
            self.logger.warning(f"Advanced metamorphic grade analysis failed: {e}")
            # Enhanced fallback with multiple proxies
            range_distance = self._calculate_mountain_range_distance(lat, lon)
            boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
            
            grade = max(0, 1 - range_distance / 8)
            grade += 0.1 * max(0, 1 - boundary_distance / 15)
            grade = min(grade, 1.0)
            
            return {
                'metamorphic_grade': grade,
                'metamorphic_facies': 'unknown',
                'numerical_grade': grade * 6 + 1,  # Scale to 1-7
                'temperature_c': 200 + grade * 400,  # 200-600°C estimate
                'pressure_kbar': 2 + grade * 6,      # 2-8 kbar estimate
                'geothermal_gradient': 25 + grade * 15,  # 25-40°C/km
                'metamorphic_belt': 'unknown',
                'orogenic_setting': 'unknown',
                'retrograde_intensity': grade * 0.3,
                'fluid_interaction': 0.5,
                'ml_prediction': grade,
                'traditional_prediction': grade,
                'uncertainty': 0.4,
                'confidence': 0.3
            }
    
    def _estimate_plutonic_density(self, lat: float, lon: float) -> Dict[str, float]:
        """Advanced plutonic intrusion density estimation using ML models and geological database integration"""
        try:
            # Initialize ML-based plutonic analysis
            plutonic_models = self._load_plutonic_models()
            geological_data = self._query_geological_database(lat, lon)
            
            # Multi-factor plutonic density analysis
            tectonic_setting = self._analyze_tectonic_setting(lat, lon)
            crustal_thickness = self._estimate_crustal_thickness(lat, lon)
            heat_flow = self._estimate_heat_flow(lat, lon)
            magma_composition = self._infer_magma_composition(lat, lon)
            
            # Advanced plutonic density calculation
            base_density = self._calculate_base_plutonic_density(tectonic_setting, crustal_thickness)
            
            # ML-based density refinement
            if plutonic_models and 'density_estimator' in plutonic_models:
                features = np.array([[lat, lon, crustal_thickness, heat_flow, 
                                    tectonic_setting.get('convergent_score', 0),
                                    tectonic_setting.get('extensional_score', 0)]])
                ml_density = plutonic_models['density_estimator'].predict(features)[0]
                
                # Ensemble prediction with uncertainty
                density_estimates = []
                for model_name, model in plutonic_models.items():
                    if hasattr(model, 'predict'):
                        estimate = model.predict(features)[0]
                        density_estimates.append(estimate)
                
                ensemble_density = np.mean(density_estimates) if density_estimates else ml_density
                uncertainty = np.std(density_estimates) if len(density_estimates) > 1 else 0.1
            else:
                ensemble_density = base_density
                uncertainty = 0.2
            
            # Confidence scoring based on data quality and model agreement
            confidence = self._calculate_plutonic_confidence(
                geological_data, tectonic_setting, uncertainty
            )
            
            return {
                'density': max(0.0, min(ensemble_density, 1.0)),
                'confidence': confidence,
                'uncertainty': uncertainty,
                'tectonic_setting': tectonic_setting.get('dominant_regime', 'unknown'),
                'crustal_thickness': crustal_thickness,
                'heat_flow': heat_flow
            }
            
        except Exception as e:
            self.logger.error(f"Error in plutonic density estimation: {str(e)}")
            # Fallback to simplified calculation
            range_distance = self._calculate_mountain_range_distance(lat, lon)
            return {
                'density': max(0, 1 - range_distance / 6),
                'confidence': 0.3,
                'uncertainty': 0.4,
                'tectonic_setting': 'unknown',
                'crustal_thickness': 35.0,
                'heat_flow': 60.0
            }
    
    def _calculate_plate_boundary_distance(self, lat: float, lon: float) -> Dict[str, Union[float, str]]:
        """Advanced plate boundary distance calculation with real-time tectonic database integration"""
        try:
            # Initialize database integration for real-time tectonic data
            tectonic_db = self._get_tectonic_database_connection()
            
            # Query real-time plate boundary data from database
            if tectonic_db:
                boundary_data = self._query_plate_boundaries(tectonic_db, lat, lon)
                seismic_data = self._query_recent_seismicity(tectonic_db, lat, lon)
                gps_velocity_data = self._query_gps_velocity_field(tectonic_db, lat, lon)
            else:
                boundary_data = None
                seismic_data = None
                gps_velocity_data = None
            
            # Advanced plate boundary analysis
            if boundary_data:
                # Calculate distances to various boundary types
                transform_distance = self._calculate_transform_boundary_distance(boundary_data, lat, lon)
                convergent_distance = self._calculate_convergent_boundary_distance(boundary_data, lat, lon)
                divergent_distance = self._calculate_divergent_boundary_distance(boundary_data, lat, lon)
                
                min_distance = min(transform_distance, convergent_distance, divergent_distance)
                boundary_type = self._determine_nearest_boundary_type(
                    transform_distance, convergent_distance, divergent_distance
                )
            else:
                # Fallback to enhanced static boundary data
                enhanced_boundaries = self._get_enhanced_static_boundaries()
                min_distance = float('inf')
                boundary_type = 'unknown'
                
                for boundary in enhanced_boundaries:
                    boundary_lat, boundary_lon, b_type, confidence = boundary
                    distance = self._calculate_geodetic_distance(lat, lon, boundary_lat, boundary_lon)
                    if distance < min_distance:
                        min_distance = distance
                        boundary_type = b_type
            
            # Incorporate seismic activity for boundary proximity assessment
            seismic_factor = 1.0
            if seismic_data:
                seismic_density = self._calculate_seismic_density(seismic_data, lat, lon)
                seismic_factor = max(0.5, 1.0 - seismic_density * 0.3)
            
            # GPS velocity field analysis for active tectonics
            velocity_magnitude = 0.0
            if gps_velocity_data:
                velocity_magnitude = self._calculate_velocity_magnitude(gps_velocity_data)
            
            # Weighted distance considering multiple factors
            effective_distance = min_distance * seismic_factor
            
            # Confidence assessment based on data quality
            data_quality_score = self._assess_tectonic_data_quality(
                boundary_data, seismic_data, gps_velocity_data
            )
            
            return {
                'distance_km': effective_distance,
                'raw_distance_km': min_distance,
                'boundary_type': boundary_type,
                'seismic_activity_factor': seismic_factor,
                'gps_velocity_mm_yr': velocity_magnitude,
                'confidence': data_quality_score,
                'data_source': 'database' if boundary_data else 'static'
            }
            
        except Exception as e:
            self.logger.error(f"Error in plate boundary distance calculation: {str(e)}")
            # Fallback to simplified calculation
            boundaries = [
                (36, -118, 'transform', 0.8),   # San Andreas
                (39, 142, 'convergent', 0.9),   # Japan Trench
                (-40, -73, 'convergent', 0.8),  # Chile Trench
                (28, 84, 'convergent', 0.9),    # Himalayan collision
                (37, 15, 'convergent', 0.7),    # Mediterranean
            ]
            
            min_distance = float('inf')
            boundary_type = 'unknown'
            for boundary_lat, boundary_lon, b_type, confidence in boundaries:
                distance = np.sqrt((lat - boundary_lat)**2 + (lon - boundary_lon)**2) * 111  # Convert to km
                if distance < min_distance:
                    min_distance = distance
                    boundary_type = b_type
            
            return {
                'distance_km': min_distance,
                'raw_distance_km': min_distance,
                'boundary_type': boundary_type,
                'seismic_activity_factor': 1.0,
                'gps_velocity_mm_yr': 0.0,
                'confidence': 0.4,
                'data_source': 'fallback'
            }
    
    def _assess_convergent_setting(self, lat: float, lon: float) -> Dict[str, Union[float, str]]:
        """Advanced convergent tectonic setting assessment using plate tectonics models and data integration"""
        try:
            # Initialize data integration pipeline for geological data
            data_pipeline = self._get_data_integration_pipeline()
            
            # Multi-layer geological data analysis
            if data_pipeline:
                tectonic_layers = data_pipeline.get_tectonic_layers(lat, lon)
                stress_field = data_pipeline.get_stress_field_data(lat, lon)
                gravity_anomaly = data_pipeline.get_gravity_anomaly(lat, lon)
                magnetic_anomaly = data_pipeline.get_magnetic_anomaly(lat, lon)
                seismic_tomography = data_pipeline.get_seismic_tomography(lat, lon)
            else:
                tectonic_layers = None
                stress_field = None
                gravity_anomaly = None
                magnetic_anomaly = None
                seismic_tomography = None
            
            # Advanced convergent zone analysis
            convergence_indicators = {}
            
            # 1. Plate motion analysis
            plate_motion = self._analyze_plate_motion_vectors(lat, lon)
            convergence_indicators['plate_motion_score'] = self._calculate_convergence_score(plate_motion)
            
            # 2. Earthquake focal mechanisms
            focal_mechanisms = self._query_focal_mechanisms(lat, lon)
            convergence_indicators['seismic_convergence'] = self._assess_convergent_seismicity(focal_mechanisms)
            
            # 3. Topographic signatures
            topographic_signature = self._analyze_convergent_topography(lat, lon)
            convergence_indicators['topographic_score'] = topographic_signature
            
            # 4. Geological age progression
            age_progression = self._analyze_age_progression(lat, lon)
            convergence_indicators['age_progression_score'] = age_progression
            
            # 5. Metamorphic grade analysis
            metamorphic_grade = self._assess_metamorphic_convergence(lat, lon)
            convergence_indicators['metamorphic_score'] = metamorphic_grade
            
            # 6. Gravity and magnetic signatures
            if gravity_anomaly and magnetic_anomaly:
                geophysical_score = self._assess_convergent_geophysics(gravity_anomaly, magnetic_anomaly)
                convergence_indicators['geophysical_score'] = geophysical_score
            else:
                convergence_indicators['geophysical_score'] = 0.5
            
            # 7. Stress field orientation
            if stress_field:
                stress_convergence = self._assess_stress_field_convergence(stress_field)
                convergence_indicators['stress_field_score'] = stress_convergence
            else:
                convergence_indicators['stress_field_score'] = 0.5
            
            # Weighted ensemble assessment
            weights = {
                'plate_motion_score': 0.25,
                'seismic_convergence': 0.20,
                'topographic_score': 0.15,
                'age_progression_score': 0.10,
                'metamorphic_score': 0.10,
                'geophysical_score': 0.10,
                'stress_field_score': 0.10
            }
            
            convergent_score = sum(
                convergence_indicators[indicator] * weights[indicator]
                for indicator in weights
                if indicator in convergence_indicators
            )
            
            # Convergent zone classification
            if convergent_score > 0.8:
                zone_type = 'active_convergent'
            elif convergent_score > 0.6:
                zone_type = 'moderate_convergent'
            elif convergent_score > 0.4:
                zone_type = 'weak_convergent'
            else:
                zone_type = 'non_convergent'
            
            # Uncertainty quantification
            indicator_std = np.std(list(convergence_indicators.values()))
            uncertainty = min(0.5, indicator_std)
            
            # Confidence assessment
            data_availability = sum(1 for score in convergence_indicators.values() if score != 0.5) / len(convergence_indicators)
            confidence = min(0.95, 0.5 + data_availability * 0.4)
            
            # Distance to nearest known convergent zone (for validation)
            nearest_convergent_distance = self._calculate_nearest_convergent_zone_distance(lat, lon)
            
            return {
                'convergent_score': max(0.0, min(convergent_score, 1.0)),
                'zone_type': zone_type,
                'confidence': confidence,
                'uncertainty': uncertainty,
                'nearest_convergent_km': nearest_convergent_distance,
                'indicators': convergence_indicators,
                'data_sources': self._get_convergent_data_sources(
                    tectonic_layers, stress_field, gravity_anomaly, magnetic_anomaly
                )
            }
            
        except Exception as e:
            self.logger.error(f"Error in convergent setting assessment: {str(e)}")
            # Fallback to enhanced static analysis
            convergent_zones = [
                (28, 84, 'himalayan', 0.95),     # Himalayas
                (-15, -70, 'andean', 0.90),      # Andes
                (39, 142, 'japan_trench', 0.90), # Japan
                (37, 15, 'mediterranean', 0.75), # Mediterranean
                (61, -150, 'aleutian', 0.85),    # Aleutian
                (-37, 178, 'kermadec', 0.80),    # Kermadec
            ]
            
            min_distance = float('inf')
            zone_type = 'non_convergent'
            for zone_lat, zone_lon, z_type, strength in convergent_zones:
                distance = self._calculate_geodetic_distance(lat, lon, zone_lat, zone_lon)
                if distance < min_distance:
                    min_distance = distance
                    zone_type = z_type
            
            fallback_score = max(0, 1 - min_distance / (15 * 111))  # Convert to km
            
            return {
                'convergent_score': fallback_score,
                'zone_type': 'fallback_assessment',
                'confidence': 0.4,
                'uncertainty': 0.3,
                'nearest_convergent_km': min_distance,
                'indicators': {'distance_based': fallback_score},
                'data_sources': ['static_fallback']
            }
    
    def _assess_orogenic_belt(self, lat: float, lon: float) -> Dict[str, Union[float, str, Dict]]:
        """Advanced orogenic belt analysis using geological database integration and structural modeling"""
        try:
            # Initialize geological database connections
            geological_db = self._get_geological_database_connection()
            structural_db = self._get_structural_database_connection()
            
            # Query comprehensive orogenic data from databases
            if geological_db:
                orogenic_data = self._query_orogenic_database(geological_db, lat, lon)
                metamorphic_data = self._query_metamorphic_database(geological_db, lat, lon)
                geochronology_data = self._query_geochronology_database(geological_db, lat, lon)
            else:
                orogenic_data = None
                metamorphic_data = None
                geochronology_data = None
            
            if structural_db:
                structural_data = self._query_structural_geology(structural_db, lat, lon)
                fault_data = self._query_fault_systems(structural_db, lat, lon)
                fold_data = self._query_fold_structures(structural_db, lat, lon)
            else:
                structural_data = None
                fault_data = None
                fold_data = None
            
            # Multi-criteria orogenic belt assessment
            orogenic_indicators = {}
            
            # 1. Structural geology indicators
            if structural_data and fault_data and fold_data:
                structural_score = self._assess_orogenic_structures(structural_data, fault_data, fold_data)
                orogenic_indicators['structural_complexity'] = structural_score
            else:
                orogenic_indicators['structural_complexity'] = self._estimate_structural_complexity_fallback(lat, lon)
            
            # 2. Metamorphic grade assessment
            if metamorphic_data:
                metamorphic_score = self._assess_orogenic_metamorphism(metamorphic_data)
                orogenic_indicators['metamorphic_intensity'] = metamorphic_score
            else:
                orogenic_indicators['metamorphic_intensity'] = self._estimate_metamorphic_grade_fallback(lat, lon)
            
            # 3. Geochronological evidence
            if geochronology_data:
                age_score = self._assess_orogenic_ages(geochronology_data)
                orogenic_indicators['geochronological_evidence'] = age_score
            else:
                orogenic_indicators['geochronological_evidence'] = 0.5
            
            # 4. Topographic expression
            topographic_score = self._assess_orogenic_topography(lat, lon)
            orogenic_indicators['topographic_expression'] = topographic_score
            
            # 5. Crustal thickness analysis
            crustal_thickness = self._estimate_crustal_thickness(lat, lon)
            thickness_score = self._assess_orogenic_crustal_thickness(crustal_thickness)
            orogenic_indicators['crustal_thickness'] = thickness_score
            
            # 6. Gravity anomaly patterns
            gravity_data = self._get_gravity_anomaly_data(lat, lon)
            if gravity_data:
                gravity_score = self._assess_orogenic_gravity_signature(gravity_data)
                orogenic_indicators['gravity_signature'] = gravity_score
            else:
                orogenic_indicators['gravity_signature'] = 0.5
            
            # 7. Seismic velocity structure
            seismic_velocity = self._get_seismic_velocity_structure(lat, lon)
            if seismic_velocity:
                velocity_score = self._assess_orogenic_seismic_structure(seismic_velocity)
                orogenic_indicators['seismic_structure'] = velocity_score
            else:
                orogenic_indicators['seismic_structure'] = 0.5
            
            # Enhanced orogenic belt classification with database integration
            known_belts = self._query_known_orogenic_belts(lat, lon) if geological_db else None
            if known_belts:
                belt_classification = self._classify_orogenic_belt_type(known_belts, orogenic_indicators)
            else:
                belt_classification = self._fallback_orogenic_classification(lat, lon, orogenic_indicators)
            
            # Weighted composite assessment
            weights = {
                'structural_complexity': 0.20,
                'metamorphic_intensity': 0.18,
                'geochronological_evidence': 0.15,
                'topographic_expression': 0.15,
                'crustal_thickness': 0.12,
                'gravity_signature': 0.10,
                'seismic_structure': 0.10
            }
            
            orogenic_score = sum(
                orogenic_indicators[indicator] * weights[indicator]
                for indicator in weights
                if indicator in orogenic_indicators
            )
            
            # Orogenic belt type determination
            if orogenic_score > 0.85:
                belt_type = 'active_orogenic'
                orogenic_stage = 'syn-orogenic'
            elif orogenic_score > 0.65:
                belt_type = 'mature_orogenic'
                orogenic_stage = 'late-orogenic'
            elif orogenic_score > 0.45:
                belt_type = 'ancient_orogenic'
                orogenic_stage = 'post-orogenic'
            else:
                belt_type = 'non_orogenic'
                orogenic_stage = 'stable'
            
            # Uncertainty and confidence assessment
            indicator_variance = np.var(list(orogenic_indicators.values()))
            uncertainty = min(0.4, np.sqrt(indicator_variance))
            
            data_completeness = sum(1 for v in orogenic_indicators.values() if v != 0.5) / len(orogenic_indicators)
            confidence = min(0.95, 0.4 + data_completeness * 0.5)
            
            # Distance to nearest major orogenic belt
            nearest_belt_distance = self._calculate_nearest_orogenic_belt_distance(lat, lon)
            
            return {
                'orogenic_score': max(0.0, min(orogenic_score, 1.0)),
                'belt_type': belt_type,
                'orogenic_stage': orogenic_stage,
                'belt_name': belt_classification.get('name', 'unknown'),
                'confidence': confidence,
                'uncertainty': uncertainty,
                'nearest_belt_km': nearest_belt_distance,
                'indicators': orogenic_indicators,
                'geological_age_ma': belt_classification.get('age_range', [0, 0]),
                'tectonic_setting': belt_classification.get('tectonic_setting', 'unknown'),
                'data_sources': self._get_orogenic_data_sources(
                    orogenic_data, structural_data, metamorphic_data, geochronology_data
                )
            }
            
        except Exception as e:
            self.logger.error(f"Error in orogenic belt assessment: {str(e)}")
            # Enhanced fallback with comprehensive belt database
            enhanced_orogenic_belts = [
                (28, 84, 'alpine_himalayan', 'collision', [65, 0], 0.95),
                (-15, -70, 'andean', 'subduction', [200, 0], 0.90),
                (45, -110, 'north_american_cordillera', 'accretionary', [200, 50], 0.85),
                (37, -80, 'appalachian', 'collision', [480, 250], 0.70),
                (62, 15, 'caledonian', 'collision', [490, 390], 0.60),
                (-25, 135, 'alice_springs', 'intracratonic', [450, 300], 0.65),
                (48, 105, 'central_asian', 'accretionary', [570, 250], 0.75),
            ]
            
            min_distance = float('inf')
            best_match = None
            for belt_lat, belt_lon, name, setting, age_range, strength in enhanced_orogenic_belts:
                distance = self._calculate_geodetic_distance(lat, lon, belt_lat, belt_lon)
                if distance < min_distance:
                    min_distance = distance
                    best_match = (name, setting, age_range, strength)
            
            fallback_score = max(0, 1 - min_distance / (12 * 111))  # Convert to km
            
            if best_match:
                belt_name, tectonic_setting, age_range, strength = best_match
            else:
                belt_name = 'unknown'
                tectonic_setting = 'unknown'
                age_range = [0, 0]
            
            return {
                'orogenic_score': fallback_score,
                'belt_type': 'fallback_assessment',
                'orogenic_stage': 'unknown',
                'belt_name': belt_name,
                'confidence': 0.4,
                'uncertainty': 0.35,
                'nearest_belt_km': min_distance,
                'indicators': {'distance_based': fallback_score},
                'geological_age_ma': age_range,
                'tectonic_setting': tectonic_setting,
                'data_sources': ['static_fallback']
            }
    
    def _determine_region(self, lat: float, lon: float) -> Dict[str, Union[str, float, Dict]]:
        """Advanced dynamic geographic classification using ML models and geological context"""
        try:
            # Initialize ML-based geographic classification
            region_models = self._load_regional_classification_models()
            geological_context = self._get_geological_context(lat, lon)
            
            # Multi-criteria regional classification
            classification_features = {}
            
            # 1. Basic geographic coordinates
            classification_features['latitude'] = lat
            classification_features['longitude'] = lon
            
            # 2. Tectonic plate association
            plate_info = self._identify_tectonic_plate(lat, lon)
            classification_features['tectonic_plate'] = plate_info.get('plate_name', 'unknown')
            
            # 3. Geological province
            if geological_context:
                geological_province = geological_context.get('geological_province', 'unknown')
                classification_features['geological_province'] = geological_province
            else:
                geological_province = 'unknown'
            
            # 4. Climate zone classification
            climate_zone = self._classify_climate_zone(lat, lon)
            classification_features['climate_zone'] = climate_zone
            
            # 5. Ocean basin or continental mass
            physiographic_setting = self._determine_physiographic_setting(lat, lon)
            classification_features['physiographic_setting'] = physiographic_setting
            
            # 6. Proximity to major geological features
            proximity_features = self._analyze_proximity_features(lat, lon)
            classification_features.update(proximity_features)
            
            # ML-based region prediction
            if region_models and 'geographic_classifier' in region_models:
                # Prepare feature vector for ML model
                feature_vector = self._prepare_regional_feature_vector(classification_features)
                
                # Predict primary region
                primary_region = region_models['geographic_classifier'].predict([feature_vector])[0]
                
                # Get prediction probabilities for confidence assessment
                if hasattr(region_models['geographic_classifier'], 'predict_proba'):
                    probabilities = region_models['geographic_classifier'].predict_proba([feature_vector])[0]
                    confidence = max(probabilities)
                    
                    # Get alternative regions with significant probability
                    class_names = region_models['geographic_classifier'].classes_
                    region_probabilities = dict(zip(class_names, probabilities))
                else:
                    confidence = 0.7
                    region_probabilities = {primary_region: confidence}
            else:
                # Fallback to enhanced rule-based classification
                primary_region, confidence, region_probabilities = self._enhanced_rule_based_classification(
                    lat, lon, classification_features
                )
            
            # Sub-region classification for better data specificity
            sub_region = self._classify_sub_region(lat, lon, primary_region, classification_features)
            
            # Geological data source prioritization
            data_sources = self._prioritize_regional_data_sources(primary_region, sub_region, classification_features)
            
            # Specialized regional characteristics
            regional_characteristics = self._analyze_regional_characteristics(
                lat, lon, primary_region, classification_features
            )
            
            return {
                'primary_region': primary_region,
                'sub_region': sub_region,
                'confidence': confidence,
                'region_probabilities': region_probabilities,
                'tectonic_plate': classification_features['tectonic_plate'],
                'geological_province': geological_province,
                'climate_zone': climate_zone,
                'physiographic_setting': physiographic_setting,
                'data_source_priority': data_sources,
                'regional_characteristics': regional_characteristics,
                'classification_method': 'ml_enhanced' if region_models else 'rule_based_enhanced'
            }
            
        except Exception as e:
            self.logger.error(f"Error in regional classification: {str(e)}")
            # Enhanced fallback classification
            fallback_region = self._fallback_regional_classification(lat, lon)
            
            return {
                'primary_region': fallback_region['region'],
                'sub_region': fallback_region['sub_region'],
                'confidence': 0.6,
                'region_probabilities': {fallback_region['region']: 0.6},
                'tectonic_plate': 'unknown',
                'geological_province': 'unknown',
                'climate_zone': self._simple_climate_classification(lat),
                'physiographic_setting': 'unknown',
                'data_source_priority': ['global'],
                'regional_characteristics': {},
                'classification_method': 'fallback'
            }
    
    def _fallback_regional_classification(self, lat: float, lon: float) -> Dict[str, str]:
        """Enhanced fallback regional classification with sub-regions"""
        if lat > 66.5:
            return {'region': 'arctic', 'sub_region': 'high_arctic' if lat > 80 else 'sub_arctic'}
        elif lat < -60:
            if lon > -60 and lon < 60:
                return {'region': 'antarctic', 'sub_region': 'east_antarctica'}
            else:
                return {'region': 'antarctic', 'sub_region': 'west_antarctica'}
        elif -30 <= lat <= 70 and -180 <= lon <= -30:
            if lat > 50:
                return {'region': 'americas', 'sub_region': 'north_america'}
            elif lat > 15:
                return {'region': 'americas', 'sub_region': 'central_america'}
            else:
                return {'region': 'americas', 'sub_region': 'south_america'}
        elif -50 <= lat <= 75 and -30 <= lon <= 60:
            if lat > 35:
                return {'region': 'europe', 'sub_region': 'northern_europe' if lat > 55 else 'central_europe'}
            elif lat > 0:
                return {'region': 'africa_europe', 'sub_region': 'mediterranean'}
            else:
                return {'region': 'africa_europe', 'sub_region': 'sub_saharan_africa'}
        elif -50 <= lat <= 70 and 60 <= lon <= 180:
            if lat > 40:
                return {'region': 'asia_pacific', 'sub_region': 'northern_asia'}
            elif lat > 0:
                return {'region': 'asia_pacific', 'sub_region': 'central_asia'}
            else:
                return {'region': 'asia_pacific', 'sub_region': 'southeast_asia_oceania'}
        else:
            return {'region': 'global', 'sub_region': 'unclassified'}
    
    def _query_topography_model(self, model_name: str, lat: float, lon: float) -> Dict[str, Union[float, str, Dict]]:
        """Advanced topography model querying with full model_database.py integration"""
        try:
            # Initialize model database connection
            if not hasattr(self, 'model_database') or self.model_database is None:
                from .model_database import ModelDatabase
                db_config = {'host': 'localhost', 'database': 'prometheus_models'}
                self.model_database = ModelDatabase(db_config)
            
            # Query available topography models
            topography_models = self.model_database.search_models({
                'model_type': 'topography',
                'region': self._determine_optimal_region(lat, lon),
                'status': 'active'
            })
            
            if not topography_models:
                # Fallback to global models
                topography_models = self.model_database.search_models({
                    'model_type': 'topography',
                    'region': 'global',
                    'status': 'active'
                })
            
            elevation_data = {}
            model_sources = []
            confidence_scores = []
            
            # Multi-model ensemble approach
            for model_info in topography_models[:5]:  # Use top 5 models
                try:
                    # Download and load model if needed
                    model_path = self.model_database.get_model(model_info['model_id'])
                    
                    if model_path:
                        # Load the specific topography model
                        topo_model = self._load_topography_model(model_path, model_info)
                        
                        if topo_model:
                            # Query elevation from the model
                            elevation = self._extract_elevation_from_model(
                                topo_model, lat, lon, model_info
                            )
                            
                            # Store results with metadata
                            model_key = f"{model_info['model_name']}_{model_info['version']}"
                            elevation_data[model_key] = {
                                'elevation_m': elevation,
                                'resolution_m': model_info.get('spatial_resolution', 30),
                                'data_source': model_info.get('data_source', 'unknown'),
                                'accuracy_m': model_info.get('vertical_accuracy', 10),
                                'last_updated': model_info.get('last_updated', 'unknown')
                            }
                            
                            model_sources.append(model_key)
                            
                            # Calculate confidence based on model metadata
                            confidence = self._calculate_model_confidence(model_info, lat, lon)
                            confidence_scores.append(confidence)
                
                except Exception as model_error:
                    self.logger.warning(f"Error loading model {model_info.get('model_name', 'unknown')}: {str(model_error)}")
                    continue
            
            # Ensemble elevation calculation
            if elevation_data:
                # Weighted average based on model confidence and resolution
                weighted_elevations = []
                weights = []
                
                for i, (model_key, data) in enumerate(elevation_data.items()):
                    elevation = data['elevation_m']
                    confidence = confidence_scores[i] if i < len(confidence_scores) else 0.5
                    resolution_weight = 1.0 / max(data['resolution_m'], 1)  # Higher weight for better resolution
                    
                    total_weight = confidence * resolution_weight
                    weighted_elevations.append(elevation * total_weight)
                    weights.append(total_weight)
                
                if weights:
                    ensemble_elevation = sum(weighted_elevations) / sum(weights)
                    elevation_uncertainty = np.std([data['elevation_m'] for data in elevation_data.values()])
                    overall_confidence = np.mean(confidence_scores)
                else:
                    ensemble_elevation = list(elevation_data.values())[0]['elevation_m']
                    elevation_uncertainty = 0.0
                    overall_confidence = confidence_scores[0] if confidence_scores else 0.5
                
                # Additional topographic context
                topographic_context = self._analyze_topographic_context(
                    lat, lon, ensemble_elevation, elevation_data
                )
                
                return {
                    'elevation_m': ensemble_elevation,
                    'uncertainty_m': elevation_uncertainty,
                    'confidence': overall_confidence,
                    'model_count': len(elevation_data),
                    'model_sources': model_sources,
                    'detailed_elevations': elevation_data,
                    'topographic_context': topographic_context,
                    'query_timestamp': self._get_current_timestamp(),
                    'data_quality': self._assess_elevation_data_quality(elevation_data, confidence_scores)
                }
            
            else:
                # No models available, use fallback DEM data
                fallback_elevation = self._get_fallback_elevation(lat, lon)
                return {
                    'elevation_m': fallback_elevation,
                    'uncertainty_m': 100.0,  # High uncertainty for fallback
                    'confidence': 0.3,
                    'model_count': 0,
                    'model_sources': ['fallback'],
                    'detailed_elevations': {'fallback': {'elevation_m': fallback_elevation}},
                    'topographic_context': {'terrain_type': 'unknown'},
                    'query_timestamp': self._get_current_timestamp(),
                    'data_quality': 'low'
                }
            
        except Exception as e:
            self.logger.error(f"Error in topography model query: {str(e)}")
            # Final fallback
            basic_elevation = self._basic_elevation_estimate(lat, lon)
            
            return {
                'elevation_m': basic_elevation,
                'uncertainty_m': 200.0,
                'confidence': 0.2,
                'model_count': 0,
                'model_sources': ['basic_estimate'],
                'detailed_elevations': {'basic': {'elevation_m': basic_elevation}},
                'topographic_context': {'terrain_type': 'estimated'},
                'query_timestamp': self._get_current_timestamp(),
                'data_quality': 'very_low'
            }
    
