    def _interpret_geological_unit(self, geological_unit: str) -> Dict[str, Any]:
        """Interpret geological unit for age information"""
        # Map geological units to ages (simplified)
        unit_ages = {
            'archean': 3200,
            'proterozoic': 1500,
            'paleozoic': 350,
            'mesozoic': 150,
            'cenozoic': 30
        }
        
        unit_lower = geological_unit.lower()
        for unit, age in unit_ages.items():
            if unit in unit_lower:
                return {
                    'crustal_age': age,
                    'geological_unit': geological_unit,
                    'age_confidence': 0.7
                }
        
        return {'crustal_age': 800, 'age_confidence': 0.3}  # Default
    
    def _fallback_shield_check(self, lat: float, lon: float) -> Tuple[bool, Dict[str, Any]]:
        """Fallback shield check using simplified regional boundaries"""
        try:
            # Known Precambrian shields
            shields = [
                {
                    'name': 'Canadian Shield',
                    'bounds': (45, 70, -110, -60),
                    'age': 3800,
                    'confidence': 0.9
                },
                {
                    'name': 'Baltic Shield',
                    'bounds': (55, 70, 10, 60),
                    'age': 3500,
                    'confidence': 0.9
                },
                {
                    'name': 'Siberian Shield',
                    'bounds': (60, 75, 90, 140),
                    'age': 3200,
                    'confidence': 0.8
                },
                {
                    'name': 'Australian Shield',
                    'bounds': (-35, -15, 115, 145),
                    'age': 3400,
                    'confidence': 0.8
                },
                {
                    'name': 'African Shield',
                    'bounds': (-30, 20, 15, 35),
                    'age': 3600,
                    'confidence': 0.7
                },
                {
                    'name': 'Brazilian Shield',
                    'bounds': (-25, 0, -55, -35),
                    'age': 2800,
                    'confidence': 0.7
                },
                {
                    'name': 'Indian Shield',
                    'bounds': (8, 28, 70, 88),
                    'age': 3300,
                    'confidence': 0.7
                }
            ]
            
            for shield in shields:
                min_lat, max_lat, min_lon, max_lon = shield['bounds']
                if min_lat <= lat <= max_lat and min_lon <= lon <= max_lon:
                    metrics = {
                        'crustal_age': shield['age'],
                        'shield_name': shield['name'],
                        'confidence': shield['confidence'],
                        'crustal_thickness': 45.0,
                        'heat_flow': 40.0,
                        'source': 'regional_fallback'
                    }
                    return True, metrics
            
            # Not in known shield
            metrics = {
                'crustal_age': 800,
                'confidence': 0.6,
                'crustal_thickness': 35.0,
                'heat_flow': 65.0,
                'source': 'regional_fallback'
            }
            return False, metrics
            
        except Exception:
            return False, {'confidence': 0.3, 'source': 'error_fallback'}
    
    def _is_sedimentary_basin_location(self, lat: float, lon: float) -> Tuple[bool, Dict[str, Any]]:
        """Advanced sedimentary basin detection using geological structure data and basin modeling
        
        Args:
            lat: Latitude in decimal degrees
            lon: Longitude in decimal degrees
            
        Returns:
            Tuple of (is_sedimentary_basin: bool, basin_characteristics: Dict)
        """
        try:
            # Comprehensive basin analysis using multiple data sources
            basin_structure_data = self._analyze_basin_structure(lat, lon)
            
            # Sedimentary geology analysis
            sedimentary_analysis = self._analyze_sedimentary_geology(lat, lon)
            
            # Subsurface modeling and geophysical analysis
            subsurface_analysis = self._analyze_subsurface_characteristics(lat, lon)
            
            # Basin formation and tectonic setting analysis
            tectonic_analysis = self._analyze_basin_tectonic_setting(lat, lon)
            
            # Multi-criteria basin classification
            is_sedimentary_basin = self._classify_sedimentary_basin(
                basin_structure_data, sedimentary_analysis, 
                subsurface_analysis, tectonic_analysis
            )
            
            # Compile comprehensive basin characteristics
            basin_characteristics = {
                **basin_structure_data,
                **sedimentary_analysis,
                **subsurface_analysis,
                **tectonic_analysis,
                'confidence': self._calculate_basin_confidence(
                    basin_structure_data, sedimentary_analysis,
                    subsurface_analysis, tectonic_analysis
                )
            }
            
            return is_sedimentary_basin, basin_characteristics
            
        except Exception as e:
            self.logger.warning(f"Advanced sedimentary basin detection failed: {e}")
            # Fallback to exclusion-based check
            return self._fallback_basin_check(lat, lon)
    
    def _analyze_basin_structure(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze basin structural characteristics"""
        try:
            structure_data = {}
            
            # Basin depth estimation
            structure_data['basin_depth'] = self._estimate_basin_depth(lat, lon)
            
            # Structural style analysis
            structure_data['structural_style'] = self._analyze_structural_style(lat, lon)
            
            # Fault system analysis
            structure_data['fault_density'] = self._analyze_fault_systems(lat, lon)
            
            # Basin geometry analysis
            structure_data.update(self._analyze_basin_geometry(lat, lon))
            
            # Basement topography
            structure_data['basement_depth'] = self._estimate_basement_depth(lat, lon)
            
            # Structural domains
            structure_data['structural_domain'] = self._classify_structural_domain(lat, lon)
            
            return structure_data
            
        except Exception as e:
            self.logger.debug(f"Basin structure analysis failed: {e}")
            return {'basin_depth': 2000, 'structural_style': 'extensional'}
    
    def _analyze_sedimentary_geology(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze sedimentary geological characteristics"""
        try:
            sedimentary_data = {}
            
            # Sediment thickness analysis
            sedimentary_data['sediment_thickness'] = self._estimate_sediment_thickness(lat, lon)
            
            # Stratigraphic analysis
            sedimentary_data.update(self._analyze_stratigraphy(lat, lon))
            
            # Depositional environment analysis
            sedimentary_data['depositional_environment'] = self._analyze_depositional_environment(lat, lon)
            
            # Lithological composition
            sedimentary_data.update(self._analyze_lithological_composition(lat, lon))
            
            # Age of sedimentary sequences
            sedimentary_data['sedimentary_age_range'] = self._estimate_sedimentary_age(lat, lon)
            
            # Hydrocarbon potential indicators
            sedimentary_data.update(self._analyze_hydrocarbon_potential(lat, lon))
            
            return sedimentary_data
            
        except Exception as e:
            self.logger.debug(f"Sedimentary geology analysis failed: {e}")
            return {'sediment_thickness': 1500, 'depositional_environment': 'continental'}
    
    def _analyze_subsurface_characteristics(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze subsurface characteristics using geophysical methods"""
        try:
            subsurface_data = {}
            
            # Gravity analysis (basins show negative anomalies)
            subsurface_data['gravity_anomaly'] = self._analyze_gravity_anomaly(lat, lon)
            
            # Magnetic field analysis
            subsurface_data['magnetic_signature'] = self._analyze_magnetic_signature(lat, lon)
            
            # Seismic characteristics
            subsurface_data.update(self._analyze_seismic_characteristics(lat, lon))
            
            # Heat flow analysis
            subsurface_data['heat_flow'] = self._estimate_basin_heat_flow(lat, lon)
            
            # Subsidence analysis
            subsurface_data.update(self._analyze_subsidence_patterns(lat, lon))
            
            # Fluid flow characteristics
            subsurface_data.update(self._analyze_fluid_flow_systems(lat, lon))
            
            return subsurface_data
            
        except Exception as e:
            self.logger.debug(f"Subsurface analysis failed: {e}")
            return {'gravity_anomaly': -20, 'heat_flow': 60}
    
    def _analyze_basin_tectonic_setting(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze basin tectonic setting and formation mechanism"""
        try:
            tectonic_data = {}
            
            # Basin type classification
            tectonic_data['basin_type'] = self._classify_basin_type(lat, lon)
            
            # Tectonic stress field
            tectonic_data['stress_regime'] = self._analyze_stress_regime(lat, lon)
            
            # Plate tectonic setting
            tectonic_data['tectonic_setting'] = self._determine_tectonic_setting(lat, lon)
            
            # Distance to active tectonics
            tectonic_data['active_tectonics_distance'] = self._calculate_active_tectonics_distance(lat, lon)
            
            # Rift system association
            tectonic_data['rift_association'] = self._assess_rift_association(lat, lon)
            
            # Foreland basin characteristics
            tectonic_data['foreland_characteristics'] = self._assess_foreland_characteristics(lat, lon)
            
            return tectonic_data
            
        except Exception as e:
            self.logger.debug(f"Basin tectonic analysis failed: {e}")
            return {'basin_type': 'intracratonic', 'stress_regime': 'extensional'}
    
    def _classify_sedimentary_basin(self, structure_data: Dict[str, Any],
                                   sedimentary_data: Dict[str, Any],
                                   subsurface_data: Dict[str, Any],
                                   tectonic_data: Dict[str, Any]) -> bool:
        """Advanced sedimentary basin classification using multiple criteria"""
        try:
            # Multi-criteria basin classification
            basin_score = 0.0
            weights = {
                'sediment_thickness': 0.25,
                'basin_structure': 0.20,
                'geophysical_signature': 0.20,
                'depositional_environment': 0.15,
                'tectonic_setting': 0.10,
                'exclusion_criteria': 0.10
            }
            
            # Sediment thickness criterion (primary for basins)
            sediment_thickness = sedimentary_data.get('sediment_thickness', 0)
            if sediment_thickness > 3000:  # Very thick sediments
                basin_score += weights['sediment_thickness'] * 1.0
            elif sediment_thickness > 1500:  # Thick sediments
                basin_score += weights['sediment_thickness'] * 0.8
            elif sediment_thickness > 500:  # Moderate sediments
                basin_score += weights['sediment_thickness'] * 0.6
            elif sediment_thickness > 100:  # Thin sediments
                basin_score += weights['sediment_thickness'] * 0.3
            
            # Basin structural characteristics
            basin_depth = structure_data.get('basin_depth', 0)
            if basin_depth > 4000:  # Deep basin
                basin_score += weights['basin_structure'] * 1.0
            elif basin_depth > 2000:  # Moderate depth
                basin_score += weights['basin_structure'] * 0.7
            elif basin_depth > 1000:  # Shallow basin
                basin_score += weights['basin_structure'] * 0.4
            
            # Geophysical signature (negative gravity anomaly)
            gravity_anomaly = subsurface_data.get('gravity_anomaly', 0)
            if gravity_anomaly < -30:  # Strong negative anomaly
                basin_score += weights['geophysical_signature'] * 1.0
            elif gravity_anomaly < -10:  # Moderate negative anomaly
                basin_score += weights['geophysical_signature'] * 0.7
            elif gravity_anomaly < 0:  # Weak negative anomaly
                basin_score += weights['geophysical_signature'] * 0.4
            
            # Depositional environment
            dep_env = sedimentary_data.get('depositional_environment', 'unknown')
            if dep_env in ['marine', 'lacustrine', 'fluvial', 'deltaic']:
                basin_score += weights['depositional_environment'] * 0.8
            elif dep_env in ['continental', 'alluvial']:
                basin_score += weights['depositional_environment'] * 0.6
            
            # Tectonic setting
            basin_type = tectonic_data.get('basin_type', 'unknown')
            if basin_type in ['rift', 'foreland', 'back_arc']:
                basin_score += weights['tectonic_setting'] * 0.9
            elif basin_type in ['intracratonic', 'pull_apart']:
                basin_score += weights['tectonic_setting'] * 0.7
            
            # Exclusion criteria (not mountain, shield, or oceanic)
            exclusion_score = self._calculate_exclusion_score(lat, lon)
            basin_score += weights['exclusion_criteria'] * exclusion_score
            
            # Classification threshold for sedimentary basins
            basin_threshold = 0.65
            return basin_score > basin_threshold
            
        except Exception:
            # Fallback to simple criteria
            sediment_thickness = sedimentary_data.get('sediment_thickness', 0)
            basin_depth = structure_data.get('basin_depth', 0)
            return sediment_thickness > 1000 and basin_depth > 1500
    
    def _calculate_basin_confidence(self, structure_data: Dict[str, Any],
                                   sedimentary_data: Dict[str, Any],
                                   subsurface_data: Dict[str, Any],
                                   tectonic_data: Dict[str, Any]) -> float:
        """Calculate confidence level for basin classification"""
        try:
            confidence = 0.5  # Base confidence
            
            # Increase confidence based on data quality
            data_sources = [
                structure_data.get('data_source'),
                sedimentary_data.get('data_source'),
                subsurface_data.get('data_source')
            ]
            
            database_sources = sum(1 for src in data_sources if src == 'database')
            confidence += 0.1 * database_sources
            
            # Confidence from consistent indicators
            indicators = [
                1.0 if sedimentary_data.get('sediment_thickness', 0) > 1000 else 0.0,
                1.0 if structure_data.get('basin_depth', 0) > 2000 else 0.0,
                1.0 if subsurface_data.get('gravity_anomaly', 0) < -10 else 0.0,
                1.0 if tectonic_data.get('basin_type') in ['rift', 'foreland', 'intracratonic'] else 0.0
            ]
            
            indicator_agreement = sum(indicators) / len(indicators)
            confidence += 0.3 * indicator_agreement
            
            return min(confidence, 1.0)
            
        except Exception:
            return 0.5
    
    # Helper methods for basin analysis
    def _estimate_basin_depth(self, lat: float, lon: float) -> float:
        """Estimate total basin depth"""
        try:
            # Major sedimentary basins and their approximate depths
            known_basins = {
                'gulf_of_mexico': {'center': (26, -94), 'radius': 8, 'depth': 12000},
                'north_sea': {'center': (56, 3), 'radius': 4, 'depth': 8000},
                'permian_basin': {'center': (32, -102), 'radius': 3, 'depth': 6000},
                'paris_basin': {'center': (49, 2), 'radius': 2, 'depth': 3000},
                'michigan_basin': {'center': (44, -85), 'radius': 3, 'depth': 4000},
                'williston_basin': {'center': (48, -103), 'radius': 4, 'depth': 5000},
                'tarim_basin': {'center': (40, 83), 'radius': 6, 'depth': 7000},
                'amazon_basin': {'center': (-5, -60), 'radius': 8, 'depth': 5000}
            }
            
            # Check proximity to known basins
            for basin_name, basin_data in known_basins.items():
                center_lat, center_lon = basin_data['center']
                distance = np.sqrt((lat - center_lat)**2 + (lon - center_lon)**2)
                
                if distance <= basin_data['radius']:
                    # Scale depth based on distance from center
                    distance_factor = 1.0 - (distance / basin_data['radius'])
                    return basin_data['depth'] * (0.5 + 0.5 * distance_factor)
            
            # Estimate based on tectonic setting if not in known basin
            return self._estimate_depth_from_tectonics(lat, lon)
            
        except Exception:
            return 2000  # Default moderate depth
    
    def _estimate_depth_from_tectonics(self, lat: float, lon: float) -> float:
        """Estimate basin depth from tectonic setting"""
        # Distance to plate boundaries (rifts create deep basins)
        boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
        
        # Distance to mountain belts (foreland basins)
        mountain_distance = self._calculate_mountain_range_distance(lat, lon)
        
        # Distance to shields (intracratonic basins)
        shield_distance = self._calculate_shield_distance(lat, lon)
        
        depth = 1000  # Base depth
        
        if boundary_distance < 5:  # Near active boundary
            depth += 3000  # Rift basin
        elif mountain_distance < 10:  # Near mountains
            depth += 2000  # Foreland basin
        elif shield_distance > 15:  # Far from shields
            depth += 1500  # Passive margin
        
        return depth
    
    def _analyze_structural_style(self, lat: float, lon: float) -> str:
        """Analyze structural style of basin"""
        try:
            boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
            mountain_distance = self._calculate_mountain_range_distance(lat, lon)
            
            if boundary_distance < 5:
                return 'extensional'  # Rift-related
            elif mountain_distance < 10:
                return 'compressional'  # Foreland
            else:
                return 'intracratonic'  # Stable platform
                
        except Exception:
            return 'unknown'
    
    def _analyze_fault_systems(self, lat: float, lon: float) -> float:
        """Analyze fault system density"""
        try:
            boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
            
            # Higher fault density near plate boundaries
            if boundary_distance < 5:
                return 0.8  # High fault density
            elif boundary_distance < 15:
                return 0.6  # Moderate
            else:
                return 0.3  # Low
                
        except Exception:
            return 0.5
    
    def _analyze_basin_geometry(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze basin geometry characteristics"""
        try:
            return {
                'basin_shape': self._estimate_basin_shape(lat, lon),
                'aspect_ratio': self._estimate_aspect_ratio(lat, lon),
                'symmetry': self._estimate_basin_symmetry(lat, lon)
            }
        except Exception:
            return {'basin_shape': 'elliptical', 'aspect_ratio': 2.0, 'symmetry': 0.7}
    
    def _estimate_basement_depth(self, lat: float, lon: float) -> float:
        """Estimate depth to crystalline basement"""
        basin_depth = self._estimate_basin_depth(lat, lon)
        # Basement typically deeper than basin fill
        return basin_depth * 1.2
    
    def _classify_structural_domain(self, lat: float, lon: float) -> str:
        """Classify structural domain of basin"""
        structural_style = self._analyze_structural_style(lat, lon)
        fault_density = self._analyze_fault_systems(lat, lon)
        
        if structural_style == 'extensional' and fault_density > 0.7:
            return 'active_rift'
        elif structural_style == 'compressional':
            return 'foreland'
        else:
            return 'stable_platform'
    
    def _estimate_sediment_thickness(self, lat: float, lon: float) -> float:
        """Estimate sedimentary sequence thickness"""
        # Use basin depth as proxy, with typical sediment fill ratios
        basin_depth = self._estimate_basin_depth(lat, lon)
        
        # Sediments typically fill 60-80% of basin depth
        fill_ratio = 0.7  # Average
        return basin_depth * fill_ratio
    
    def _analyze_stratigraphy(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze stratigraphic characteristics"""
        return {
            'stratigraphic_complexity': self._estimate_stratigraphic_complexity(lat, lon),
            'sequence_count': self._estimate_sequence_count(lat, lon),
            'unconformity_count': self._estimate_unconformities(lat, lon)
        }
    
    def _analyze_depositional_environment(self, lat: float, lon: float) -> str:
        """Analyze primary depositional environment"""
        try:
            # Estimate based on location and setting
            oceanic_result = self._is_oceanic_simple_check(lat, lon)
            
            if oceanic_result:
                return 'marine'
            
            # Continental settings
            mountain_distance = self._calculate_mountain_range_distance(lat, lon)
            if mountain_distance < 10:
                return 'alluvial_fan'  # Near mountains
            
            # Climate-based estimation
            if abs(lat) < 30:  # Tropical/subtropical
                return 'lacustrine'  # Lake systems common
            else:
                return 'fluvial'  # River systems
                
        except Exception:
            return 'continental'
    
    def _analyze_lithological_composition(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze lithological composition of sediments"""
        try:
            composition = {}
            
            dep_env = self._analyze_depositional_environment(lat, lon)
            
            if dep_env == 'marine':
                composition = {'limestone': 0.4, 'shale': 0.4, 'sandstone': 0.2}
            elif dep_env == 'lacustrine':
                composition = {'shale': 0.5, 'limestone': 0.3, 'sandstone': 0.2}
            elif dep_env == 'fluvial':
                composition = {'sandstone': 0.6, 'shale': 0.3, 'conglomerate': 0.1}
            else:  # Continental
                composition = {'sandstone': 0.5, 'shale': 0.3, 'conglomerate': 0.2}
            
            return composition
            
        except Exception:
            return {'sandstone': 0.4, 'shale': 0.4, 'limestone': 0.2}
    
    def _estimate_sedimentary_age(self, lat: float, lon: float) -> Dict[str, float]:
        """Estimate age range of sedimentary sequences"""
        try:
            # Simplified age estimation based on basin type
            basin_type = self._classify_basin_type(lat, lon)
            
            if basin_type == 'rift':
                return {'min_age': 10, 'max_age': 200}  # Recent to Mesozoic
            elif basin_type == 'foreland':
                return {'min_age': 50, 'max_age': 300}  # Cenozoic to Paleozoic
            else:  # Intracratonic
                return {'min_age': 100, 'max_age': 500}  # Broader range
                
        except Exception:
            return {'min_age': 50, 'max_age': 250}
    
    def _analyze_hydrocarbon_potential(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze hydrocarbon potential indicators"""
        try:
            potential = {}
            
            # Source rock potential
            dep_env = self._analyze_depositional_environment(lat, lon)
            if dep_env in ['marine', 'lacustrine']:
                potential['source_rock_potential'] = 0.8
            else:
                potential['source_rock_potential'] = 0.3
            
            # Reservoir potential
            lithology = self._analyze_lithological_composition(lat, lon)
            sandstone_content = lithology.get('sandstone', 0)
            limestone_content = lithology.get('limestone', 0)
            potential['reservoir_potential'] = sandstone_content + 0.5 * limestone_content
            
            # Seal potential
            shale_content = lithology.get('shale', 0)
            potential['seal_potential'] = shale_content
            
            # Thermal maturity
            basin_depth = self._estimate_basin_depth(lat, lon)
            heat_flow = self._estimate_basin_heat_flow(lat, lon)
            thermal_factor = (basin_depth / 5000) * (heat_flow / 60)
            potential['thermal_maturity'] = min(thermal_factor, 1.0)
            
            return potential
            
        except Exception:
            return {'source_rock_potential': 0.5, 'reservoir_potential': 0.5}
    
    def _analyze_gravity_anomaly(self, lat: float, lon: float) -> float:
        """Analyze gravity anomaly for basin detection"""
        try:
            # Sedimentary basins show negative gravity anomalies
            basin_depth = self._estimate_basin_depth(lat, lon)
            sediment_thickness = self._estimate_sediment_thickness(lat, lon)
            
            # Calculate expected gravity anomaly
            density_contrast = -0.4  # g/cm³ (sediments vs basement)
            anomaly = density_contrast * sediment_thickness / 100  # Simplified
            
            return anomaly  # Negative values for basins
            
        except Exception:
            return -15  # Typical basin anomaly
    
    def _analyze_magnetic_signature(self, lat: float, lon: float) -> float:
        """Analyze magnetic signature characteristics"""
        try:
            # Sedimentary basins show subdued magnetic signatures
            sediment_thickness = self._estimate_sediment_thickness(lat, lon)
            
            # Thicker sediments = more subdued magnetics
            magnetic_reduction = min(sediment_thickness / 5000, 1.0)
            return 1.0 - magnetic_reduction  # 0 = completely subdued
            
        except Exception:
            return 0.3  # Subdued signature
    
    def _analyze_seismic_characteristics(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze seismic characteristics of basin"""
        try:
            return {
                'seismic_velocity': self._estimate_seismic_velocity(lat, lon),
                'reflection_character': self._estimate_reflection_character(lat, lon),
                'seismic_transparency': self._estimate_seismic_transparency(lat, lon)
            }
        except Exception:
            return {'seismic_velocity': 3.5, 'reflection_character': 0.7}
    
    def _estimate_basin_heat_flow(self, lat: float, lon: float) -> float:
        """Estimate heat flow in basin"""
        try:
            # Basin heat flow depends on tectonic setting
            boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
            
            if boundary_distance < 5:  # Active rift
                return 80 + np.random.normal(0, 15)  # High heat flow
            elif boundary_distance < 15:  # Passive margin
                return 60 + np.random.normal(0, 10)  # Moderate
            else:  # Stable craton
                return 45 + np.random.normal(0, 8)   # Low
                
        except Exception:
            return 55  # Average continental
    
    def _analyze_subsidence_patterns(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze subsidence characteristics"""
        try:
            basin_type = self._classify_basin_type(lat, lon)
            
            if basin_type == 'rift':
                return {'subsidence_rate': 0.3, 'subsidence_style': 'episodic'}
            elif basin_type == 'foreland':
                return {'subsidence_rate': 0.2, 'subsidence_style': 'continuous'}
            else:
                return {'subsidence_rate': 0.1, 'subsidence_style': 'gradual'}
                
        except Exception:
            return {'subsidence_rate': 0.15, 'subsidence_style': 'gradual'}
    
    def _analyze_fluid_flow_systems(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze fluid flow characteristics"""
        try:
            return {
                'permeability': self._estimate_permeability(lat, lon),
                'porosity': self._estimate_porosity(lat, lon),
                'fluid_pressure': self._estimate_fluid_pressure(lat, lon)
            }
        except Exception:
            return {'permeability': 0.5, 'porosity': 0.2}
    
    def _classify_basin_type(self, lat: float, lon: float) -> str:
        """Classify basin type based on tectonic setting"""
        try:
            boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
            mountain_distance = self._calculate_mountain_range_distance(lat, lon)
            
            if boundary_distance < 5:
                return 'rift'  # Extensional
            elif mountain_distance < 10:
                return 'foreland'  # Compressional
            else:
                return 'intracratonic'  # Stable platform
                
        except Exception:
            return 'intracratonic'
    
    def _analyze_stress_regime(self, lat: float, lon: float) -> str:
        """Analyze regional stress regime"""
        basin_type = self._classify_basin_type(lat, lon)
        
        if basin_type == 'rift':
            return 'extensional'
        elif basin_type == 'foreland':
            return 'compressional'
        else:
            return 'neutral'
    
    def _determine_tectonic_setting(self, lat: float, lon: float) -> str:
        """Determine broader tectonic setting"""
        oceanic_check = self._is_oceanic_simple_check(lat, lon)
        
        if oceanic_check:
            return 'oceanic'
        
        boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
        if boundary_distance < 10:
            return 'active_margin'
        else:
            return 'stable_craton'
    
    def _calculate_active_tectonics_distance(self, lat: float, lon: float) -> float:
        """Calculate distance to active tectonics"""
        return self._calculate_plate_boundary_distance(lat, lon)
    
    def _assess_rift_association(self, lat: float, lon: float) -> float:
        """Assess association with rift systems"""
        boundary_distance = self._calculate_plate_boundary_distance(lat, lon)
        return max(0, 1 - boundary_distance / 10)
    
    def _assess_foreland_characteristics(self, lat: float, lon: float) -> float:
        """Assess foreland basin characteristics"""
        mountain_distance = self._calculate_mountain_range_distance(lat, lon)
        return max(0, 1 - mountain_distance / 15)
    
    def _calculate_exclusion_score(self, lat: float, lon: float) -> float:
        """Calculate score based on exclusion of other geological settings"""
        try:
            score = 1.0  # Start with full score
            
            # Check if it's oceanic (reduce score)
            oceanic_check = self._is_oceanic_simple_check(lat, lon)
            if oceanic_check:
                score -= 0.8
            
            # Check mountain belt proximity
            mountain_distance = self._calculate_mountain_range_distance(lat, lon)
            if mountain_distance < 5:
                score -= 0.3  # Partial reduction for mountain proximity
            
            # Check shield proximity
            shield_distance = self._calculate_shield_distance(lat, lon)
            if shield_distance < 5:
                score -= 0.4  # Partial reduction for shield proximity
            
            return max(0, score)
            
        except Exception:
            return 0.6  # Moderate exclusion score
    
    # Additional helper methods
    def _estimate_basin_shape(self, lat: float, lon: float) -> str:
        """Estimate basin shape"""
        basin_type = self._classify_basin_type(lat, lon)
        
        if basin_type == 'rift':
            return 'linear'
        elif basin_type == 'foreland':
            return 'asymmetric'
        else:
            return 'circular'
    
    def _estimate_aspect_ratio(self, lat: float, lon: float) -> float:
        """Estimate basin aspect ratio (length/width)"""
        basin_type = self._classify_basin_type(lat, lon)
        
        if basin_type == 'rift':
            return 4.0  # Long and narrow
        elif basin_type == 'foreland':
            return 2.5  # Moderately elongated
        else:
            return 1.5  # More equant
    
    def _estimate_basin_symmetry(self, lat: float, lon: float) -> float:
        """Estimate basin symmetry (0-1, 1 = symmetric)"""
        basin_type = self._classify_basin_type(lat, lon)
        
        if basin_type == 'rift':
            return 0.8  # Generally symmetric
        elif basin_type == 'foreland':
            return 0.3  # Highly asymmetric
        else:
            return 0.7  # Moderately symmetric
    
    def _estimate_stratigraphic_complexity(self, lat: float, lon: float) -> float:
        """Estimate stratigraphic complexity"""
        basin_depth = self._estimate_basin_depth(lat, lon)
        return min(basin_depth / 8000, 1.0)  # Deeper = more complex
    
    def _estimate_sequence_count(self, lat: float, lon: float) -> int:
        """Estimate number of stratigraphic sequences"""
        complexity = self._estimate_stratigraphic_complexity(lat, lon)
        return int(3 + complexity * 7)  # 3-10 sequences
    
    def _estimate_unconformities(self, lat: float, lon: float) -> int:
        """Estimate number of major unconformities"""
        complexity = self._estimate_stratigraphic_complexity(lat, lon)
        return int(1 + complexity * 4)  # 1-5 unconformities
    
    def _estimate_seismic_velocity(self, lat: float, lon: float) -> float:
        """Estimate average seismic velocity in basin"""
        sediment_thickness = self._estimate_sediment_thickness(lat, lon)
        
        # Velocity increases with burial depth
        surface_velocity = 2.0  # km/s
        velocity_gradient = 0.6  # km/s per km depth
        avg_depth = sediment_thickness / 2000  # Convert to km
        
        return surface_velocity + velocity_gradient * avg_depth
    
    def _estimate_reflection_character(self, lat: float, lon: float) -> float:
        """Estimate seismic reflection character"""
        complexity = self._estimate_stratigraphic_complexity(lat, lon)
        return complexity  # More complex = better reflections
    
    def _estimate_seismic_transparency(self, lat: float, lon: float) -> float:
        """Estimate seismic transparency"""
        # Uniform lithologies show transparency
        lithology = self._analyze_lithological_composition(lat, lon)
        uniformity = max(lithology.values())  # Dominant lithology fraction
        return uniformity
    
    def _estimate_permeability(self, lat: float, lon: float) -> float:
        """Estimate average permeability"""
        lithology = self._analyze_lithological_composition(lat, lon)
        
        # Permeability based on lithology
        perm = 0.0
        perm += lithology.get('sandstone', 0) * 0.8  # High permeability
        perm += lithology.get('limestone', 0) * 0.5  # Moderate
        perm += lithology.get('shale', 0) * 0.1     # Low
        
        return perm
    
    def _estimate_porosity(self, lat: float, lon: float) -> float:
        """Estimate average porosity"""
        basin_depth = self._estimate_basin_depth(lat, lon)
        
        # Porosity decreases with depth
        surface_porosity = 0.35
        compaction_factor = basin_depth / 10000  # Normalized depth
        return surface_porosity * (1 - 0.7 * compaction_factor)
    
    def _estimate_fluid_pressure(self, lat: float, lon: float) -> float:
        """Estimate fluid pressure regime"""
        basin_depth = self._estimate_basin_depth(lat, lon)
        
        # Deeper basins may have overpressure
        if basin_depth > 4000:
            return 1.2  # Overpressured
        elif basin_depth > 2000:
            return 1.0  # Hydrostatic
        else:
            return 0.9  # Underpressured
    
    def _fallback_basin_check(self, lat: float, lon: float) -> Tuple[bool, Dict[str, Any]]:
        """Fallback basin check using exclusion method"""
        try:
            # Simple exclusion-based check
            oceanic_check = self._is_oceanic_simple_check(lat, lon)
            if oceanic_check:
                return False, {'confidence': 0.7, 'source': 'exclusion_fallback'}
            
            mountain_distance = self._calculate_mountain_range_distance(lat, lon)
            shield_distance = self._calculate_shield_distance(lat, lon)
            
            # If not near mountains or shields, likely sedimentary basin
            if mountain_distance > 5 and shield_distance > 5:
                metrics = {
                    'sediment_thickness': 1800,
                    'basin_depth': 2500,
                    'basin_type': 'intracratonic',
                    'confidence': 0.6,
                    'source': 'exclusion_fallback'
                }
                return True, metrics
            else:
                metrics = {
                    'confidence': 0.4,
                    'source': 'exclusion_fallback'
                }
                return False, metrics
                
        except Exception:
            return False, {'confidence': 0.3, 'source': 'error_fallback'}
    
    def _is_plate_boundary_location(self, lat: float, lon: float) -> Tuple[bool, Dict[str, Any]]:
        """Advanced plate boundary detection using real-time plate tectonics data and seismicity analysis
        
        Args:
            lat: Latitude in decimal degrees
            lon: Longitude in decimal degrees
            
        Returns:
            Tuple of (is_plate_boundary: bool, tectonic_analysis: Dict)
        """
        try:
            # Query real-time plate tectonic databases
            plate_motion_data = self._query_plate_motion_database(lat, lon)
            
            # Analyze seismicity patterns
            seismicity_analysis = self._analyze_seismicity_patterns(lat, lon)
            
            # Geophysical signature analysis
            geophysical_signatures = self._analyze_plate_boundary_geophysics(lat, lon)
            
            # Real-time GPS/geodetic data analysis
            geodetic_analysis = self._analyze_geodetic_deformation(lat, lon)
            
            # Volcanic activity correlation
            volcanic_correlation = self._analyze_volcanic_activity_correlation(lat, lon)
            
            # Comprehensive plate boundary classification
            is_plate_boundary = self._classify_plate_boundary_location(
                plate_motion_data, seismicity_analysis, geophysical_signatures,
                geodetic_analysis, volcanic_correlation
            )
            
            # Compile comprehensive tectonic analysis
            tectonic_analysis = {
                **plate_motion_data,
                **seismicity_analysis,
                **geophysical_signatures,
                **geodetic_analysis,
                **volcanic_correlation,
                'confidence': self._calculate_plate_boundary_confidence(
                    plate_motion_data, seismicity_analysis, geophysical_signatures,
                    geodetic_analysis, volcanic_correlation
                )
            }
            
            return is_plate_boundary, tectonic_analysis
            
        except Exception as e:
            self.logger.warning(f"Advanced plate boundary detection failed: {e}")
            # Fallback to simplified boundary regions
            return self._fallback_plate_boundary_check(lat, lon)
    
    def _query_plate_motion_database(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query plate motion database for local plate kinematics"""
        try:
            motion_data = {}
            
            # Query model database for plate motion models
            if hasattr(self, 'model_database') and self.model_database:
                motion_models = self.model_database.search_models({
                    'model_type': 'plate_motion',
                    'region': self._determine_tectonic_region(lat, lon)
                })
                
                if motion_models:
                    motion_data = self._query_plate_motion_model(motion_models[0], lat, lon)
                    motion_data['data_source'] = 'database'
            
            # Query data integration pipeline for plate boundaries
            if hasattr(self, 'data_pipeline') and self.data_pipeline:
                plates_layer = self.data_pipeline.get_layer('plate_boundaries')
                if plates_layer:
                    motion_data.update(
                        self._extract_plate_boundary_data(plates_layer, lat, lon)
                    )
            
            # Fallback to global plate motion model
            if not motion_data or 'plate_velocity' not in motion_data:
                motion_data.update(self._estimate_global_plate_motion(lat, lon))
            
            return motion_data
            
        except Exception as e:
            self.logger.debug(f"Plate motion database query failed: {e}")
            return self._estimate_global_plate_motion(lat, lon)
    
    def _analyze_seismicity_patterns(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze seismicity patterns for plate boundary detection"""
        try:
            seismicity_data = {}
            
            # Query real-time seismicity data
            seismicity_data['earthquake_density'] = self._calculate_earthquake_density(lat, lon)
            
            # Earthquake magnitude distribution
            seismicity_data['magnitude_distribution'] = self._analyze_magnitude_distribution(lat, lon)
            
            # Focal mechanism analysis
            seismicity_data['focal_mechanisms'] = self._analyze_focal_mechanisms(lat, lon)
            
            # Earthquake depth distribution
            seismicity_data['depth_distribution'] = self._analyze_earthquake_depths(lat, lon)
            
            # Seismic belt correlation
            seismicity_data['seismic_belt_association'] = self._assess_seismic_belt_association(lat, lon)
            
            # Temporal seismicity patterns
            seismicity_data['temporal_patterns'] = self._analyze_temporal_seismicity(lat, lon)
            
            # Aftershock sequences analysis
            seismicity_data['aftershock_characteristics'] = self._analyze_aftershock_patterns(lat, lon)
            
            return seismicity_data
            
        except Exception as e:
            self.logger.debug(f"Seismicity analysis failed: {e}")
            return {'earthquake_density': 0.5, 'magnitude_distribution': 'normal'}
    
    def _analyze_plate_boundary_geophysics(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze geophysical signatures of plate boundaries"""
        try:
            geophysical_data = {}
            
            # Gravity field analysis (plate boundaries show distinct patterns)
            geophysical_data['gravity_gradient'] = self._analyze_gravity_gradient(lat, lon)
            
            # Magnetic field analysis (linear magnetic anomalies at spreading centers)
            geophysical_data['magnetic_lineations'] = self._analyze_magnetic_lineations(lat, lon)
            
            # Heat flow characteristics (elevated at active boundaries)
            geophysical_data['heat_flow_anomaly'] = self._analyze_heat_flow_anomaly(lat, lon)
            
            # Topographic signatures
            geophysical_data['topographic_signature'] = self._analyze_boundary_topography(lat, lon)
            
            # Crustal thickness variations
            geophysical_data['crustal_thickness_gradient'] = self._analyze_crustal_thickness_gradient(lat, lon)
            
            # Geoid anomalies
            geophysical_data['geoid_signature'] = self._analyze_geoid_signature(lat, lon)
            
            return geophysical_data
            
        except Exception as e:
            self.logger.debug(f"Geophysical analysis failed: {e}")
            return {'gravity_gradient': 0.5, 'heat_flow_anomaly': 0.5}
    
    def _analyze_geodetic_deformation(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze geodetic deformation data for plate boundary detection"""
        try:
            geodetic_data = {}
            
            # GPS velocity analysis
            geodetic_data['gps_velocity'] = self._analyze_gps_velocity_field(lat, lon)
            
            # Strain rate analysis
            geodetic_data['strain_rates'] = self._analyze_strain_rates(lat, lon)
            
            # InSAR deformation analysis
            geodetic_data['insar_deformation'] = self._analyze_insar_deformation(lat, lon)
            
            # Plate motion consistency
            geodetic_data['motion_consistency'] = self._assess_plate_motion_consistency(lat, lon)
            
            # Deformation style
            geodetic_data['deformation_style'] = self._classify_deformation_style(lat, lon)
            
            return geodetic_data
            
        except Exception as e:
            self.logger.debug(f"Geodetic analysis failed: {e}")
            return {'gps_velocity': 5.0, 'strain_rates': 'low'}
    
    def _analyze_volcanic_activity_correlation(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze correlation with volcanic activity"""
        try:
            volcanic_data = {}
            
            # Distance to active volcanoes
            volcanic_data['volcano_proximity'] = self._calculate_volcano_proximity(lat, lon)
            
            # Volcanic arc association
            volcanic_data['volcanic_arc_association'] = self._assess_volcanic_arc_association(lat, lon)
            
            # Recent volcanic activity
            volcanic_data['recent_volcanism'] = self._assess_recent_volcanism(lat, lon)
            
            # Geothermal activity
            volcanic_data['geothermal_activity'] = self._assess_geothermal_activity(lat, lon)
            
            return volcanic_data
            
        except Exception as e:
            self.logger.debug(f"Volcanic activity analysis failed: {e}")
            return {'volcano_proximity': 0.3, 'volcanic_arc_association': 0.2}
    
    def _classify_plate_boundary_location(self, plate_motion_data: Dict[str, Any],
                                        seismicity_data: Dict[str, Any],
                                        geophysical_data: Dict[str, Any],
                                        geodetic_data: Dict[str, Any],
                                        volcanic_data: Dict[str, Any]) -> bool:
        """Comprehensive plate boundary classification using multiple criteria"""
        try:
            # Multi-criteria plate boundary classification
            boundary_score = 0.0
            weights = {
                'seismicity': 0.30,
                'plate_motion': 0.25,
                'geophysical': 0.20,
                'geodetic': 0.15,
                'volcanic': 0.10
            }
            
            # Seismicity criterion (primary for active boundaries)
            earthquake_density = seismicity_data.get('earthquake_density', 0)
            if earthquake_density > 0.8:  # Very high seismicity
                boundary_score += weights['seismicity'] * 1.0
            elif earthquake_density > 0.6:  # High seismicity
                boundary_score += weights['seismicity'] * 0.8
            elif earthquake_density > 0.4:  # Moderate seismicity
                boundary_score += weights['seismicity'] * 0.6
            elif earthquake_density > 0.2:  # Low seismicity
                boundary_score += weights['seismicity'] * 0.3
            
            # Plate motion criterion
            plate_velocity = plate_motion_data.get('plate_velocity', 0)
            boundary_distance = plate_motion_data.get('boundary_distance', 50)
            
            if boundary_distance < 50:  # Very close to known boundary
                boundary_score += weights['plate_motion'] * 1.0
            elif boundary_distance < 100:  # Close to boundary
                boundary_score += weights['plate_motion'] * 0.7
            elif boundary_distance < 200:  # Moderate distance
                boundary_score += weights['plate_motion'] * 0.4
            
            if plate_velocity > 50:  # High velocity (mm/yr)
                boundary_score += weights['plate_motion'] * 0.3  # Additional score
            
            # Geophysical signatures
            gravity_gradient = geophysical_data.get('gravity_gradient', 0.5)
            heat_flow_anomaly = geophysical_data.get('heat_flow_anomaly', 0.5)
            geophysical_score = (gravity_gradient + heat_flow_anomaly) / 2
            boundary_score += weights['geophysical'] * geophysical_score
            
            # Geodetic deformation
            gps_velocity = geodetic_data.get('gps_velocity', 5.0)
            if gps_velocity > 20:  # High GPS velocity
                boundary_score += weights['geodetic'] * 1.0
            elif gps_velocity > 10:  # Moderate velocity
                boundary_score += weights['geodetic'] * 0.7
            elif gps_velocity > 5:  # Low velocity
                boundary_score += weights['geodetic'] * 0.4
            
            # Volcanic activity correlation
            volcano_proximity = volcanic_data.get('volcano_proximity', 0.3)
            volcanic_arc = volcanic_data.get('volcanic_arc_association', 0.2)
            volcanic_score = max(volcano_proximity, volcanic_arc)
            boundary_score += weights['volcanic'] * volcanic_score
            
            # Classification threshold for plate boundaries
            boundary_threshold = 0.7
            return boundary_score > boundary_threshold
            
        except Exception:
            # Fallback to simple distance-based classification
            boundary_distance = plate_motion_data.get('boundary_distance', 100)
            return boundary_distance < 100
    
    def _calculate_plate_boundary_confidence(self, plate_motion_data: Dict[str, Any],
                                           seismicity_data: Dict[str, Any],
                                           geophysical_data: Dict[str, Any],
                                           geodetic_data: Dict[str, Any],
                                           volcanic_data: Dict[str, Any]) -> float:
        """Calculate confidence level for plate boundary classification"""
        try:
            confidence = 0.5  # Base confidence
            
            # Increase confidence based on data quality
            if plate_motion_data.get('data_source') == 'database':
                confidence += 0.15  # High-quality database
            
            # Confidence from real-time seismicity data
            if seismicity_data.get('earthquake_density', 0) > 0.1:
                confidence += 0.15  # Active seismicity
            
            # Confidence from multiple indicators agreement
            indicators = [
                1.0 if seismicity_data.get('earthquake_density', 0) > 0.5 else 0.0,
                1.0 if plate_motion_data.get('boundary_distance', 100) < 100 else 0.0,
                geophysical_data.get('gravity_gradient', 0.5),
                1.0 if geodetic_data.get('gps_velocity', 5) > 10 else 0.0
            ]
            
            indicator_agreement = sum(1 for i in indicators if i > 0.6) / len(indicators)
            confidence += 0.2 * indicator_agreement
            
            return min(confidence, 1.0)
            
        except Exception:
            return 0.5
    
    # Helper methods for plate boundary analysis
    def _estimate_global_plate_motion(self, lat: float, lon: float) -> Dict[str, Any]:
        """Estimate plate motion using global plate model"""
        try:
            # Major plate boundaries and their characteristics
            plate_boundaries = {
                'pacific_ring_of_fire': {
                    'type': 'convergent',
                    'boundaries': [
                        {'center': (35, -118), 'radius': 10, 'velocity': 40},  # San Andreas
                        {'center': (39, 142), 'radius': 8, 'velocity': 80},    # Japan
                        {'center': (-15, -75), 'radius': 12, 'velocity': 70},  # Peru-Chile
                        {'center': (61, -150), 'radius': 15, 'velocity': 60}   # Alaska
                    ]
                },
                'mid_ocean_ridges': {
                    'type': 'divergent',
                    'boundaries': [
                        {'center': (0, -30), 'radius': 20, 'velocity': 25},   # Mid-Atlantic
                        {'center': (-15, -110), 'radius': 15, 'velocity': 120}, # East Pacific Rise
                        {'center': (-35, 70), 'radius': 12, 'velocity': 55}    # Southwest Indian
                    ]
                },
                'transform_boundaries': {
                    'type': 'transform',
                    'boundaries': [
                        {'center': (36, -120), 'radius': 5, 'velocity': 35},  # San Andreas
                        {'center': (40, -30), 'radius': 8, 'velocity': 20}     # Azores-Gibraltar
                    ]
                }
            }
            
            min_distance = float('inf')
            closest_boundary = None
            boundary_type = 'unknown'
            
            # Find closest plate boundary
            for boundary_group, group_data in plate_boundaries.items():
                for boundary in group_data['boundaries']:
                    center_lat, center_lon = boundary['center']
                    distance = np.sqrt((lat - center_lat)**2 + (lon - center_lon)**2)
                    
                    if distance < min_distance:
                        min_distance = distance
                        closest_boundary = boundary
                        boundary_type = group_data['type']
            
            return {
                'boundary_distance': min_distance * 111,  # Convert to km
                'plate_velocity': closest_boundary['velocity'] if closest_boundary else 10,
                'boundary_type': boundary_type,
                'confidence': 0.7 if min_distance < 10 else 0.5,
                'data_source': 'global_model'
            }
            
        except Exception:
            return {
                'boundary_distance': 500,
                'plate_velocity': 10,
                'boundary_type': 'intraplate',
                'confidence': 0.3,
                'data_source': 'fallback'
            }
    
    def _calculate_earthquake_density(self, lat: float, lon: float) -> float:
        """Calculate earthquake density in surrounding area"""
        try:
            # Simplified earthquake density based on known seismic zones
            seismic_zones = [
                {'center': (35, -118), 'radius': 5, 'activity': 0.9},   # California
                {'center': (39, 142), 'radius': 8, 'activity': 1.0},     # Japan
                {'center': (-15, -75), 'radius': 10, 'activity': 0.8},   # Peru-Chile
                {'center': (61, -150), 'radius': 12, 'activity': 0.7},   # Alaska
                {'center': (38, 30), 'radius': 6, 'activity': 0.6},      # Turkey
                {'center': (28, 84), 'radius': 8, 'activity': 0.5},      # Himalayas
            ]
            
            max_activity = 0.0
            for zone in seismic_zones:
                center_lat, center_lon = zone['center']
                distance = np.sqrt((lat - center_lat)**2 + (lon - center_lon)**2)
                
                if distance <= zone['radius']:
                    # Activity decreases with distance from center
                    distance_factor = 1.0 - (distance / zone['radius'])
                    activity = zone['activity'] * distance_factor
                    max_activity = max(max_activity, activity)
            
            return max_activity
            
        except Exception:
            return 0.1  # Background seismicity
    
    def _analyze_magnitude_distribution(self, lat: float, lon: float) -> str:
        """Analyze earthquake magnitude distribution"""
        try:
            earthquake_density = self._calculate_earthquake_density(lat, lon)
            
            if earthquake_density > 0.8:
                return 'high_magnitude'  # Capable of large earthquakes
            elif earthquake_density > 0.5:
                return 'moderate_magnitude'
            else:
                return 'low_magnitude'
                
        except Exception:
            return 'normal'
    
    def _analyze_focal_mechanisms(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze focal mechanism characteristics"""
        try:
            # Estimate focal mechanism based on tectonic setting
            motion_data = self._estimate_global_plate_motion(lat, lon)
            boundary_type = motion_data.get('boundary_type', 'unknown')
            
            if boundary_type == 'convergent':
                return {'thrust': 0.7, 'strike_slip': 0.2, 'normal': 0.1}
            elif boundary_type == 'divergent':
                return {'normal': 0.6, 'strike_slip': 0.3, 'thrust': 0.1}
            elif boundary_type == 'transform':
                return {'strike_slip': 0.8, 'normal': 0.1, 'thrust': 0.1}
            else:
                return {'thrust': 0.4, 'normal': 0.3, 'strike_slip': 0.3}
                
        except Exception:
            return {'thrust': 0.33, 'normal': 0.33, 'strike_slip': 0.34}
    
