    def _calculate_volcano_proximity(self, lat: float, lon: float) -> float:
        """Calculate proximity to active volcanoes"""
        try:
            # Major volcanic regions
            volcanic_regions = [
                {'center': (61, -150), 'radius': 10, 'activity': 0.9},  # Alaska volcanoes
                {'center': (45, -122), 'radius': 8, 'activity': 0.7},   # Cascades
                {'center': (14, -90), 'radius': 12, 'activity': 0.8},   # Central America
                {'center': (39, 142), 'radius': 15, 'activity': 1.0},   # Japan
                {'center': (-6, 106), 'radius': 20, 'activity': 0.9},   # Indonesia
                {'center': (38, 15), 'radius': 10, 'activity': 0.6},    # Italy
            ]
            
            max_proximity = 0.0
            for region in volcanic_regions:
                center_lat, center_lon = region['center']
                distance = np.sqrt((lat - center_lat)**2 + (lon - center_lon)**2)
                
                if distance <= region['radius']:
                    distance_factor = 1.0 - (distance / region['radius'])
                    proximity = region['activity'] * distance_factor
                    max_proximity = max(max_proximity, proximity)
            
            return max_proximity
            
        except Exception:
            return 0.2  # Low proximity
    
