    def _determine_climate_zone(self, lat: float, lon: float) -> str:
        """Determine climate zone"""
        try:
            abs_lat = abs(lat)
            if abs_lat < 23.5:
                return 'tropical'
            elif abs_lat < 35:
                return 'subtropical'
            elif abs_lat < 60:
                return 'temperate'
            else:
                return 'polar'
        except Exception:
            return 'temperate'
    
