    def _query_usgs_geology_api(self, lat: float, lon: float) -> Optional[Dict]:
        """Query USGS National Geologic Map Database via web services"""
        try:
            import requests
            import xml.etree.ElementTree as ET
            
            # USGS GeoSciML web service endpoint
            base_url = "https://mrdata.usgs.gov/wfs/geology"
            params = {
                'service': 'WFS',
                'version': '2.0.0',
                'request': 'GetFeature',
                'typeName': 'geology:GeologicUnit',
                'outputFormat': 'application/json',
                'CQL_FILTER': f'INTERSECTS(geometry, POINT({lon} {lat}))',
                'maxFeatures': 1
            }
            
            response = requests.get(base_url, params=params, timeout=10)
            if response.status_code == 200:
                data = response.json()
                if data.get('features'):
                    feature = data['features'][0]
                    properties = feature.get('properties', {})
                    
                    return {
                        'province': self._extract_geological_province(properties),
                        'lithology': properties.get('lithology', ''),
                        'age': properties.get('min_age', ''),
                        'description': properties.get('description', ''),
                        'source': 'usgs_geology_api'
                    }
        except Exception as e:
            logging.warning(f"USGS geology API query failed: {e}")
            return None
    
