    def _query_thermal_database(self, lat: float, lon: float, current_time: datetime) -> Optional[float]:
        """Query historical thermal data from database"""
        try:
            if hasattr(self, 'database') and self.database:
                query = """
                SELECT avg(temperature_c) as avg_temp
                FROM thermal_measurements 
                WHERE ST_DWithin(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 5000)
                AND measurement_time BETWEEN %s AND %s
                """
                time_window = timedelta(hours=2)
                start_time = current_time - time_window
                end_time = current_time + time_window
                
                result = self.database.execute_query(
                    query, (lon, lat, start_time, end_time)
                )
                if result and result[0]['avg_temp']:
                    return float(result[0]['avg_temp'])
            return None
        except Exception:
            return None

    def _apply_thermal_corrections(self, temp: float, lat: float, lon: float, 
                                 current_time: datetime) -> float:
        """Apply atmospheric and topographic corrections to temperature"""
        try:
            import math
            
            # Atmospheric corrections
            elevation = self._get_elevation(lat, lon) or 0
            atmospheric_correction = -0.0065 * elevation  # Standard lapse rate
            
            # Solar angle correction
            hour = current_time.hour
            solar_angle_factor = math.cos(math.pi * (hour - 12) / 12) * 0.5 + 0.5
            
            # Topographic shadowing (simplified)
            slope_aspect = self._get_slope_aspect(lat, lon)
            if slope_aspect:
                shadow_correction = slope_aspect.get('shadow_factor', 1.0)
            else:
                shadow_correction = 1.0
            
            corrected_temp = temp + atmospheric_correction
            corrected_temp *= (0.8 + 0.2 * solar_angle_factor * shadow_correction)
            
            return corrected_temp
        except Exception:
            return temp

    def _ml_enhanced_thermal_model(self, lat: float, lon: float, current_time: datetime) -> Optional[float]:
        """ML-enhanced thermal model for missing data"""
        try:
            if hasattr(self, 'model_manager') and self.model_manager:
                features = {
                    'latitude': lat,
                    'longitude': lon,
                    'hour': current_time.hour,
                    'day_of_year': current_time.timetuple().tm_yday,
                    'month': current_time.month
                }
                
                prediction = self.model_manager.predict('thermal_model', features)
                if prediction and 'temperature' in prediction:
                    return prediction['temperature']
            
            # Fallback empirical model
            import math
            month = current_time.month
            hour = current_time.hour
            
            base_temp = 15.0 - 0.6 * abs(lat)
            seasonal_variation = 20.0 * math.cos(2 * math.pi * (month - 7) / 12)
            diurnal_variation = 10.0 * math.cos(2 * math.pi * (hour - 14) / 24)
            
            return base_temp + seasonal_variation + diurnal_variation
        except Exception:
            return None

    def _get_soil_properties(self, lat: float, lon: float) -> Optional[Dict]:
        """Get soil thermal properties from database or maps"""
        try:
            if hasattr(self, 'database') and self.database:
                query = """
                SELECT thermal_conductivity, thermal_diffusivity, 
                       bulk_density, moisture_content, soil_type
                FROM soil_properties 
                WHERE ST_DWithin(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1000)
                ORDER BY ST_Distance(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326))
                LIMIT 1
                """
                result = self.database.execute_query(query, (lon, lat, lon, lat))
                if result and result[0]:
                    return {
                        'thermal_conductivity': float(result[0]['thermal_conductivity'] or 1.5),
                        'thermal_diffusivity': float(result[0]['thermal_diffusivity'] or 6e-7),
                        'bulk_density': float(result[0]['bulk_density'] or 1400),
                        'moisture_content': float(result[0]['moisture_content'] or 0.15),
                        'soil_type': result[0]['soil_type'] or 'mixed'
                    }
            return None
        except Exception:
            return None

    def _calculate_thermal_profile(self, surface_temp: float, depths: np.ndarray,
                                 soil_properties: Dict, current_time: datetime, lat: float) -> np.ndarray:
        """Calculate thermal profile with depth using heat equation"""
        try:
            import numpy as np
            import math
            
            alpha = soil_properties['thermal_diffusivity']
            day_of_year = current_time.timetuple().tm_yday
            
            # Analytical solution for seasonal temperature variation
            annual_amplitude = 10.0  # Annual surface temperature amplitude
            angular_freq = 2 * math.pi / (365.25 * 24 * 3600)  # rad/s
            
            thermal_profile = np.zeros_like(depths)
            for i, depth in enumerate(depths):
                # Damping and phase lag with depth
                damping_depth = math.sqrt(2 * alpha / angular_freq)
                amplitude_factor = math.exp(-depth / damping_depth)
                phase_lag = depth / damping_depth  # radians
                
                # Seasonal variation at depth
                seasonal_component = annual_amplitude * amplitude_factor * math.cos(
                    2 * math.pi * (day_of_year - 80) / 365.25 - phase_lag
                )
                
                # Base temperature + seasonal variation
                thermal_profile[i] = surface_temp * 0.9 + seasonal_component
                
                # Geothermal gradient (approximately 25°C/km)
                thermal_profile[i] += depth * 0.025
            
            return thermal_profile
        except Exception:
            # Simple linear model fallback
            return surface_temp * 0.9 + depths * 0.01

    def _calculate_seasonal_soil_correction(self, current_time: datetime, lat: float,
                                          soil_properties: Dict) -> float:
        """Calculate seasonal correction for soil temperature"""
        try:
            import math
            
            day_of_year = current_time.timetuple().tm_yday
            soil_type = soil_properties.get('soil_type', 'mixed')
            
            # Soil-type specific seasonal response
            soil_factors = {
                'clay': {'amplitude': 0.8, 'phase_lag': 30},
                'sand': {'amplitude': 1.2, 'phase_lag': 10},
                'loam': {'amplitude': 1.0, 'phase_lag': 20},
                'mixed': {'amplitude': 1.0, 'phase_lag': 20}
            }
            
            factor_params = soil_factors.get(soil_type, soil_factors['mixed'])
            
            # Seasonal correction with latitude dependence
            latitude_factor = 1.0 - 0.3 * abs(lat) / 90.0
            seasonal_correction = 1.0 + 0.1 * factor_params['amplitude'] * latitude_factor * math.cos(
                2 * math.pi * (day_of_year - 80 - factor_params['phase_lag']) / 365.25
            )
            
            return max(0.7, min(1.3, seasonal_correction))
        except Exception:
            return 1.0

    def _calculate_moisture_thermal_effect(self, moisture_content: float, surface_temp: float) -> float:
        """Calculate moisture effect on soil thermal properties"""
        try:
            # Higher moisture increases thermal conductivity
            moisture_factor = 1.0 + moisture_content * 0.5
            
            # Temperature-dependent moisture evaporation effects
            if surface_temp > 25.0:
                evap_cooling = (surface_temp - 25.0) * 0.02
                moisture_factor *= (1.0 - evap_cooling * moisture_content)
            
            return max(0.8, min(1.2, moisture_factor))
        except Exception:
            return 1.0

    def _validate_soil_temperature(self, temp: float, lat: float, lon: float,
                                 current_time: datetime) -> Dict:
        """Validate soil temperature against historical patterns"""
        try:
            if hasattr(self, 'database') and self.database:
                # Query historical temperature range for location and time
                query = """
                SELECT min(temperature_c) as min_temp, max(temperature_c) as max_temp,
                       avg(temperature_c) as avg_temp, stddev(temperature_c) as std_temp
                FROM soil_temperature_history
                WHERE ST_DWithin(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 10000)
                AND extract(month from measurement_time) = %s
                """
                result = self.database.execute_query(
                    query, (lon, lat, current_time.month)
                )
                
                if result and result[0]:
                    hist_data = result[0]
                    min_temp = hist_data['min_temp']
                    max_temp = hist_data['max_temp']
                    avg_temp = hist_data['avg_temp']
                    std_temp = hist_data['std_temp'] or 5.0
                    
                    # Check if temperature is within reasonable bounds
                    lower_bound = avg_temp - 3 * std_temp
                    upper_bound = avg_temp + 3 * std_temp
                    
                    if lower_bound <= temp <= upper_bound:
                        return {'valid': True, 'adjusted_value': temp}
                    else:
                        # Adjust to nearest bound
                        adjusted_temp = max(lower_bound, min(temp, upper_bound))
                        return {'valid': False, 'adjusted_value': adjusted_temp}
            
            return {'valid': True, 'adjusted_value': temp}
        except Exception:
            return {'valid': True, 'adjusted_value': temp}

    def _get_rock_thermal_properties(self, lat: Optional[float], lon: Optional[float]) -> Dict:
        """Get rock-specific thermal expansion coefficients"""
        try:
            if lat and lon and hasattr(self, 'database') and self.database:
                query = """
                SELECT rock_type, linear_expansion_coeff, volumetric_expansion_coeff,
                       anisotropy_factor, min_expansion, max_expansion
                FROM rock_thermal_properties
                WHERE ST_DWithin(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 5000)
                ORDER BY ST_Distance(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326))
                LIMIT 1
                """
                result = self.database.execute_query(query, (lon, lat, lon, lat))
                if result and result[0]:
                    return {
                        'linear_coeff': float(result[0]['linear_expansion_coeff'] or 1e-5),
                        'volumetric_coeff': float(result[0]['volumetric_expansion_coeff'] or 3e-5),
                        'anisotropy': float(result[0]['anisotropy_factor'] or 1.0),
                        'min_expansion': float(result[0]['min_expansion'] or 1e-6),
                        'max_expansion': float(result[0]['max_expansion'] or 1e-4),
                        'rock_type': result[0]['rock_type'] or 'granite'
                    }
            
            # Default values for typical crustal rocks
            return {
                'linear_coeff': 1e-5,      # /°C for granite/basalt
                'volumetric_coeff': 3e-5,  # /°C
                'anisotropy': 1.0,
                'min_expansion': 1e-6,
                'max_expansion': 1e-4,
                'rock_type': 'mixed'
            }
        except Exception:
            return {
                'linear_coeff': 1e-5,
                'volumetric_coeff': 3e-5,
                'anisotropy': 1.0,
                'min_expansion': 1e-6,
                'max_expansion': 1e-4,
                'rock_type': 'mixed'
            }

    def _calculate_pressure_thermal_coupling(self, thermal_data: Dict, rock_properties: Dict) -> float:
        """Calculate pressure-temperature coupling effects"""
        try:
            pressure = thermal_data.get('lithostatic_pressure', 0.0)
            temperature = thermal_data.get('land_surface_temperature', 15.0)
            
            # Pressure-dependent thermal expansion (higher P reduces expansion)
            pressure_factor = 1.0 - pressure * 1e-9  # GPa to dimensionless
            
            # Temperature-dependent pressure coupling
            temp_coupling = 1.0 + abs(temperature - 15.0) * 0.001
            
            return pressure_factor * temp_coupling - 1.0
        except Exception:
            return 0.0

    def _calculate_moisture_expansion_coupling(self, thermal_data: Dict, rock_properties: Dict) -> float:
        """Calculate moisture-thermal expansion coupling"""
        try:
            moisture = thermal_data.get('soil_moisture', 0.15)
            temperature = thermal_data.get('soil_temperature', 15.0)
            
            # Moisture reduces thermal expansion through increased thermal mass
            moisture_damping = 1.0 - moisture * 0.2
            
            # Temperature-dependent moisture effects
            if temperature > 20.0:
                evap_effect = (temperature - 20.0) * 0.005
                moisture_damping *= (1.0 + evap_effect)
            
            return moisture_damping - 1.0
        except Exception:
            return 0.0

    def _get_default_thermal_expansion(self, thermal_data: Dict) -> float:
        """Get default thermal expansion factor"""
        try:
            # Use any available temperature data
            temp_gradient = thermal_data.get('temperature_gradient', 5.0)
            return temp_gradient * 1e-5  # Basic linear expansion
        except Exception:
            return 5e-5  # Conservative default

    def _log_thermal_error(self, method: str, error: Exception, *args) -> None:
        """Log thermal analysis errors with context"""
        try:
            import logging
            logger = logging.getLogger(__name__)
            
            error_context = {
                'method': method,
                'error_type': type(error).__name__,
                'error_message': str(error),
                'arguments': str(args),
                'timestamp': datetime.now().isoformat()
            }
            
            logger.error(f"Thermal analysis error in {method}: {error_context}")
            
            # Database logging if available
            if hasattr(self, 'database') and self.database:
                self.database.log_error('thermal_analysis', error_context)
                
        except Exception:
            pass  # Prevent error logging from breaking the main process

    def _calculate_atmospheric_thermal_effects(self, current_time: datetime, thermal_data: Dict) -> float:
        """Calculate atmospheric effects on thermal stress"""
        try:
            # Cloud cover effects
            cloud_cover = thermal_data.get('cloud_cover', 0.5)
            cloud_effect = -cloud_cover * 0.1  # Clouds reduce thermal stress
            
            # Wind effects on surface cooling
            wind_speed = thermal_data.get('wind_speed', 5.0)  # m/s
            wind_cooling = min(wind_speed * 0.02, 0.1)
            
            # Humidity effects
            humidity = thermal_data.get('relative_humidity', 0.6)
            humidity_effect = humidity * 0.05
            
            return cloud_effect - wind_cooling + humidity_effect
        except Exception:
            return 0.0

    def _get_surface_thermal_correction(self, lat: Optional[float], lon: Optional[float]) -> float:
        """Get surface material thermal correction factor"""
        try:
            if lat and lon and hasattr(self, 'database') and self.database:
                query = """
                SELECT surface_material, albedo, emissivity, thermal_inertia
                FROM surface_properties
                WHERE ST_DWithin(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2000)
                ORDER BY ST_Distance(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326))
                LIMIT 1
                """
                result = self.database.execute_query(query, (lon, lat, lon, lat))
                if result and result[0]:
                    albedo = float(result[0]['albedo'] or 0.3)
                    emissivity = float(result[0]['emissivity'] or 0.9)
                    thermal_inertia = float(result[0]['thermal_inertia'] or 1.0)
                    
                    # Combined surface correction
                    return (1.0 - albedo) * emissivity * thermal_inertia
            
            return 1.0  # Default correction
        except Exception:
            return 1.0

    def _calculate_topographic_thermal_effect(self, thermal_data: Dict) -> float:
        """Calculate topographic effects on thermal stress"""
        try:
            elevation = thermal_data.get('elevation', 0.0)
            slope = thermal_data.get('slope_degrees', 0.0)
            aspect = thermal_data.get('aspect_degrees', 180.0)  # South-facing default
            
            # Elevation cooling effect
            elevation_factor = 1.0 - elevation * 2e-5  # ~0.02 per km
            
            # Slope and aspect effects on solar heating
            import math
            slope_rad = math.radians(slope)
            aspect_rad = math.radians(aspect)
            
            # South-facing slopes get more heating (Northern hemisphere assumption)
            aspect_factor = 1.0 + 0.1 * math.cos(aspect_rad) * math.sin(slope_rad)
            
            return elevation_factor * aspect_factor
        except Exception:
            return 1.0

    def _calculate_latitude_thermal_scaling(self, lat: float) -> float:
        """Calculate latitude-dependent thermal scaling"""
        try:
            import math
            # Thermal stress decreases with latitude due to lower solar angles
            lat_factor = math.cos(math.radians(abs(lat))) ** 0.5
            return max(0.3, min(1.0, lat_factor))
        except Exception:
            return 1.0

    def _get_climate_zone_correction(self, lat: float) -> float:
        """Get climate zone-specific correction factor"""
        try:
            abs_lat = abs(lat)
            
            # Climate zone corrections
            if abs_lat < 23.5:  # Tropical
                return 1.2
            elif abs_lat < 40.0:  # Subtropical
                return 1.1
            elif abs_lat < 60.0:  # Temperate
                return 1.0
            else:  # Polar
                return 0.7
        except Exception:
            return 1.0

    def _calculate_climate_oscillation_effect(self, current_time: datetime, lat: float) -> float:
        """Calculate multi-year climate oscillation effects"""
        try:
            import math
            
            year = current_time.year
            
            # Advanced multi-oscillation climate modeling system
            oscillation_effects = {}
            
            # 1. El Niño/Southern Oscillation (ENSO) - Comprehensive modeling
            enso_data = self._calculate_enso_index(current_time, lat)
            oscillation_effects['enso'] = enso_data
            
            # 2. Pacific Decadal Oscillation (PDO) - Advanced modeling
            pdo_data = self._calculate_pdo_index(current_time, lat)
            oscillation_effects['pdo'] = pdo_data
            
            # 3. North Atlantic Oscillation (NAO) - Advanced modeling
            nao_data = self._calculate_nao_index(current_time, lat)
            oscillation_effects['nao'] = nao_data
            
            # 4. Atlantic Multidecadal Oscillation (AMO)
            amo_data = self._calculate_amo_index(current_time, lat)
            oscillation_effects['amo'] = amo_data
            
            # 5. Arctic Oscillation (AO)
            ao_data = self._calculate_ao_index(current_time, lat)
            oscillation_effects['ao'] = ao_data
            
            # 6. Indian Ocean Dipole (IOD)
            iod_data = self._calculate_iod_index(current_time, lat)
            oscillation_effects['iod'] = iod_data
            
            # 7. Madden-Julian Oscillation (MJO)
            mjo_data = self._calculate_mjo_index(current_time, lat)
            oscillation_effects['mjo'] = mjo_data
            
            # Calculate teleconnection patterns and interactions
            teleconnection_effects = self._calculate_teleconnection_patterns(oscillation_effects, lat)
            
            # Weighted combination with regional amplification factors
            total_effect = self._combine_oscillation_effects(oscillation_effects, teleconnection_effects, lat)
            
            # ML-enhanced prediction validation
            ml_validated_effect = self._validate_oscillation_with_ml(total_effect, oscillation_effects, current_time, lat)
            
            return ml_validated_effect if ml_validated_effect is not None else total_effect
        except Exception:
            return 0.0

    def _calculate_enso_index(self, current_time: datetime, lat: float) -> Dict:
        """Calculate comprehensive ENSO index with multiple indicators"""
        try:
            year = current_time.year
            month = current_time.month
            
            # Multi-phase ENSO calculation based on realistic cycles
            base_period = 3.5  # Average ENSO cycle length
            irregular_component = 0.5 * math.sin(2 * math.pi * year / 7.2)  # Irregular 7-year modulation
            cycle_length = base_period + irregular_component
            
            # Phase calculation with stochastic component
            phase = 2 * math.pi * (year + month/12) / cycle_length
            phase_shift = 0.3 * math.sin(2 * math.pi * year / 11.2)  # Solar cycle influence
            adjusted_phase = phase + phase_shift
            
            # Multi-indicator ENSO index
            sst_anomaly = 0.8 * math.sin(adjusted_phase)  # SST-based component
            trade_wind_component = -0.6 * math.cos(adjusted_phase + math.pi/4)  # Trade wind component
            thermocline_component = 0.4 * math.sin(adjusted_phase + math.pi/2)  # Thermocline depth
            
            # Regional amplitude modulation
            tropical_factor = max(0.1, 1.0 - abs(lat) / 30.0)  # Strongest in tropics
            longitude_factor = 1.0  # Would need longitude for Pacific weighting
            
            enso_strength = (sst_anomaly + trade_wind_component + thermocline_component) * tropical_factor
            
            # Phase classification
            if enso_strength > 0.5:
                phase_name = "El Niño"
            elif enso_strength < -0.5:
                phase_name = "La Niña"
            else:
                phase_name = "Neutral"
            
            return {
                'index': enso_strength,
                'phase': phase_name,
                'sst_component': sst_anomaly * tropical_factor,
                'wind_component': trade_wind_component * tropical_factor,
                'thermocline_component': thermocline_component * tropical_factor,
                'regional_factor': tropical_factor,
                'confidence': min(1.0, abs(enso_strength) + 0.3)
            }
        except Exception:
            return {'index': 0.0, 'phase': 'Unknown', 'confidence': 0.0}

    def _calculate_pdo_index(self, current_time: datetime, lat: float) -> Dict:
        """Calculate Pacific Decadal Oscillation index"""
        try:
            year = current_time.year
            
            # PDO has 20-30 year cycles with irregular switching
            base_cycle = 25.0
            modulation = 5.0 * math.cos(2 * math.pi * year / 60.0)  # Long-term modulation
            effective_cycle = base_cycle + modulation
            
            # Multi-component PDO calculation
            phase = 2 * math.pi * year / effective_cycle
            sst_pattern = 0.7 * math.cos(phase)
            atmospheric_pattern = 0.5 * math.sin(phase + math.pi/6)
            
            # Regional effects - stronger in North Pacific
            north_pacific_factor = max(0.0, (lat - 30.0) / 30.0) if lat > 30 else 0.2
            
            pdo_strength = (sst_pattern + atmospheric_pattern) * north_pacific_factor
            
            # Phase determination
            phase_name = "Positive" if pdo_strength > 0 else "Negative"
            
            return {
                'index': pdo_strength,
                'phase': phase_name,
                'sst_component': sst_pattern * north_pacific_factor,
                'atmospheric_component': atmospheric_pattern * north_pacific_factor,
                'regional_factor': north_pacific_factor,
                'confidence': min(1.0, abs(pdo_strength) + 0.2)
            }
        except Exception:
            return {'index': 0.0, 'phase': 'Unknown', 'confidence': 0.0}

    def _calculate_nao_index(self, current_time: datetime, lat: float) -> Dict:
        """Calculate North Atlantic Oscillation index"""
        try:
            year = current_time.year
            month = current_time.month
            
            # NAO shows strong seasonal variation and irregular multi-year patterns
            seasonal_phase = 2 * math.pi * month / 12
            seasonal_amplitude = 0.6 * math.cos(seasonal_phase - math.pi/6)  # Stronger in winter
            
            # Multi-year variability
            interannual_component = 0.8 * math.sin(2 * math.pi * year / 2.3)  # ~2.3 year cycle
            decadal_component = 0.4 * math.cos(2 * math.pi * year / 8.5)  # ~8.5 year cycle
            
            # Atlantic sector influence
            atlantic_factor = max(0.0, 1.0 - abs(lat - 60.0) / 40.0) if 20 <= lat <= 80 else 0.1
            
            nao_strength = (seasonal_amplitude + interannual_component + decadal_component) * atlantic_factor
            
            phase_name = "Positive" if nao_strength > 0 else "Negative"
            
            return {
                'index': nao_strength,
                'phase': phase_name,
                'seasonal_component': seasonal_amplitude * atlantic_factor,
                'interannual_component': interannual_component * atlantic_factor,
                'decadal_component': decadal_component * atlantic_factor,
                'regional_factor': atlantic_factor,
                'confidence': min(1.0, abs(nao_strength) + 0.3)
            }
        except Exception:
            return {'index': 0.0, 'phase': 'Unknown', 'confidence': 0.0}

    def _calculate_amo_index(self, current_time: datetime, lat: float) -> Dict:
        """Calculate Atlantic Multidecadal Oscillation index"""
        try:
            year = current_time.year
            
            # AMO has ~60-80 year cycles
            long_cycle = 70.0
            irregular_modulation = 10.0 * math.sin(2 * math.pi * year / 45.0)
            effective_cycle = long_cycle + irregular_modulation
            
            # AMO components
            phase = 2 * math.pi * year / effective_cycle
            sst_component = 0.6 * math.sin(phase)
            circulation_component = 0.4 * math.cos(phase + math.pi/4)
            
            # Atlantic basin influence
            atlantic_influence = max(0.0, 1.0 - abs(lat - 45.0) / 50.0) if lat > -10 else 0.1
            
            amo_strength = (sst_component + circulation_component) * atlantic_influence
            
            phase_name = "Positive" if amo_strength > 0 else "Negative"
            
            return {
                'index': amo_strength,
                'phase': phase_name,
                'sst_component': sst_component * atlantic_influence,
                'circulation_component': circulation_component * atlantic_influence,
                'regional_factor': atlantic_influence,
                'confidence': min(1.0, abs(amo_strength) + 0.2)
            }
        except Exception:
            return {'index': 0.0, 'phase': 'Unknown', 'confidence': 0.0}

    def _calculate_ao_index(self, current_time: datetime, lat: float) -> Dict:
        """Calculate Arctic Oscillation index"""
        try:
            year = current_time.year
            month = current_time.month
            
            # AO shows strong seasonal cycle and irregular variability
            seasonal_phase = 2 * math.pi * month / 12
            seasonal_strength = 0.8 * math.cos(seasonal_phase)  # Stronger in winter
            
            # Irregular multi-year patterns
            irregular_component = 0.6 * math.sin(2 * math.pi * year / 1.8)  # ~1.8 year cycle
            trend_component = 0.2 * math.cos(2 * math.pi * year / 12.0)  # Decadal trend
            
            # Arctic/high-latitude influence
            arctic_factor = max(0.0, (lat - 45.0) / 45.0) if lat > 45 else 0.1
            
            ao_strength = (seasonal_strength + irregular_component + trend_component) * arctic_factor
            
            phase_name = "Positive" if ao_strength > 0 else "Negative"
            
            return {
                'index': ao_strength,
                'phase': phase_name,
                'seasonal_component': seasonal_strength * arctic_factor,
                'irregular_component': irregular_component * arctic_factor,
                'trend_component': trend_component * arctic_factor,
                'regional_factor': arctic_factor,
                'confidence': min(1.0, abs(ao_strength) + 0.3)
            }
        except Exception:
            return {'index': 0.0, 'phase': 'Unknown', 'confidence': 0.0}

    def _calculate_iod_index(self, current_time: datetime, lat: float) -> Dict:
        """Calculate Indian Ocean Dipole index"""
        try:
            year = current_time.year
            month = current_time.month
            
            # IOD shows strong seasonal phase-locking and irregular events
            seasonal_phase = 2 * math.pi * month / 12
            seasonal_modulation = 0.7 * math.cos(seasonal_phase - 2 * math.pi * 9/12)  # Peak in Sep-Nov
            
            # Irregular IOD events (~3-5 years)
            irregular_cycle = 4.2
            event_phase = 2 * math.pi * year / irregular_cycle
            event_strength = 0.9 * math.sin(event_phase)
            
            # ENSO interaction (simplified)
            enso_interaction = 0.3 * math.sin(2 * math.pi * year / 3.8 + math.pi/3)
            
            # Indian Ocean regional influence
            indian_ocean_factor = max(0.0, 1.0 - abs(lat) / 40.0) if -40 <= lat <= 40 else 0.05
            
            iod_strength = (seasonal_modulation * event_strength + enso_interaction) * indian_ocean_factor
            
            phase_name = "Positive" if iod_strength > 0 else "Negative"
            
            return {
                'index': iod_strength,
                'phase': phase_name,
                'seasonal_component': seasonal_modulation * indian_ocean_factor,
                'event_component': event_strength * indian_ocean_factor,
                'enso_interaction': enso_interaction * indian_ocean_factor,
                'regional_factor': indian_ocean_factor,
                'confidence': min(1.0, abs(iod_strength) + 0.25)
            }
        except Exception:
            return {'index': 0.0, 'phase': 'Unknown', 'confidence': 0.0}

    def _calculate_mjo_index(self, current_time: datetime, lat: float) -> Dict:
        """Calculate Madden-Julian Oscillation index"""
        try:
            # MJO has 30-90 day cycles (use day of year for sub-annual variation)
            day_of_year = current_time.timetuple().tm_yday
            year = current_time.year
            
            # Primary MJO cycle (30-90 days)
            mjo_cycle = 45 + 15 * math.sin(2 * math.pi * year / 3.2)  # Variable cycle length
            mjo_phase = 2 * math.pi * day_of_year / mjo_cycle
            
            # MJO amplitude (varies seasonally and interannually)
            seasonal_modulation = 0.5 + 0.5 * math.cos(2 * math.pi * day_of_year / 365 - math.pi/2)  # Stronger in boreal winter
            interannual_modulation = 0.7 + 0.3 * math.cos(2 * math.pi * year / 2.5)
            
            mjo_amplitude = seasonal_modulation * interannual_modulation
            
            # MJO has 8 phases - simplified to continuous index
            mjo_strength = mjo_amplitude * math.sin(mjo_phase)
            
            # Tropical influence (MJO is strongest in tropics)
            tropical_factor = max(0.1, 1.0 - abs(lat) / 25.0)
            
            final_mjo = mjo_strength * tropical_factor
            
            # Phase determination (simplified)
            phase_number = int((mjo_phase % (2 * math.pi)) / (2 * math.pi / 8)) + 1
            
            return {
                'index': final_mjo,
                'phase_number': phase_number,
                'amplitude': mjo_amplitude * tropical_factor,
                'seasonal_modulation': seasonal_modulation,
                'interannual_modulation': interannual_modulation,
                'regional_factor': tropical_factor,
                'confidence': min(1.0, abs(final_mjo) + 0.4)
            }
        except Exception:
            return {'index': 0.0, 'phase_number': 1, 'confidence': 0.0}

    def _calculate_teleconnection_patterns(self, oscillation_effects: Dict, lat: float) -> Dict:
        """Calculate teleconnection patterns between climate oscillations"""
        try:
            teleconnections = {}
            
            # ENSO-PDO interaction
            if 'enso' in oscillation_effects and 'pdo' in oscillation_effects:
                enso_pdo_correlation = 0.3  # Moderate positive correlation
                interaction = (oscillation_effects['enso']['index'] * 
                             oscillation_effects['pdo']['index'] * enso_pdo_correlation)
                teleconnections['enso_pdo'] = interaction
            
            # NAO-AO interaction (strong positive correlation)
            if 'nao' in oscillation_effects and 'ao' in oscillation_effects:
                nao_ao_correlation = 0.7
                interaction = (oscillation_effects['nao']['index'] * 
                             oscillation_effects['ao']['index'] * nao_ao_correlation)
                teleconnections['nao_ao'] = interaction
            
            # ENSO-IOD interaction
            if 'enso' in oscillation_effects and 'iod' in oscillation_effects:
                enso_iod_correlation = 0.4
                interaction = (oscillation_effects['enso']['index'] * 
                             oscillation_effects['iod']['index'] * enso_iod_correlation)
                teleconnections['enso_iod'] = interaction
            
            # ENSO-MJO modulation
            if 'enso' in oscillation_effects and 'mjo' in oscillation_effects:
                # ENSO modulates MJO amplitude
                mjo_modulation = oscillation_effects['enso']['index'] * 0.2
                teleconnections['enso_mjo_modulation'] = (oscillation_effects['mjo']['index'] * 
                                                        (1.0 + mjo_modulation))
            
            # AMO-NAO interaction (negative correlation)
            if 'amo' in oscillation_effects and 'nao' in oscillation_effects:
                amo_nao_correlation = -0.3
                interaction = (oscillation_effects['amo']['index'] * 
                             oscillation_effects['nao']['index'] * amo_nao_correlation)
                teleconnections['amo_nao'] = interaction
            
            return teleconnections
        except Exception:
            return {}

    def _combine_oscillation_effects(self, oscillation_effects: Dict, 
                                   teleconnection_effects: Dict, lat: float) -> float:
        """Combine all oscillation effects with appropriate weighting"""
        try:
            total_effect = 0.0
            
            # Base oscillation weights (regionally dependent)
            weights = {
                'enso': 0.3 * max(0.2, 1.0 - abs(lat) / 30.0),  # Stronger in tropics
                'pdo': 0.2 * max(0.1, (lat - 30.0) / 30.0) if lat > 30 else 0.05,  # N. Pacific
                'nao': 0.25 * max(0.1, 1.0 - abs(lat - 60.0) / 40.0) if 20 <= lat <= 80 else 0.05,  # N. Atlantic
                'amo': 0.15 * max(0.1, 1.0 - abs(lat - 45.0) / 50.0) if lat > -10 else 0.05,  # Atlantic
                'ao': 0.2 * max(0.1, (lat - 45.0) / 45.0) if lat > 45 else 0.05,  # Arctic
                'iod': 0.15 * max(0.1, 1.0 - abs(lat) / 40.0) if -40 <= lat <= 40 else 0.03,  # Indian Ocean
                'mjo': 0.1 * max(0.1, 1.0 - abs(lat) / 25.0),  # Tropical
            }
            
            # Sum weighted oscillation effects
            for osc_name, osc_data in oscillation_effects.items():
                if osc_name in weights and isinstance(osc_data, dict):
                    confidence = osc_data.get('confidence', 1.0)
                    weighted_effect = osc_data.get('index', 0.0) * weights[osc_name] * confidence
                    total_effect += weighted_effect
            
            # Add teleconnection effects with smaller weights
            teleconnection_weight = 0.15
            for tc_name, tc_effect in teleconnection_effects.items():
                total_effect += tc_effect * teleconnection_weight
            
            # Apply non-linear scaling to prevent extreme values
            if abs(total_effect) > 1.0:
                total_effect = math.copysign(1.0 - math.exp(-abs(total_effect)), total_effect)
            
            return total_effect
        except Exception:
            return 0.0

    def _validate_oscillation_with_ml(self, calculated_effect: float, oscillation_data: Dict,
                                    current_time: datetime, lat: float) -> Optional[float]:
        """ML-enhanced validation and correction of oscillation effects"""
        try:
            if hasattr(self, 'model_manager') and self.model_manager:
                # Prepare features for ML validation
                features = {
                    'calculated_effect': calculated_effect,
                    'month': current_time.month,
                    'latitude': lat,
                    'year_fraction': (current_time.timetuple().tm_yday - 1) / 365.0,
                }
                
                # Add oscillation indices as features
                for osc_name, osc_data in oscillation_data.items():
                    if isinstance(osc_data, dict):
                        features[f'{osc_name}_index'] = osc_data.get('index', 0.0)
                        features[f'{osc_name}_confidence'] = osc_data.get('confidence', 0.0)
                
                # Query ML model for validation/correction
                ml_prediction = self.model_manager.predict_climate_oscillation_effect(features)
                
                if ml_prediction is not None and isinstance(ml_prediction, (int, float)):
                    # Blend ML prediction with calculated effect
                    ml_confidence = features.get('overall_confidence', 0.7)
                    blended_effect = (ml_confidence * ml_prediction + 
                                    (1.0 - ml_confidence) * calculated_effect)
                    return blended_effect
            
            return None
        except Exception:
            return None

    def _calculate_atm_thermal_coupling(self, atmospheric_data: Dict, thermal_data: Dict) -> float:
        """Calculate atmospheric-thermal coupling effects"""
        try:
            # Pressure-temperature coupling
            pressure_anomaly = atmospheric_data.get('pressure_anomaly', 0.0)
            temp_anomaly = thermal_data.get('temperature_anomaly', 0.0)
            pressure_temp_coupling = pressure_anomaly * temp_anomaly * 0.001
            
            # Humidity-thermal coupling
            humidity = atmospheric_data.get('humidity_factor', 1.0)
            thermal_stress = thermal_data.get('thermal_stress_factor', 0.5)
            humidity_thermal_coupling = (humidity - 1.0) * thermal_stress * 0.05
            
            return pressure_temp_coupling + humidity_thermal_coupling
        except Exception:
            return 0.0

    def _calculate_hydro_thermal_coupling(self, hydro_data: Dict, thermal_data: Dict) -> float:
        """Calculate hydrological-thermal coupling effects"""
        try:
            # Surface loading thermal effects
            loading_factor = hydro_data.get('loading_factor', 1.0)
            thermal_expansion = thermal_data.get('thermal_expansion_factor', 0.0)
            loading_thermal_coupling = (loading_factor - 1.0) * thermal_expansion * 0.1
            
            # Groundwater thermal coupling
            groundwater_pressure = hydro_data.get('groundwater_pressure_factor', 1.0)
            soil_temp = thermal_data.get('soil_temperature', 15.0)
            gw_thermal_coupling = (groundwater_pressure - 1.0) * abs(soil_temp - 15.0) * 0.001
            
            return loading_thermal_coupling + gw_thermal_coupling
        except Exception:
            return 0.0

    def _calculate_atm_hydro_coupling(self, atmospheric_data: Dict, hydro_data: Dict) -> float:
        """Calculate atmospheric-hydrological coupling effects"""
        try:
            # Precipitation-pressure coupling
            precipitation_stress = hydro_data.get('precipitation_stress', 0.0)
            pressure_anomaly = atmospheric_data.get('pressure_anomaly', 0.0)
            precip_pressure_coupling = precipitation_stress * pressure_anomaly * 0.02
            
            # Wind-evaporation coupling
            wind_stress = atmospheric_data.get('wind_stress_factor', 0.0)
            soil_moisture_stress = hydro_data.get('soil_moisture_stress', 0.0)
            wind_evap_coupling = wind_stress * soil_moisture_stress * 0.03
            
            return precip_pressure_coupling + wind_evap_coupling
        except Exception:
            return 0.0

    def _ml_seasonal_factor_prediction(self, atmospheric_data: Dict, hydro_data: Dict,
                                     thermal_data: Dict, day_of_year: int) -> Optional[float]:
        """ML-enhanced seasonal factor prediction"""
        try:
            if hasattr(self, 'model_manager') and self.model_manager:
                features = {
                    'day_of_year': day_of_year,
                    'pressure_anomaly': atmospheric_data.get('pressure_anomaly', 0.0),
                    'temperature_anomaly': atmospheric_data.get('temperature_anomaly', 0.0),
                    'humidity_factor': atmospheric_data.get('humidity_factor', 1.0),
                    'loading_factor': hydro_data.get('loading_factor', 1.0),
                    'thermal_expansion_factor': thermal_data.get('thermal_expansion_factor', 0.0),
                    'thermal_stress_factor': thermal_data.get('thermal_stress_factor', 0.5)
                }
                
                prediction = self.model_manager.predict('seasonal_factor_model', features)
                if prediction and 'seasonal_factor' in prediction:
                    return prediction['seasonal_factor']
            return None
        except Exception:
            return None

    def _calculate_seasonal_factor_uncertainty(self, atmospheric_data: Dict, 
                                             hydro_data: Dict, thermal_data: Dict) -> float:
        """Calculate uncertainty in seasonal factor estimation"""
        try:
            import numpy as np
            
            # Data quality indicators
            data_qualities = []
            
            # Atmospheric data quality
            atm_quality = atmospheric_data.get('data_quality', 0.8)
            data_qualities.append(atm_quality)
            
            # Hydrological data quality
            hydro_quality = hydro_data.get('data_quality', 0.8)
            data_qualities.append(hydro_quality)
            
            # Thermal data quality
            thermal_quality = thermal_data.get('data_quality', 0.8)
            data_qualities.append(thermal_quality)
            
            # Overall data quality
            overall_quality = np.mean(data_qualities)
            
            # Uncertainty scales inversely with data quality
            base_uncertainty = 0.1
            quality_factor = 1.0 - overall_quality
            uncertainty = base_uncertainty * (1.0 + quality_factor)
            
            return min(uncertainty, 0.5)  # Cap uncertainty at 50%
        except Exception:
            return 0.2  # Default uncertainty

    def _robust_seasonal_factor_correction(self, raw_factor: float, atmospheric_data: Dict,
                                         hydro_data: Dict, thermal_data: Dict) -> float:
        """Robust correction for outlier seasonal factors"""
        try:
            import numpy as np
            
            # Historical seasonal factor statistics (would come from database)
            historical_mean = 1.0
            historical_std = 0.3
            
            # Z-score based outlier detection
            z_score = abs(raw_factor - historical_mean) / historical_std
            
            if z_score > 2.5:  # Outlier detected
                # Apply robust M-estimator correction
                sign = 1 if raw_factor > historical_mean else -1
                corrected_factor = historical_mean + sign * min(
                    abs(raw_factor - historical_mean),
                    2 * historical_std
                )
                return corrected_factor
            
            return raw_factor
        except Exception:
            return max(0.5, min(2.0, raw_factor))

