    def _get_elevation(self, lat: float, lon: float) -> Optional[float]:
        """Get elevation data for location"""
        try:
            if hasattr(self, 'database') and self.database:
                query = """
                SELECT elevation_m 
                FROM topography 
                WHERE ST_DWithin(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1000)
                ORDER BY ST_Distance(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326))
                LIMIT 1
                """
                result = self.database.execute_query(query, (lon, lat, lon, lat))
                if result and result[0]:
                    return float(result[0]['elevation_m'])
            return None
        except Exception:
            return None

    def _get_slope_aspect(self, lat: float, lon: float) -> Optional[Dict]:
        """Get slope and aspect data for location"""
        try:
            if hasattr(self, 'database') and self.database:
                query = """
                SELECT slope_degrees, aspect_degrees, shadow_factor
                FROM topography 
                WHERE ST_DWithin(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1000)
                ORDER BY ST_Distance(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326))
                LIMIT 1
                """
                result = self.database.execute_query(query, (lon, lat, lon, lat))
                if result and result[0]:
                    return {
                        'slope_degrees': float(result[0]['slope_degrees'] or 0.0),
                        'aspect_degrees': float(result[0]['aspect_degrees'] or 180.0),
                        'shadow_factor': float(result[0]['shadow_factor'] or 1.0)
                    }
            return None
        except Exception:
            return None
    
    def _fallback_seasonal_analysis(self, current_time: datetime, day_of_year: int) -> Dict:
        """Enhanced fallback seasonal analysis when real data unavailable"""
        import math
        
        month = current_time.month
        seasonal_factor = 1.0 + 0.1 * math.cos(2 * math.pi * (day_of_year - 80) / 365.25)
        
        # Enhanced seasonal hydro model
        seasonal_hydro = {
            1: 0.8, 2: 0.9, 3: 1.2, 4: 1.3, 5: 1.1, 6: 0.9,
            7: 0.7, 8: 0.6, 9: 0.7, 10: 0.9, 11: 1.0, 12: 0.8
        }
        
        return {
            'seasonal_factor': seasonal_factor,
            'hydrological_loading': {'loading_factor': seasonal_hydro.get(month, 1.0)},
            'atmospheric_pressure_effect': self._fallback_atmospheric_model(current_time),
            'thermal_stress_factor': {'thermal_stress_factor': self._calculate_thermal_stress(day_of_year)},
            'analysis_quality': 'enhanced_model'
        }
    
    def _fallback_atmospheric_model(self, current_time: datetime) -> Dict:
        """Enhanced atmospheric model when real data unavailable"""
        import math
        
        day_of_year = current_time.timetuple().tm_yday
        hour = current_time.hour
        
        # Enhanced atmospheric pressure model
        diurnal_pressure = math.sin(2 * math.pi * hour / 24)
        seasonal_pressure = math.cos(2 * math.pi * (day_of_year - 15) / 365.25)
        pressure_anomaly = 0.1 * diurnal_pressure + 0.2 * seasonal_pressure
        
        return {
            'pressure_anomaly': pressure_anomaly,
            'diurnal_component': diurnal_pressure,
            'seasonal_component': seasonal_pressure,
            'seismic_influence': abs(pressure_anomaly) * 0.02,
            'source': 'enhanced_model'
        }
    
    def _calculate_thermal_stress(self, day_of_year: int) -> float:
        """Calculate thermal stress contribution"""
        import math
        # Thermal expansion/contraction effects
        return 0.5 * (1 + math.sin(2 * math.pi * (day_of_year - 172) / 365.25))
    
    def _analyze_historical_temporal_context(self, current_time: datetime) -> Dict:
        """Analyze historical temporal context and patterns"""
        from datetime import timedelta
        
        context = {
            'time_since_midnight': (current_time - current_time.replace(hour=0, minute=0, second=0, microsecond=0)).total_seconds(),
            'time_until_midnight': 86400 - (current_time - current_time.replace(hour=0, minute=0, second=0, microsecond=0)).total_seconds(),
            'circadian_phase': self._calculate_circadian_phase(current_time.hour),
            'weekly_pattern': self._get_weekly_seismic_pattern(current_time.weekday())
        }
        
        # Add temporal clustering analysis
        context['temporal_clustering'] = self._analyze_temporal_clustering(current_time)
        
        return context
    
    def _calculate_circadian_phase(self, hour: int) -> Dict:
        """Calculate circadian rhythm phase relevant to seismic activity"""
        import math
        
        # 24-hour circadian cycle
        phase_radians = 2 * math.pi * hour / 24
        
        return {
            'phase_radians': phase_radians,
            'phase_normalized': hour / 24.0,
            'circadian_amplitude': math.sin(phase_radians),
            'activity_level': 'high' if 6 <= hour <= 18 else 'low'
        }
    
    def _get_weekly_seismic_pattern(self, weekday: int) -> Dict:
        """Get weekly seismic activity patterns"""
        # Some studies suggest slight weekly variations in seismic activity
        weekly_factors = [1.02, 1.01, 0.99, 1.00, 0.98, 1.01, 1.03]  # Mon-Sun
        
        return {
            'weekday_factor': weekly_factors[weekday],
            'is_weekend': weekday >= 5,
            'anthropogenic_noise': 'high' if weekday < 5 else 'low'
        }
    
