    def _get_regional_earthquake_data(self, latitude: float, longitude: float) -> Dict:
        """Get regional earthquake data using external connectors"""
        try:
            # Try to use USGS connector if available
            if hasattr(self, 'external_connectors'):
                usgs_connector = self.external_connectors.get('usgs')
                if usgs_connector:
                    from datetime import datetime, timedelta
                    
                    end_time = datetime.now()
                    start_time = end_time - timedelta(days=30)
                    
                    # Define search area (200km radius)
                    lat_range = 1.8  # ~200km
                    lon_range = 1.8 / abs(math.cos(math.radians(latitude)))
                    
                    earthquake_data = usgs_connector.get_earthquake_data(
                        start_time=start_time,
                        end_time=end_time,
                        min_latitude=latitude - lat_range,
                        max_latitude=latitude + lat_range,
                        min_longitude=longitude - lon_range,
                        max_longitude=longitude + lon_range,
                        min_magnitude=1.0,
                        limit=1000
                    )
                    
                    return {
                        'recent_events': earthquake_data,
                        'data_source': 'USGS',
                        'query_params': {
                            'center': [latitude, longitude],
                            'radius_km': 200,
                            'time_window_days': 30,
                            'min_magnitude': 1.0
                        }
                    }
            
            # Fallback to simulated data if no connector available
            return self._generate_simulated_earthquake_data(latitude, longitude)
            
        except Exception as e:
            import warnings
            warnings.warn(f"Failed to fetch earthquake data: {e}")
            return self._generate_simulated_earthquake_data(latitude, longitude)
    
    def _generate_simulated_earthquake_data(self, latitude: float, longitude: float) -> Dict:
        """Generate realistic simulated earthquake data for analysis"""
        import random
        from datetime import datetime, timedelta
        
        # Generate realistic earthquake distribution
        events = []
        current_time = datetime.now()
        
        # Generate events following Gutenberg-Richter law
        for i in range(random.randint(10, 50)):
            event_time = current_time - timedelta(days=random.uniform(0, 30))
            
            # Magnitude following exponential distribution (b-value ~ 1.0)
            magnitude = random.expovariate(1.0) + 1.0
            magnitude = min(magnitude, 7.0)  # Cap at M7.0
            
            # Location within 200km radius
            angle = random.uniform(0, 2 * math.pi)
            distance = random.uniform(0, 200)  # km
            
            lat_offset = (distance / 111.0) * math.cos(angle)  # 111 km per degree
            lon_offset = (distance / (111.0 * math.cos(math.radians(latitude)))) * math.sin(angle)
            
            events.append({
                'magnitude': magnitude,
                'latitude': latitude + lat_offset,
                'longitude': longitude + lon_offset,
                'depth': random.uniform(1, 30),  # km
                'time': event_time.isoformat(),
                'location': f'Simulated event {i+1}'
            })
        
        return {
            'recent_events': events,
            'data_source': 'Simulated',
            'query_params': {
                'center': [latitude, longitude],
                'radius_km': 200,
                'time_window_days': 30
            }
        }

    def _infer_geological_setting(self, location: Dict) -> Dict:
        """Advanced geological setting inference using data integration pipeline"""
        try:
            latitude = location.get('latitude', 0.0)
            longitude = location.get('longitude', 0.0)
            distance_km = location.get('distance_km', 100.0)
            depth_km = location.get('depth_km', 10.0)
            
            # Initialize data integration pipeline if available
            geological_context = self._get_geological_context_from_pipeline(latitude, longitude)
            
            # Multi-scale geological analysis
            scale_analysis = {
                'local_scale': self._analyze_local_geological_setting(latitude, longitude, distance_km),
                'regional_scale': self._analyze_regional_geological_setting(latitude, longitude),
                'crustal_scale': self._analyze_crustal_structure(latitude, longitude, depth_km),
                'tectonic_scale': self._analyze_tectonic_setting(latitude, longitude)
            }
            
            # Integrate multiple data sources
            integrated_setting = {
                'primary_setting': self._determine_primary_geological_setting(scale_analysis, distance_km),
                'scale_analysis': scale_analysis,
                'geological_context': geological_context,
                'lithology': self._infer_lithology(latitude, longitude, depth_km),
                'structural_features': self._identify_structural_features(latitude, longitude),
                'geophysical_properties': self._estimate_geophysical_properties(geological_context),
                'hazard_indicators': self._assess_geological_hazards(scale_analysis, geological_context)
            }
            
            return integrated_setting
            
        except Exception as e:
            import warnings
            warnings.warn(f"Advanced geological setting inference failed: {e}")
            
            # Fallback to distance-based classification
            distance_km = location.get('distance_km', 100.0)
            if distance_km < 50:
                setting = 'local_geological_setting'
            elif distance_km < 200:
                setting = 'regional_geological_setting'
            else:
                setting = 'teleseismic_geological_setting'
            
            return {
                'primary_setting': setting,
                'analysis_quality': 'fallback',
                'error': str(e)
            }
    
