    def _extract_contextual_features(self, geological_context: Dict) -> Dict:
        """Extract quantitative features from geological context for ML refinement"""
        try:
            features = {}
            
            # Primary geological setting features
            primary_setting = geological_context.get('primary_setting', 'unknown')
            features['setting_encoded'] = hash(primary_setting) % 1000 / 1000.0  # Normalized hash
            
            # Scale analysis features
            scale_analysis = geological_context.get('scale_analysis', {})
            
            # Local scale features
            local_scale = scale_analysis.get('local_scale', {})
            features['geological_heterogeneity'] = local_scale.get('geological_heterogeneity', 0.5)
            features['detail_level_score'] = {'very_high': 1.0, 'high': 0.8, 'moderate': 0.6, 'low': 0.4}.get(
                local_scale.get('detail_level', 'moderate'), 0.6
            )
            
            # Crustal features
            crustal_scale = scale_analysis.get('crustal_scale', {})
            features['crustal_thickness'] = crustal_scale.get('crustal_thickness_km', 35.0) / 50.0  # Normalized
            features['crustal_type_score'] = 1.0 if crustal_scale.get('crustal_type') == 'continental' else 0.0
            
            # Tectonic features
            tectonic_scale = scale_analysis.get('tectonic_scale', {})
            plate_setting = tectonic_scale.get('plate_setting', 'intraplate')
            features['plate_setting_score'] = {
                'plate_boundary': 1.0,
                'subduction_zone': 0.9,
                'rift_zone': 0.7,
                'intraplate': 0.3
            }.get(plate_setting, 0.3)
            
            # Lithology features
            lithology = geological_context.get('lithology', {})
            dominant_lithology = lithology.get('dominant_lithology', 'sedimentary')
            features['lithology_score'] = {
                'igneous': 1.0,
                'metamorphic': 0.8,
                'sedimentary': 0.4
            }.get(dominant_lithology, 0.4)
            
            features['porosity'] = lithology.get('porosity', 0.1)
            features['rock_strength'] = min(1.0, lithology.get('strength', 100.0) / 300.0)  # Normalized
            
            # Geophysical properties
            geophys_props = geological_context.get('geophysical_properties', {})
            features['p_wave_velocity'] = geophys_props.get('p_wave_velocity', 6.0) / 8.0  # Normalized
            features['density'] = (geophys_props.get('density', 2.7) - 2.0) / 1.5  # Normalized
            
            return features
            
        except Exception as e:
            # Return default features if extraction fails
            return {
                'setting_encoded': 0.5,
                'geological_heterogeneity': 0.5,
                'detail_level_score': 0.6,
                'crustal_thickness': 0.7,
                'crustal_type_score': 1.0,
                'plate_setting_score': 0.3,
                'lithology_score': 0.4,
                'porosity': 0.1,
                'rock_strength': 0.3,
                'p_wave_velocity': 0.75,
                'density': 0.47
            }
    
    def _apply_geological_prior_refinement(self, classification: str, geological_context: Dict) -> Dict:
        """Apply geological prior knowledge for classification refinement"""
        # Prior probabilities based on geological setting
        geological_priors = {
            'earthquake': {
                'continental_intraplate': 0.4,
                'oceanic_intraplate': 0.3,
                'plate_boundary': 0.8,
                'subduction_zone': 0.9,
                'continental_rift': 0.7
            },
            'explosion': {
                'continental_intraplate': 0.1,
                'oceanic_intraplate': 0.05,
                'plate_boundary': 0.02,
                'subduction_zone': 0.01,
                'continental_rift': 0.05
            },
            'volcanic': {
                'continental_intraplate': 0.1,
                'oceanic_intraplate': 0.2,
                'plate_boundary': 0.3,
                'subduction_zone': 0.6,
                'continental_rift': 0.8
            }
        }
        
        primary_setting = geological_context.get('primary_setting', 'continental_intraplate')
        setting_key = primary_setting.split('_')[-2:]
        setting_key = '_'.join(setting_key) if len(setting_key) >= 2 else 'continental_intraplate'
        
        prior_scores = {}
        for event_type, settings in geological_priors.items():
            prior_scores[event_type] = settings.get(setting_key, 0.1)
        
        # Calculate refinement based on priors
        current_prior = prior_scores.get(classification, 0.1)
        max_prior_type = max(prior_scores.keys(), key=lambda x: prior_scores[x])
        max_prior_score = prior_scores[max_prior_type]
        
        refinement_strength = abs(max_prior_score - current_prior)
        
        return {
            'method': 'geological_prior',
            'prior_scores': prior_scores,
            'current_classification_prior': current_prior,
            'suggested_classification': max_prior_type if refinement_strength > 0.3 else classification,
            'refinement_strength': refinement_strength,
            'confidence_modifier': refinement_strength
        }
    
    def _apply_tectonic_context_refinement(self, classification: str, geological_context: Dict) -> Dict:
        """Apply tectonic context for classification refinement"""
        scale_analysis = geological_context.get('scale_analysis', {})
        tectonic_scale = scale_analysis.get('tectonic_scale', {})
        
        # Tectonic setting implications
        tectonic_implications = {
            'plate_boundary': {'earthquake': 0.9, 'volcanic': 0.4, 'explosion': 0.1},
            'subduction_zone': {'earthquake': 0.8, 'volcanic': 0.9, 'explosion': 0.05},
            'rift_zone': {'earthquake': 0.7, 'volcanic': 0.8, 'explosion': 0.1},
            'intraplate': {'earthquake': 0.5, 'volcanic': 0.1, 'explosion': 0.3}
        }
        
        plate_setting = tectonic_scale.get('plate_setting', 'intraplate')
        volcanic_activity = tectonic_scale.get('volcanic_activity', {})
        volcanic_level = volcanic_activity.get('activity_level', 'none')
        
        # Adjust probabilities based on volcanic activity
        volcanic_modifier = {
            'very_high': 0.3,
            'high': 0.2,
            'moderate': 0.1,
            'low': 0.05,
            'none': 0.0
        }.get(volcanic_level, 0.0)
        
        implications = tectonic_implications.get(plate_setting, tectonic_implications['intraplate'])
        
        # Apply volcanic modifier
        if 'volcanic' in implications:
            implications['volcanic'] += volcanic_modifier
            implications['earthquake'] -= volcanic_modifier * 0.5  # Trade-off
        
        suggested_type = max(implications.keys(), key=lambda x: implications[x])
        current_score = implications.get(classification, 0.1)
        max_score = implications[suggested_type]
        
        return {
            'method': 'tectonic_context',
            'plate_setting': plate_setting,
            'volcanic_activity_level': volcanic_level,
            'tectonic_implications': implications,
            'suggested_classification': suggested_type,
            'current_classification_score': current_score,
            'refinement_strength': abs(max_score - current_score),
            'confidence_modifier': min(0.3, abs(max_score - current_score))
        }
    
    def _apply_regional_statistics_refinement(self, classification: str, geological_context: Dict) -> Dict:
        """Apply regional seismic statistics for refinement"""
        # This would use actual regional seismicity statistics
