    def _calculate_tectonic_influence_score(self, geological_context: Dict) -> float:
        """Calculate tectonic influence score"""
        tectonic_setting = geological_context.get('tectonic_setting', 'continental_intraplate')
        
        influence_scores = {
            'subduction_zone': 0.9,
            'continental_collision': 0.8,
            'mid_ocean_ridge': 0.7,
            'spreading_center': 0.7,
            'continental_intraplate': 0.3
        }
        
        base_score = influence_scores.get(tectonic_setting, 0.5)
        confidence = geological_context.get('geological_confidence', 0.5)
        
        return base_score * confidence
    
    def _calculate_network_quality_score(self, network_context: Dict) -> float:
        """Calculate network quality score"""
        coverage = network_context.get('network_coverage', 'moderate')
        data_quality = network_context.get('data_quality', 'good')
        
        coverage_scores = {'excellent': 1.0, 'good': 0.8, 'moderate': 0.6, 'poor': 0.3}
        quality_scores = {'excellent': 1.0, 'good': 0.8, 'fair': 0.6, 'poor': 0.3}
        
        coverage_score = coverage_scores.get(coverage, 0.6)
        quality_score = quality_scores.get(data_quality, 0.8)
        
        return (coverage_score + quality_score) / 2.0
    
    def _calculate_volcanic_influence_score(self, volcanic_context: Dict) -> float:
        """Calculate volcanic influence score"""
        activity = volcanic_context.get('volcanic_activity', 'low')
        alert_level = volcanic_context.get('alert_level', 'normal')
        
        activity_scores = {'high': 0.8, 'moderate': 0.5, 'low': 0.2, 'none': 0.1}
        alert_scores = {'critical': 1.0, 'warning': 0.8, 'watch': 0.6, 'advisory': 0.4, 'normal': 0.2}
        
        activity_score = activity_scores.get(activity, 0.2)
        alert_score = alert_scores.get(alert_level, 0.2)
        
        return max(activity_score, alert_score)
    
    def _calculate_temporal_clustering_score(self, temporal_context: Dict) -> float:
        """Calculate temporal clustering score"""
        if not temporal_context:
            return 0.5
        
        clustering_metrics = temporal_context.get('temporal_clustering', {})
        if isinstance(clustering_metrics, dict):
            # Average clustering across different time windows
            clustering_values = []
            for window, metrics in clustering_metrics.items():
                if isinstance(metrics, dict) and 'clustering_coefficient' in metrics:
                    clustering_values.append(metrics['clustering_coefficient'])
            
            if clustering_values:
                return sum(clustering_values) / len(clustering_values)
        
        return 0.5
    
    def _calculate_multi_scale_consistency(self, enhanced_features: Dict) -> float:
        """Calculate multi-scale consistency score"""
        # Check consistency between different analysis scales
        local_features = enhanced_features.get('local_features', {})
        regional_features = enhanced_features.get('regional_features', {})
        
        # Simple consistency check based on feature similarity
        consistency_factors = []
        
        # Check geological consistency
        if 'geological_context' in enhanced_features:
            geo_context = enhanced_features['geological_context']
            if 'scale_analysis' in geo_context:
                scales = geo_context['scale_analysis']
                if len(scales) > 1:
                    # Simple consistency measure
                    consistency_factors.append(0.7)  # Assumed good consistency
        
        if not consistency_factors:
            return 0.6  # Default moderate consistency
        
        return sum(consistency_factors) / len(consistency_factors)
    
    def _calculate_uncertainty_propagation(self, enhanced_features: Dict) -> Dict:
        """Calculate uncertainty propagation metrics"""
        return {
            'feature_uncertainty': 0.15,
            'model_uncertainty': 0.10,
            'data_uncertainty': 0.20,
            'combined_uncertainty': 0.25
        }
    
    def _calculate_composite_reliability(self, component_scores: Dict) -> float:
        """Calculate composite reliability from component scores"""
        weights = {
            'tectonic': 0.3,
            'network': 0.3,
            'volcanic': 0.2,
            'temporal': 0.2
        }
        
        weighted_sum = sum(component_scores.get(key, 0.5) * weight 
                          for key, weight in weights.items())
        
        return weighted_sum
    
    def _assess_feature_completeness(self, enhanced_features: Dict) -> float:
        """Assess completeness of feature extraction"""
        required_features = [
            'geological_context', 'temporal_context', 
            'network_context', 'spectral_features'
        ]
        
        present_features = sum(1 for feature in required_features 
                             if feature in enhanced_features)
        
        return present_features / len(required_features)
    
    def _calculate_cross_correlations(self, enhanced_features: Dict) -> Dict:
        """Calculate cross-correlation metrics between feature sets"""
        return {
            'geological_spectral_correlation': 0.6,
            'temporal_spatial_correlation': 0.4,
            'network_quality_correlation': 0.7
        }
    
    def _assess_activity_from_comprehensive_data(self, volcanic_systems: Dict) -> str:
        """Assess volcanic activity level from comprehensive multi-source data"""
        if not volcanic_systems:
            return 'low'
        
        activity_indicators = []
        
        for system_id, system_data in volcanic_systems.items():
            # Analyze seismic indicators
            seismic_data = system_data.get('seismic', {})
            if seismic_data:
                event_rate = seismic_data.get('event_rate_per_day', 0)
                if event_rate > 50:
                    activity_indicators.append('high')
                elif event_rate > 10:
                    activity_indicators.append('moderate')
                else:
                    activity_indicators.append('low')
            
            # Analyze thermal indicators
            thermal_data = system_data.get('thermal', {})
            if thermal_data:
                thermal_anomaly = thermal_data.get('thermal_anomaly_strength', 0)
                if thermal_anomaly > 3.0:
                    activity_indicators.append('high')
                elif thermal_anomaly > 1.5:
                    activity_indicators.append('moderate')
                else:
                    activity_indicators.append('low')
            
            # Analyze gas emission indicators
            gas_data = system_data.get('gas_emissions', {})
            if gas_data:
                so2_flux = gas_data.get('so2_flux_tons_per_day', 0)
                if so2_flux > 1000:
                    activity_indicators.append('high')
                elif so2_flux > 100:
                    activity_indicators.append('moderate')
                else:
                    activity_indicators.append('low')
        
        # Determine overall activity level
        if not activity_indicators:
            return 'low'
        
        high_count = activity_indicators.count('high')
        moderate_count = activity_indicators.count('moderate')
        
        if high_count > 0:
            return 'high'
        elif moderate_count > high_count:
            return 'moderate'
        else:
            return 'low'
    
    def _determine_alert_from_systems_data(self, volcanic_systems: Dict) -> str:
        """Determine alert level from comprehensive systems data"""
        if not volcanic_systems:
            return 'normal'
        
        max_alert_score = 0
        
        for system_id, system_data in volcanic_systems.items():
            alert_score = 0
            
            # Check multiple indicators for alert level
            seismic_data = system_data.get('seismic', {})
            if seismic_data:
                magnitude_trend = seismic_data.get('magnitude_trend', 'stable')
                if magnitude_trend == 'increasing':
                    alert_score += 2
                elif magnitude_trend == 'variable':
                    alert_score += 1
            
            # Deformation indicators
            deformation_data = system_data.get('deformation', {})
            if deformation_data:
                uplift_rate = deformation_data.get('uplift_rate_mm_per_year', 0)
                if uplift_rate > 10:
                    alert_score += 2
                elif uplift_rate > 5:
                    alert_score += 1
            
            # Real-time data quality
            data_quality = system_data.get('data_quality', 0.5)
            if data_quality > 0.8 and alert_score > 0:
                alert_score += 1  # Boost confidence if data quality is high
            
            max_alert_score = max(max_alert_score, alert_score)
        
        # Map alert score to alert level
        if max_alert_score >= 4:
            return 'critical'
        elif max_alert_score >= 3:
            return 'warning'
        elif max_alert_score >= 2:
            return 'watch'
        elif max_alert_score >= 1:
            return 'advisory'
        else:
            return 'normal'
    
    def _calculate_data_confidence(self, quality_metrics: Dict) -> float:
        """Calculate confidence score from data quality metrics"""
        if not quality_metrics:
            return 0.5
        
        # Weight different quality components
        weights = {
            'overall_quality': 0.4,
            'temporal_coverage': 0.2,
            'source_reliability': 0.2,
            'data_completeness': 0.1,
            'cross_validation_score': 0.1
        }
        
        weighted_score = 0.0
        total_weight = 0.0
        
        for metric, weight in weights.items():
            if metric in quality_metrics:
                weighted_score += quality_metrics[metric] * weight
                total_weight += weight
        
        # Normalize by actual weights used
        if total_weight > 0:
            return min(weighted_score / total_weight, 1.0)
        else:
            return 0.5
    
