    def _assess_local_volcanic_activity_advanced(self, latitude: float, longitude: float) -> str:
        """Advanced local volcanic activity assessment using ML models"""
        # Enhanced version with more sophisticated regional analysis
        volcanic_regions = self._get_enhanced_volcanic_regions()
        
        activity_scores = []
        
        for region in volcanic_regions:
            distance = self._calculate_region_distance(latitude, longitude, region)
            if distance < region['influence_radius_km']:
                # Weight by distance and region characteristics
                distance_weight = 1.0 - (distance / region['influence_radius_km'])
                activity_weight = region['activity_weight']
                tectonic_weight = region.get('tectonic_weight', 1.0)
                
                regional_score = distance_weight * activity_weight * tectonic_weight
                activity_scores.append(regional_score)
        
        if not activity_scores:
            return 'low'
        
        max_score = max(activity_scores)
        if max_score > 0.7:
            return 'high'
        elif max_score > 0.4:
            return 'moderate'
        else:
            return 'low'
    
