    def _calculate_region_distance(self, latitude: float, longitude: float, region: Dict) -> float:
        """Calculate distance to volcanic region center"""
        try:
            from math import radians, sin, cos, sqrt, atan2
            
            # Haversine distance calculation
            lat1, lon1 = radians(latitude), radians(longitude)
            lat2, lon2 = radians(region['center_lat']), radians(region['center_lon'])
            
            dlat = lat2 - lat1
            dlon = lon2 - lon1
            
            a = sin(dlat/2)**2 + cos(lat1) * cos(lat2) * sin(dlon/2)**2
            c = 2 * atan2(sqrt(a), sqrt(1-a))
            
            return 6371.0 * c  # Earth radius in km
        except:
            # Fallback to simple distance approximation
            return sqrt((latitude - region['center_lat'])**2 + 
                       (longitude - region['center_lon'])**2) * 111.0  # Rough km conversion
    
    def _determine_volcanic_alert_level_advanced(self, activity_level: str, regional_data: Dict) -> str:
        """Advanced volcanic alert level determination"""
        base_alert_map = {
            'high': 'watch',
            'moderate': 'advisory',
            'low': 'normal'
        }
        
        base_alert = base_alert_map.get(activity_level, 'normal')
        
        # Enhance based on regional data
        if regional_data.get('recent_activity') == 'high' and activity_level in ['moderate', 'high']:
            alert_escalation = {'normal': 'advisory', 'advisory': 'watch', 'watch': 'warning'}
            base_alert = alert_escalation.get(base_alert, base_alert)
        
        return base_alert
    
    def _extract_volcanic_risk_features(self, latitude: float, longitude: float) -> np.ndarray:
        """Extract comprehensive volcanic risk features for ML prediction"""
        features = []
        
        # Geographic features
        features.extend([latitude, longitude])
        
        # Distance to major volcanic regions
        volcanic_regions = self._get_enhanced_volcanic_regions()
        for region in volcanic_regions:
            distance = self._calculate_region_distance(latitude, longitude, region)
            features.append(distance)
            # Normalized distance (0-1, closer = higher value)
            normalized_distance = max(0, 1 - (distance / region['influence_radius_km']))
            features.append(normalized_distance)
        
        # Tectonic setting indicators
        tectonic_features = self._extract_tectonic_features(latitude, longitude)
        features.extend(tectonic_features)
        
        # Elevation and topographic features
        elevation_features = self._extract_elevation_features(latitude, longitude)
        features.extend(elevation_features)
        
        # Geological age and rock type indicators
        geological_features = self._extract_geological_features(latitude, longitude)
        features.extend(geological_features)
        
        return np.array(features, dtype=np.float32)
    
    def _extract_tectonic_features(self, latitude: float, longitude: float) -> List[float]:
        """Extract tectonic setting features for volcanic risk assessment"""
        # Simplified tectonic feature extraction
        features = []
        
        # Distance to plate boundaries (simplified approximation)
        plate_boundary_distance = self._estimate_plate_boundary_distance(latitude, longitude)
        features.append(plate_boundary_distance)
        
        # Subduction zone proximity (binary indicators)
        subduction_zones = [
            {'lat_range': [-60, 60], 'lon_range': [120, -60], 'type': 'circum_pacific'},
            {'lat_range': [10, 50], 'lon_range': [90, 150], 'type': 'western_pacific'},
            {'lat_range': [-15, 15], 'lon_range': [-120, -60], 'type': 'eastern_pacific'}
        ]
        
        for zone in subduction_zones:
            in_zone = (zone['lat_range'][0] <= latitude <= zone['lat_range'][1] and
                      zone['lon_range'][0] <= longitude <= zone['lon_range'][1])
            features.append(float(in_zone))
        
        # Mid-ocean ridge proximity
        ridge_distance = self._estimate_ridge_distance(latitude, longitude)
        features.append(ridge_distance)
        
        return features
    
    def _extract_elevation_features(self, latitude: float, longitude: float) -> List[float]:
        """Extract elevation-based features for volcanic assessment"""
        # Simplified elevation estimation based on known volcanic regions
        features = []
        
        # Estimated elevation (simplified model)
        elevation = self._estimate_elevation(latitude, longitude)
        features.append(elevation)
        
        # Elevation gradient indicator (steep = more likely volcanic)
        gradient = abs(latitude) * 10 + abs(longitude % 180 - 90) * 5  # Simplified
        features.append(gradient)
        
        # Island vs continental indicator
        is_oceanic = self._is_oceanic_location(latitude, longitude)
        features.append(float(is_oceanic))
        
        return features
    
    def _extract_geological_features(self, latitude: float, longitude: float) -> List[float]:
        """Extract geological features for volcanic risk assessment"""
        features = []
        
        # Age indicators (simplified based on location patterns)
        # Younger regions (e.g., Pacific Ring of Fire) have higher activity
        pacific_proximity = min(abs(longitude - 180), abs(longitude + 180)) / 180.0
        features.append(1.0 - pacific_proximity)  # Closer to Pacific = younger
        
        # Rock type indicators (simplified)
        volcanic_rock_likelihood = self._estimate_volcanic_rock_likelihood(latitude, longitude)
        features.append(volcanic_rock_likelihood)
        
        # Structural features (fault density approximation)
        fault_density = self._estimate_fault_density(latitude, longitude)
        features.append(fault_density)
        
        return features
    
    def _estimate_plate_boundary_distance(self, latitude: float, longitude: float) -> float:
        """Estimate distance to nearest plate boundary"""
        # Simplified plate boundary distance estimation
        # Major boundaries: Mid-Atlantic Ridge, Pacific Ring of Fire, etc.
        
        boundaries = [
            {'lat': 0, 'lon': -25},  # Mid-Atlantic Ridge
            {'lat': 0, 'lon': 180},  # Pacific boundaries
            {'lat': 40, 'lon': 20},  # Mediterranean
        ]
        
        min_distance = float('inf')
        for boundary in boundaries:
            distance = self._calculate_region_distance(latitude, longitude, 
                                                     {'center_lat': boundary['lat'], 
                                                      'center_lon': boundary['lon']})
            min_distance = min(min_distance, distance)
        
        return min_distance / 1000.0  # Normalize to thousands of km
    
    def _estimate_ridge_distance(self, latitude: float, longitude: float) -> float:
        """Estimate distance to mid-ocean ridges"""
        # Major ridges
        ridges = [
            {'lat': 0, 'lon': -25},  # Mid-Atlantic
            {'lat': 0, 'lon': 140},  # East Pacific Rise
        ]
        
        min_distance = float('inf')
        for ridge in ridges:
            distance = self._calculate_region_distance(latitude, longitude,
                                                     {'center_lat': ridge['lat'],
                                                      'center_lon': ridge['lon']})
            min_distance = min(min_distance, distance)
        
        return min_distance / 1000.0
    
    def _estimate_elevation(self, latitude: float, longitude: float) -> float:
        """Estimate elevation based on location"""
        # Simplified elevation model
        # Higher elevations near known mountain/volcanic ranges
        elevation = 0.0
        
        # Pacific Ring of Fire tends to be elevated
        pacific_factor = 1.0 - min(abs(longitude - 180), abs(longitude + 180)) / 180.0
        elevation += pacific_factor * 2000  # Up to 2km
        
        # Continental vs oceanic
        if not self._is_oceanic_location(latitude, longitude):
            elevation += 500  # Continental boost
        
        # Mountain ranges approximation
        if 30 <= abs(latitude) <= 60:  # Mountain belt latitudes
            elevation += 1000
        
        return elevation / 5000.0  # Normalize to 0-1
    
    def _is_oceanic_location(self, latitude: float, longitude: float) -> bool:
        """Simple oceanic vs continental classification"""
        # Very simplified - just avoid major continental masses
        # North America
        if 30 <= latitude <= 70 and -170 <= longitude <= -60:
            return False
        # Europe/Asia
        if 35 <= latitude <= 70 and -10 <= longitude <= 140:
            return False
        # Africa
        if -35 <= latitude <= 35 and -20 <= longitude <= 50:
            return False
        # South America
        if -55 <= latitude <= 15 and -80 <= longitude <= -35:
            return False
        # Australia
        if -45 <= latitude <= -10 and 110 <= longitude <= 155:
            return False
        
        return True  # Assume oceanic
    
    def _estimate_volcanic_rock_likelihood(self, latitude: float, longitude: float) -> float:
        """Estimate likelihood of volcanic rocks at location"""
        # Higher likelihood in volcanic regions
        volcanic_regions = self._get_enhanced_volcanic_regions()
        max_likelihood = 0.0
        
        for region in volcanic_regions:
            distance = self._calculate_region_distance(latitude, longitude, region)
            if distance < region['influence_radius_km']:
                likelihood = (1.0 - distance / region['influence_radius_km']) * region['activity_weight']
                max_likelihood = max(max_likelihood, likelihood)
        
        return max_likelihood
    
    def _estimate_fault_density(self, latitude: float, longitude: float) -> float:
        """Estimate fault density based on tectonic setting"""
        # Higher fault density near plate boundaries
        boundary_distance = self._estimate_plate_boundary_distance(latitude, longitude)
        
        # Inverse relationship: closer to boundaries = higher fault density
        fault_density = max(0.0, 1.0 - boundary_distance / 2.0)  # Normalize
        
        return fault_density
    
    def _predict_volcanic_activity_ml(self, risk_features: np.ndarray) -> Optional[str]:
        """Predict volcanic activity using ML model from model database"""
        try:
            # Attempt to load volcanic activity classification model
            model_name = "volcanic_activity_classifier"
            
            if hasattr(self.model_database, 'load_model'):
                model_info = self.model_database.load_model(model_name)
                
                if model_info and 'model' in model_info:
                    model = model_info['model']
                    
                    # Reshape features for prediction
                    features_reshaped = risk_features.reshape(1, -1)
                    
                    # Make prediction
                    prediction = model.predict(features_reshaped)[0]
                    confidence = max(model.predict_proba(features_reshaped)[0])
                    
                    # Only return prediction if confidence is high enough
                    if confidence > 0.7:
                        # Map prediction to activity levels
                        activity_map = {0: 'low', 1: 'moderate', 2: 'high'}
                        return activity_map.get(prediction, 'low')
                    
        except Exception as e:
            self.logger.debug(f"ML volcanic prediction failed: {e}")
        
        return None  # Failed to get ML prediction
    
    def _assess_volcanic_activity_multi_source(self, latitude: float, longitude: float, 
                                             risk_features: np.ndarray) -> str:
        """Multi-source volcanic activity assessment"""
        # Combine multiple assessment methods
        assessments = []
        weights = []
        
        # Method 1: Enhanced regional analysis (already implemented)
        regional_assessment = self._assess_local_volcanic_activity_advanced(latitude, longitude)
        assessments.append(regional_assessment)
        weights.append(0.4)
        
        # Method 2: Feature-based assessment
        feature_assessment = self._assess_activity_from_features(risk_features)
        assessments.append(feature_assessment)
        weights.append(0.3)
        
        # Method 3: Database integration assessment
        if hasattr(self, 'db_integration'):
            db_assessment = self._assess_activity_from_database(latitude, longitude)
            assessments.append(db_assessment)
            weights.append(0.3)
        else:
            # Adjust weights if no database
            weights[0] = 0.6  # Give more weight to regional
            weights[1] = 0.4  # Give more weight to features
        
        # Weighted voting
        return self._combine_assessments(assessments, weights)
    
    def _assess_activity_from_features(self, risk_features: np.ndarray) -> str:
        """Assess volcanic activity based on extracted features"""
        # Simple rule-based assessment from features
        if len(risk_features) < 10:
            return 'low'
        
        # Check key feature indicators
        # Features 0-1: lat, lon
        # Features 2-9: distances to volcanic regions
        # Features 10+: tectonic, elevation, geological features
        
        # Average normalized distances to volcanic regions
        if len(risk_features) > 9:
            region_proximity_scores = risk_features[3:10:2]  # Every other starting from 3
            max_proximity = np.max(region_proximity_scores) if len(region_proximity_scores) > 0 else 0
            
            if max_proximity > 0.7:
                return 'high'
            elif max_proximity > 0.4:
                return 'moderate'
        
        # Tectonic indicators
        if len(risk_features) > 15:
            tectonic_score = np.mean(risk_features[10:15])
            if tectonic_score > 0.6:
                return 'moderate'
        
        return 'low'
    
    def _assess_activity_from_database(self, latitude: float, longitude: float) -> str:
        """Assess volcanic activity using database integration"""
        try:
            # Query database for volcanic activity indicators
            regional_data = self._query_regional_volcanic_database(latitude, longitude)
            
            if regional_data.get('database_available', False):
                active_systems = regional_data.get('active_systems', 0)
                recent_activity = regional_data.get('recent_activity', 'low')
                
                # Convert to standard activity levels
                if active_systems >= 2 or recent_activity == 'high':
                    return 'high'
                elif active_systems >= 1 or recent_activity == 'moderate':
                    return 'moderate'
                else:
                    return 'low'
        except Exception as e:
            self.logger.debug(f"Database assessment failed: {e}")
        
        return 'low'
    
    def _combine_assessments(self, assessments: List[str], weights: List[float]) -> str:
        """Combine multiple assessments using weighted voting"""
        if not assessments:
            return 'low'
        
        # Score each assessment
        assessment_scores = {'low': 0, 'moderate': 1, 'high': 2}
        score_to_assessment = {0: 'low', 1: 'moderate', 2: 'high'}
        
        weighted_score = 0.0
        total_weight = sum(weights)
        
        for assessment, weight in zip(assessments, weights):
            score = assessment_scores.get(assessment, 0)
            weighted_score += score * weight
        
        # Normalize and convert back
        final_score = weighted_score / total_weight if total_weight > 0 else 0
        
        # Round to nearest integer and convert back
        rounded_score = round(final_score)
        return score_to_assessment.get(rounded_score, 'low')
    
