    def _analyze_alert_indicators(self, monitoring_data: Dict, latitude: float, longitude: float) -> Dict:
        """Analyze multiple indicators for volcanic alert level determination"""
        indicators = {
            'seismic_indicators': 0,
            'thermal_indicators': 0,
            'gas_indicators': 0,
            'deformation_indicators': 0,
            'satellite_indicators': 0,
            'expert_assessments': 0
        }
        
        try:
            # Analyze seismic indicators
            if 'usgs' in monitoring_data and monitoring_data['usgs'].get('seismic_stations', 0) > 0:
                indicators['seismic_indicators'] = 2  # Moderate confidence
            
            # Analyze thermal indicators
            satellite_data = monitoring_data.get('satellite', {})
            if 'modis_thermal' in satellite_data:
                thermal_anomalies = satellite_data['modis_thermal'].get('thermal_anomalies', 0)
                if thermal_anomalies > 1.0:
                    indicators['thermal_indicators'] = 3  # High confidence
                elif thermal_anomalies > 0.5:
                    indicators['thermal_indicators'] = 2
                else:
                    indicators['thermal_indicators'] = 1
            
            # Analyze gas indicators
            if 'sentinel2' in satellite_data:
                so2_detection = satellite_data['sentinel2'].get('so2_detection', 0)
                if so2_detection > 0.7:
                    indicators['gas_indicators'] = 3
                elif so2_detection > 0.3:
                    indicators['gas_indicators'] = 2
            
            # Analyze expert assessments from GVP
            gvp_data = monitoring_data.get('gvp', {})
            recent_reports = gvp_data.get('recent_activity_reports', [])
            if recent_reports:
                max_activity = max([self._activity_level_to_score(report.get('activity_level', 'low')) 
                                  for report in recent_reports], default=0)
                indicators['expert_assessments'] = max_activity
            
            # Calculate composite indicator score
            indicators['composite_score'] = sum(indicators.values()) / 6.0  # Normalize
            indicators['confidence_level'] = self._calculate_indicator_confidence(monitoring_data)
            
        except Exception as e:
            self.logger.warning(f"Alert indicator analysis failed: {e}")
            indicators['error'] = str(e)
        
        return indicators
    
    def _activity_level_to_score(self, activity_level: str) -> int:
        """Convert activity level string to numeric score"""
        score_map = {'low': 1, 'moderate': 2, 'high': 3, 'extreme': 4}
        return score_map.get(activity_level.lower(), 1)
    
    def _calculate_indicator_confidence(self, monitoring_data: Dict) -> float:
        """Calculate confidence in alert indicators based on data quality"""
        confidence_factors = []
        
        # Data source diversity
        data_sources = monitoring_data.get('data_sources', 0)
        confidence_factors.append(min(data_sources / 4.0, 1.0))  # Max confidence with 4+ sources
        
        # Data quality from individual sources
        for source_name, source_data in monitoring_data.items():
            if isinstance(source_data, dict) and 'data_quality' in source_data:
                quality = source_data['data_quality']
                quality_score = {'low': 0.3, 'moderate': 0.6, 'good': 0.8, 'high': 1.0}.get(quality, 0.5)
                confidence_factors.append(quality_score)
        
        # Real-time data availability
        usgs_data = monitoring_data.get('usgs', {})
        if usgs_data.get('real_time_data_available', False):
            confidence_factors.append(0.9)
        
        return sum(confidence_factors) / len(confidence_factors) if confidence_factors else 0.5
    
