    def _setup_volcanic_model_caching(self):
        """Setup caching for volcanic models"""
        self._volcanic_model_cache = {}
        self._cache_expiry = {}
        self._cache_max_age = 3600  # 1 hour cache expiry
    
    def _initialize_volcanic_model_metadata(self):
        """Initialize metadata for volcanic models"""
        self._volcanic_model_metadata = {
            'last_training_data_version': None,
            'model_performance_metrics': {},
            'feature_importance_scores': {},
            'cross_validation_results': {},
            'model_update_history': []
        }
    
    def save_volcanic_analysis_model(self, model, model_name: str, model_type: str, 
                                   training_data_info: Dict, performance_metrics: Dict) -> str:
        """Save volcanic analysis model to model database"""
        try:
            if not hasattr(self, 'model_database'):
                raise ValueError("Model database not available")
            
            # Create comprehensive metadata
            metadata = self._create_volcanic_model_metadata(
                model_name, model_type, training_data_info, performance_metrics
            )
            
            # Save model with version control
            model_id = self.model_database.save_model(
                model=model,
                metadata=metadata,
                model_type=model_type
            )
            
            # Update local cache
            self._volcanic_model_cache[model_name] = {
                'model': model,
                'metadata': metadata,
                'model_id': model_id,
                'cached_at': datetime.now()
            }
            
            # Update performance tracking
            self._volcanic_model_metadata['model_performance_metrics'][model_name] = performance_metrics
            self._volcanic_model_metadata['model_update_history'].append({
                'model_name': model_name,
                'model_id': model_id,
                'timestamp': datetime.now().isoformat(),
                'performance': performance_metrics
            })
            
            self.logger.info(f"Volcanic model '{model_name}' saved with ID: {model_id}")
            return model_id
            
        except Exception as e:
            self.logger.error(f"Failed to save volcanic model '{model_name}': {e}")
            raise
    
    def load_volcanic_analysis_model(self, model_name: str) -> Optional[Dict]:
        """Load volcanic analysis model from database or cache"""
        try:
            # Check cache first
            if self._is_model_cached(model_name):
                self.logger.debug(f"Loading volcanic model '{model_name}' from cache")
                return self._volcanic_model_cache[model_name]
            
            # Load from model database
            if hasattr(self, 'model_database'):
                model_data = self.model_database.load_model(model_name)
                
                if model_data:
                    # Cache the loaded model
                    self._volcanic_model_cache[model_name] = {
                        'model': model_data['model'],
                        'metadata': model_data.get('metadata', {}),
                        'model_id': model_data.get('model_id'),
                        'cached_at': datetime.now()
                    }
                    
                    self.logger.info(f"Volcanic model '{model_name}' loaded from database")
                    return self._volcanic_model_cache[model_name]
            
            self.logger.warning(f"Volcanic model '{model_name}' not found")
            return None
            
        except Exception as e:
            self.logger.error(f"Failed to load volcanic model '{model_name}': {e}")
            return None
    
    def _is_model_cached(self, model_name: str) -> bool:
        """Check if model is cached and not expired"""
        if model_name not in self._volcanic_model_cache:
            return False
        
        cached_at = self._volcanic_model_cache[model_name].get('cached_at')
        if cached_at:
            age = (datetime.now() - cached_at).seconds
            return age < self._cache_max_age
        
        return False
    
    def _create_volcanic_model_metadata(self, model_name: str, model_type: str,
                                      training_data_info: Dict, performance_metrics: Dict) -> Dict:
        """Create comprehensive metadata for volcanic model"""
        from datetime import datetime
        
        # Get model type definition
        model_def = self._volcanic_model_types.get(model_type, {})
        
        return {
            'id': str(uuid.uuid4()),
            'name': model_name,
            'version': '1.0.0',
            'description': f"Volcanic analysis model: {model_def.get('description', model_type)}",
            'author': 'Prometheus_Volcanic_Analysis_System',
            'institution': 'Prometheus_Platform',
            'creation_date': datetime.now(),
            'last_modified': datetime.now(),
            'model_type': model_type,
            'region': 'global',
            'resolution': {'spatial': 'variable', 'temporal': 'real_time'},
            'dimensions': training_data_info.get('feature_dimensions', {}),
            'coordinate_system': 'geographic',
            'processing_parameters': {
                'training_algorithm': training_data_info.get('algorithm', 'unknown'),
                'feature_selection': training_data_info.get('feature_selection', 'automated'),
                'cross_validation': training_data_info.get('cross_validation', 'k_fold'),
                'hyperparameter_tuning': training_data_info.get('hyperparameter_tuning', True)
            },
            'quality_metrics': performance_metrics,
            'validation_status': 'validated' if performance_metrics.get('accuracy', 0) > 0.7 else 'pending',
            'tags': ['volcanic', 'activity_assessment', 'risk_analysis', 'ml_classification'],
            'license': 'Prometheus_Internal',
            'file_format': 'pickle',
            'training_data_info': training_data_info,
            'model_framework': model_def.get('model_framework', 'scikit-learn'),
            'expected_classes': model_def.get('output_classes', [])
        }
    
    def update_volcanic_model_performance(self, model_name: str, new_performance_metrics: Dict):
        """Update performance metrics for volcanic model"""
        try:
            # Update local metadata
            if model_name in self._volcanic_model_metadata['model_performance_metrics']:
                self._volcanic_model_metadata['model_performance_metrics'][model_name].update(new_performance_metrics)
            else:
                self._volcanic_model_metadata['model_performance_metrics'][model_name] = new_performance_metrics
            
            # Update in model database if available
            if hasattr(self, 'model_database') and hasattr(self.model_database, 'update_model_metrics'):
                self.model_database.update_model_metrics(model_name, new_performance_metrics)
            
            # Clear cache to force reload with updated metrics
            if model_name in self._volcanic_model_cache:
                del self._volcanic_model_cache[model_name]
            
            self.logger.info(f"Updated performance metrics for volcanic model '{model_name}'")
            
        except Exception as e:
            self.logger.error(f"Failed to update performance metrics for '{model_name}': {e}")
    
    def get_volcanic_model_performance_summary(self) -> Dict:
        """Get performance summary of all volcanic models"""
        try:
            summary = {
                'total_models': len(self._volcanic_model_metadata['model_performance_metrics']),
                'model_performances': {},
                'average_performance': {},
                'last_update': None
            }
            
            if self._volcanic_model_metadata['model_update_history']:
                summary['last_update'] = self._volcanic_model_metadata['model_update_history'][-1]['timestamp']
            
            # Calculate performance statistics
            all_accuracies = []
            all_precisions = []
            all_recalls = []
            
            for model_name, metrics in self._volcanic_model_metadata['model_performance_metrics'].items():
                summary['model_performances'][model_name] = metrics
                
                if 'accuracy' in metrics:
                    all_accuracies.append(metrics['accuracy'])
                if 'precision' in metrics:
                    all_precisions.append(metrics['precision'])
                if 'recall' in metrics:
                    all_recalls.append(metrics['recall'])
            
            # Calculate averages
            if all_accuracies:
                summary['average_performance']['accuracy'] = sum(all_accuracies) / len(all_accuracies)
            if all_precisions:
                summary['average_performance']['precision'] = sum(all_precisions) / len(all_precisions)
            if all_recalls:
                summary['average_performance']['recall'] = sum(all_recalls) / len(all_recalls)
            
            return summary
            
        except Exception as e:
            self.logger.error(f"Failed to get volcanic model performance summary: {e}")
            return {'error': str(e)}
    
    def retrain_volcanic_model(self, model_name: str, new_training_data: Dict) -> bool:
        """Retrain volcanic model with new data"""
        try:
            # Load existing model
            model_data = self.load_volcanic_analysis_model(model_name)
            if not model_data:
                raise ValueError(f"Model '{model_name}' not found for retraining")
            
            existing_model = model_data['model']
            existing_metadata = model_data['metadata']
            
            # Extract training features and labels from new data
            features = new_training_data.get('features')
            labels = new_training_data.get('labels')
            
            if features is None or labels is None:
                raise ValueError("New training data must contain 'features' and 'labels'")
            
            # Retrain the model
            retrained_model = existing_model.fit(features, labels)
            
            # Evaluate performance on validation set if available
            performance_metrics = {}
            if 'validation_features' in new_training_data and 'validation_labels' in new_training_data:
                val_features = new_training_data['validation_features']
                val_labels = new_training_data['validation_labels']
                
                predictions = retrained_model.predict(val_features)
                from sklearn.metrics import accuracy_score, precision_score, recall_score
                
                performance_metrics = {
                    'accuracy': accuracy_score(val_labels, predictions),
                    'precision': precision_score(val_labels, predictions, average='weighted'),
                    'recall': recall_score(val_labels, predictions, average='weighted'),
                    'retraining_date': datetime.now().isoformat(),
                    'training_samples': len(features)
                }
            
            # Save the retrained model
            training_data_info = {
                'algorithm': str(type(retrained_model).__name__),
                'feature_dimensions': {'n_features': features.shape[1] if hasattr(features, 'shape') else len(features[0])},
                'training_samples': len(features),
                'retraining': True,
                'previous_version': existing_metadata.get('version', 'unknown')
            }
            
            new_model_id = self.save_volcanic_analysis_model(
                retrained_model, model_name, existing_metadata.get('model_type', 'unknown'),
                training_data_info, performance_metrics
            )
            
            self.logger.info(f"Successfully retrained volcanic model '{model_name}' with ID: {new_model_id}")
            return True
            
        except Exception as e:
            self.logger.error(f"Failed to retrain volcanic model '{model_name}': {e}")
            return False
    
    def cleanup_volcanic_model_cache(self):
        """Clean up expired models from cache"""
        try:
            expired_models = []
            current_time = datetime.now()
            
            for model_name, model_data in self._volcanic_model_cache.items():
                cached_at = model_data.get('cached_at')
                if cached_at and (current_time - cached_at).seconds > self._cache_max_age:
                    expired_models.append(model_name)
            
            for model_name in expired_models:
                del self._volcanic_model_cache[model_name]
                self.logger.debug(f"Expired volcanic model '{model_name}' from cache")
            
            return len(expired_models)
            
        except Exception as e:
            self.logger.error(f"Failed to cleanup volcanic model cache: {e}")
            return 0
    
