    def _fuse_multi_source_volcanic_hazard_data(self, hazard_analysis: Dict, magmatic_system: Dict,
                                              multi_chamber: Dict, magma_source: Dict, tomography: Dict) -> Dict:
        """Fuse multi-source volcanic hazard data for comprehensive assessment"""
        try:
            # Weight different data sources based on availability and reliability
            source_weights = self._calculate_data_source_weights(
                magmatic_system, multi_chamber, magma_source, tomography
            )
            
            # Comprehensive hazard assessment
            fused_hazards = {
                'location': hazard_analysis['location'],
                'assessment_timestamp': hazard_analysis['hazard_assessment_timestamp'],
                'integrated_hazards': {
                    'lava_flows': self._assess_lava_flow_hazard(magmatic_system, multi_chamber, source_weights),
                    'pyroclastic_flows': self._assess_pyroclastic_hazard(magmatic_system, magma_source, source_weights),
                    'ash_fallout': self._assess_ash_fallout_hazard(multi_chamber, tomography, source_weights),
                    'volcanic_gases': self._assess_gas_hazard(magmatic_system, multi_chamber, source_weights),
                    'lahars': self._assess_lahar_hazard(tomography, magmatic_system, source_weights),
                    'ground_deformation': self._assess_deformation_hazard(tomography, multi_chamber, source_weights)
                },
                'hazard_probability_maps': self._generate_integrated_hazard_maps(
                    magmatic_system, multi_chamber, magma_source, tomography, source_weights
                ),
                'temporal_forecasts': self._generate_temporal_hazard_forecasts(
                    multi_chamber, tomography, source_weights
                ),
                'uncertainty_analysis': self._calculate_integrated_uncertainty(
                    magmatic_system, multi_chamber, magma_source, tomography, source_weights
                ),
                'confidence_metrics': {
                    'overall_confidence': np.mean(list(source_weights.values())),
                    'data_completeness': len([w for w in source_weights.values() if w > 0.5]) / len(source_weights),
                    'model_agreement': self._calculate_model_agreement(magmatic_system, multi_chamber, magma_source)
                }
            }
            
            return fused_hazards
            
        except Exception as e:
            self.logger.warning(f"Multi-source volcanic hazard fusion failed: {e}")
            return hazard_analysis  # Return basic hazard analysis as fallback
    
