    def integrate_ambient_noise_processing(self, continuous_data: np.ndarray, metadata: Dict) -> Dict:
        """Integration with improved ambient noise engine for continuous monitoring"""
        try:
            if not ADVANCED_MODULES_AVAILABLE:
                return {'error': 'Ambient noise engine not available', 'success': False}
            
            # Initialize ambient noise engine with array configuration
            noise_config = self._create_noise_config_from_array_metadata(metadata)
            noise_engine = AmbientNoiseEngine(noise_config)
            
            # Extract station pairs for cross-correlation
            station_pairs = self._extract_station_pairs_from_array(metadata)
            
            # Process ambient noise correlations
            correlation_results = []
            for station1, station2 in station_pairs:
                # Get data for station pair
                data1 = self._extract_station_data(continuous_data, station1, metadata)
                data2 = self._extract_station_data(continuous_data, station2, metadata)
                
                # Compute cross-correlation with advanced processing
                correlation = noise_engine.compute_correlation(data1, data2, metadata)
                correlation_results.append({
                    'station_pair': (station1, station2),
                    'correlation': correlation,
                    'distance_km': self._compute_station_distance(station1, station2, metadata)
                })
            
            # Velocity change detection
            velocity_changes = noise_engine.detect_velocity_changes(correlation_results)
            
            # Green's function extraction
            greens_functions = noise_engine.extract_greens_functions(correlation_results)
            
            # Integrate with array beamforming results
            array_integration = self._integrate_noise_with_array_processing(
                correlation_results, velocity_changes, metadata
            )
            
            return {
                'correlation_results': correlation_results,
                'velocity_changes': velocity_changes,
                'greens_functions': greens_functions,
                'array_integration': array_integration,
                'processing_type': 'ambient_noise_array_integration',
                'station_pairs_processed': len(station_pairs),
                'success': True,
                'timestamp': datetime.now().isoformat()
            }
            
        except Exception as e:
            self.logger.error(f"Ambient noise integration failed: {e}")
            return {'error': str(e), 'success': False}
    
