    def _detect_volcanic_events(self, seismic_data: np.ndarray, metadata: Dict) -> List[Dict]:
        """Detect and classify volcanic events in seismic data"""
        try:
            # Use existing ML capabilities for event detection
            events = []
            
            # Long-period events (magma movement)
            lp_events = self._detect_long_period_events(seismic_data)
            events.extend([{'type': 'long_period', 'event_data': event} for event in lp_events])
            
            # Volcano-tectonic events (rock fracturing)
            vt_events = self._detect_volcano_tectonic_events(seismic_data)
            events.extend([{'type': 'volcano_tectonic', 'event_data': event} for event in vt_events])
            
            # Tremor events (sustained volcanic activity)
            tremor_events = self._detect_volcanic_tremor_events(seismic_data)
            events.extend([{'type': 'volcanic_tremor', 'event_data': event} for event in tremor_events])
            
            return events
            
        except Exception as e:
            self.logger.debug(f"Volcanic event detection failed: {e}")
            return []
        
