    def _calculate_p_wave_probability(self, rectilinearity: float, inclination: float) -> float:
        """Calculate probability that the signal is a P-wave based on polarization"""
        # P-waves typically show high rectilinearity and steep incidence angles
        rectilinearity_weight = 0.7
        inclination_weight = 0.3
        
        # Normalize inclination (P-waves often have higher inclination angles)
        inclination_factor = min(1.0, abs(inclination) / 45.0)
        
        p_probability = rectilinearity_weight * rectilinearity + inclination_weight * inclination_factor
        return np.clip(p_probability, 0.0, 1.0)
    
    def _assess_polarization_quality(self, eigenvalues: np.ndarray) -> str:
        """Assess quality of polarization analysis"""
        if len(eigenvalues) < 3:
            return 'poor'
        
        # Signal-to-noise ratio based on eigenvalue distribution
        snr = eigenvalues[0] / (eigenvalues[1] + eigenvalues[2] + 1e-10)
        
        if snr > 10:
            return 'excellent'
        elif snr > 5:
            return 'good'
        elif snr > 2:
            return 'fair'
        else:
            return 'poor'
    
    def _determine_tectonic_setting_advanced(self, latitude: float, longitude: float) -> Dict:
        """Advanced tectonic setting determination using global tectonic databases and real-time data integration"""
        try:
            # Import required modules for database integration
            import os
            from pathlib import Path
            
            # Initialize tectonic analysis results
            tectonic_results = {
                'setting_type': 'unknown',
                'activity_level': 'unknown',
                'plate_boundary_distance': float('inf'),
                'dominant_motion': 'unknown',
                'confidence': 0.0,
                'data_sources': [],
                'analysis_details': {}
            }
            
            # Integrate with global tectonic plate boundary database (PB2002, NUVEL)
            plate_boundary_data = self._query_global_plate_boundaries(latitude, longitude)
            if plate_boundary_data:
                tectonic_results['data_sources'].append('PB2002_plate_boundaries')
                tectonic_results.update(plate_boundary_data)
            
            # Integrate with global stress field database (WSM - World Stress Map)
            stress_field_data = self._query_world_stress_map(latitude, longitude)
            if stress_field_data:
                tectonic_results['data_sources'].append('world_stress_map')
                tectonic_results['analysis_details']['stress_field'] = stress_field_data
            
            # Integrate with seismicity databases (ISC, USGS)
            seismicity_data = self._analyze_regional_seismicity(latitude, longitude)
            if seismicity_data:
                tectonic_results['data_sources'].append('seismicity_catalog')
                tectonic_results['analysis_details']['seismicity'] = seismicity_data
            
            # Integrate with GPS velocity field (UNAVCO, IGS)
            gps_velocity_data = self._query_gps_velocity_field(latitude, longitude)
            if gps_velocity_data:
                tectonic_results['data_sources'].append('gps_velocity_field')
                tectonic_results['analysis_details']['gps_velocities'] = gps_velocity_data
            
            # Integrate with global heat flow database
            heat_flow_data = self._query_global_heat_flow(latitude, longitude)
            if heat_flow_data:
                tectonic_results['data_sources'].append('global_heat_flow')
                tectonic_results['analysis_details']['heat_flow'] = heat_flow_data
            
            # Perform advanced tectonic setting classification
            classified_setting = self._classify_tectonic_setting_ml(tectonic_results)
            tectonic_results.update(classified_setting)
            
            # Calculate plate boundary distance using real data
            tectonic_results['plate_boundary_distance'] = self._calculate_plate_boundary_distance(
                latitude, longitude, plate_boundary_data
            )
            
            # Infer dominant plate motion from multiple data sources
            tectonic_results['dominant_motion'] = self._infer_plate_motion_advanced(
                latitude, longitude, tectonic_results['analysis_details']
            )
            
            # Calculate confidence score based on data availability and quality
            tectonic_results['confidence'] = self._calculate_tectonic_confidence(
                tectonic_results['data_sources'], tectonic_results['analysis_details']
            )
            
            # Store results in model database for caching
            self._cache_tectonic_analysis(latitude, longitude, tectonic_results)
            
            return tectonic_results
            
        except Exception as e:
            self.logger.error(f"Advanced tectonic setting determination failed: {e}")
            return {
                'setting_type': 'unknown',
                'activity_level': 'unknown',
                'plate_boundary_distance': float('inf'),
                'dominant_motion': 'unknown',
                'confidence': 0.0,
                'error': str(e)
            }
    
