    def get_error_statistics(self) -> Dict[str, Any]:
        """Get comprehensive error statistics"""
        
        if not self.error_history:
            return {'total_errors': 0, 'message': 'No errors recorded'}
        
        total_errors = len(self.error_history)
        recovery_attempts = sum(1 for err in self.error_history if err['recovery_attempted'])
        successful_recoveries = sum(1 for err in self.error_history if err['recovery_successful'])
        
        # Error classification statistics
        error_types = {}
        for error in self.error_history:
            error_type = error.get('classification', 'unknown')
            error_types[error_type] = error_types.get(error_type, 0) + 1
        
        # Recovery strategy effectiveness
        strategy_effectiveness = {}
        for error in self.error_history:
            if error['recovery_attempted']:
                strategy = error.get('recovery_strategy', 'unknown')
                if strategy not in strategy_effectiveness:
                    strategy_effectiveness[strategy] = {'attempts': 0, 'successes': 0}
                
                strategy_effectiveness[strategy]['attempts'] += 1
                if error['recovery_successful']:
                    strategy_effectiveness[strategy]['successes'] += 1
        
        # Calculate success rates
        for strategy, stats in strategy_effectiveness.items():
            stats['success_rate'] = stats['successes'] / stats['attempts'] if stats['attempts'] > 0 else 0.0
        
        return {
            'total_errors': total_errors,
            'recovery_attempts': recovery_attempts,
            'successful_recoveries': successful_recoveries,
            'recovery_success_rate': successful_recoveries / recovery_attempts if recovery_attempts > 0 else 0.0,
            'error_types': error_types,
            'strategy_effectiveness': strategy_effectiveness,
            'circuit_breaker_states': {k: v['state'] for k, v in self.circuit_breakers.items()},
            'analysis_period': {
                'start': min(err['timestamp'] for err in self.error_history),
                'end': max(err['timestamp'] for err in self.error_history)
            } if self.error_history else None
        }
    
    def reset_circuit_breakers(self):
        """Reset all circuit breakers to closed state"""
        for circuit_breaker in self.circuit_breakers.values():
            circuit_breaker['state'] = 'closed'
            circuit_breaker['failure_count'] = 0
        
        self.logger.info("All circuit breakers reset to closed state")
    
    def get_system_health_report(self) -> Dict[str, Any]:
        """Generate comprehensive system health report"""
        
        error_stats = self.get_error_statistics()
        
        # Determine overall health
        recent_errors = [
            err for err in self.error_history 
            if (datetime.now() - err['timestamp']).total_seconds() < 3600  # Last hour
        ]
        
        if not recent_errors:
            health_status = 'excellent'
        elif len(recent_errors) <= 2:
            health_status = 'good'
        elif len(recent_errors) <= 5:
            health_status = 'fair'
        else:
            health_status = 'poor'
        
        return {
            'overall_health': health_status,
            'error_statistics': error_stats,
            'recent_error_count': len(recent_errors),
            'fault_tolerance_enabled': self.fault_tolerance_enabled,
            'circuit_breaker_summary': {
                'total_breakers': len(self.circuit_breakers),
                'open_breakers': sum(1 for cb in self.circuit_breakers.values() if cb['state'] == 'open'),
                'half_open_breakers': sum(1 for cb in self.circuit_breakers.values() if cb['state'] == 'half_open')
            },
            'recommendations': self._generate_health_recommendations(recent_errors, error_stats)
        }
    
    def _generate_health_recommendations(self, recent_errors: List[Dict], 
                                       error_stats: Dict[str, Any]) -> List[str]:
        """Generate health improvement recommendations"""
        
        recommendations = []
        
        # High error rate
        if len(recent_errors) > 10:
            recommendations.append("Consider investigating root causes of high error rate")
        
        # Low recovery success rate
        recovery_rate = error_stats.get('recovery_success_rate', 1.0)
        if recovery_rate < 0.7:
            recommendations.append("Review and improve error recovery strategies")
        
        # Circuit breaker issues
        open_breakers = sum(1 for cb in self.circuit_breakers.values() if cb['state'] == 'open')
        if open_breakers > 0:
            recommendations.append(f"Reset {open_breakers} open circuit breakers and investigate underlying issues")
        
        # Specific error type recommendations
        error_types = error_stats.get('error_types', {})
        if error_types.get('memory_exhaustion', 0) > 5:
            recommendations.append("Consider optimizing memory usage or increasing available memory")
        
        if error_types.get('external_service_failure', 0) > 3:
            recommendations.append("Review external service dependencies and implement better caching")
        
        return recommendations
    
    def _infer_rock_types_advanced(self, latitude: float, longitude: float) -> List[Dict]:
        """Advanced rock type inference with ML models and multi-source data integration"""
        try:
            # Multi-source geological data integration
            tectonic_setting = self._determine_tectonic_setting_advanced(latitude, longitude)
            geological_age = self._estimate_geological_age(latitude, longitude)
            geochemical_signature = self._analyze_geochemical_signature(latitude, longitude)
            seismic_velocity_profile = self._get_seismic_velocity_profile(latitude, longitude)
            magnetic_anomaly = self._analyze_magnetic_anomaly(latitude, longitude)
            gravity_anomaly = self._analyze_gravity_anomaly(latitude, longitude)
            
            # Feature vector for ML model
            features = np.array([
                tectonic_setting.get('activity_level', 0.5),
                tectonic_setting.get('plate_convergence_rate', 0.0),
                geological_age.get('ma_age', 100.0) / 1000.0,  # Normalize to Ga
                geochemical_signature.get('sio2_content', 50.0) / 100.0,
                geochemical_signature.get('mgo_content', 5.0) / 20.0,
                seismic_velocity_profile.get('vp_avg', 6.0) / 10.0,
                magnetic_anomaly.get('intensity', 0.0) / 50000.0,
                gravity_anomaly.get('bouguer_anomaly', 0.0) / 200.0,
                abs(latitude) / 90.0,  # Latitude normalization
                abs(longitude) / 180.0  # Longitude normalization
            ]).reshape(1, -1)
            
            # Advanced rock type classification using ensemble methods
            rock_probabilities = self._ml_rock_classification_ensemble(features)
            
            # Geochemical constraints and refinement
            refined_probabilities = self._apply_geochemical_constraints(
                rock_probabilities, geochemical_signature
            )
            
            # Tectonic setting-specific refinements
            context_refined = self._apply_tectonic_context_refinement(
                refined_probabilities, tectonic_setting, geological_age
            )
            
            # Age-based weathering and alteration modeling
            weathering_effects = self._model_weathering_alteration(
                context_refined, geological_age, self._get_climate_history(latitude, longitude)
            )
            
            # Format results with detailed mineralogical and textural information
            rock_types = []
            for rock_type, probability in weathering_effects.items():
                if probability > 0.05:  # Only include significant probabilities
                    detailed_composition = self._get_detailed_rock_composition(
                        rock_type, geochemical_signature, tectonic_setting
                    )
                    
                    rock_info = {
                        'type': rock_type,
                        'probability': float(probability),
                        'composition': detailed_composition['primary_composition'],
                        'mineralogy': detailed_composition['mineral_assemblage'],
                        'texture': detailed_composition['typical_texture'],
                        'formation_process': detailed_composition['formation_mechanism'],
                        'age_estimate_ma': geological_age.get('ma_age', 100.0),
                        'metamorphic_grade': detailed_composition.get('metamorphic_grade', 'none'),
                        'weathering_state': detailed_composition.get('weathering_degree', 'fresh'),
                        'geochemical_signature': {
                            'sio2': geochemical_signature.get('sio2_content', 50.0),
                            'mgo': geochemical_signature.get('mgo_content', 5.0),
                            'cao': geochemical_signature.get('cao_content', 10.0),
                            'alkali_index': geochemical_signature.get('na2o_k2o', 3.0)
                        },
                        'confidence_metrics': {
                            'data_quality': self._assess_data_quality(latitude, longitude),
                            'model_certainty': float(np.max(list(weathering_effects.values()))),
                            'geochemical_consistency': self._check_geochemical_consistency(
                                rock_type, geochemical_signature
                            )
                        }
                    }
                    rock_types.append(rock_info)
            
            # Sort by probability and limit to top 5 most likely rock types
            rock_types.sort(key=lambda x: x['probability'], reverse=True)
            return rock_types[:5] if rock_types else [self._get_unknown_rock_default()]
            
        except Exception as e:
            self._log_error(f"Advanced rock type inference failed: {str(e)}")
            return [self._get_unknown_rock_default()]
    
    def _ml_rock_classification_ensemble(self, features: np.ndarray) -> Dict[str, float]:
        """Advanced ensemble ML classification with full infrastructure integration"""
        try:
            # Initialize integrated systems
            model_manager = self._get_model_manager_instance()
            data_pipeline = self._get_data_integration_pipeline()
            db_integration = self._get_database_integration()
            
            # Multi-model ensemble architecture
            ensemble_models = {
                'geological_rf': 'rock_classification_random_forest_v3.2',
                'tectonic_xgb': 'tectonic_context_xgboost_v2.8',
                'geochemical_nn': 'geochemical_neural_network_v4.1',
                'seismic_svm': 'seismic_velocity_svm_v2.5',
                'temporal_lstm': 'temporal_evolution_lstm_v1.9'
            }
            
            # Load pre-trained models from model database
            loaded_models = {}
            model_metadata = {}
            for model_name, model_id in ensemble_models.items():
                try:
                    model_info = model_manager.load_model_by_id(
                        model_id, 
                        include_metadata=True,
                        cache_locally=True
                    )
                    loaded_models[model_name] = model_info['model']
                    model_metadata[model_name] = model_info['metadata']
                    
                    # Log model usage for MLOps tracking
                    self._log_model_usage(model_id, features.shape, 'rock_classification')
                    
                except Exception as e:
                    self._log_warning(f"Failed to load {model_name} ({model_id}): {str(e)}")
                    loaded_models[model_name] = None
            
            # Enhanced feature engineering with data pipeline integration
            enhanced_features = data_pipeline.engineer_geological_features(
                base_features=features,
                context_type='rock_classification',
                apply_domain_knowledge=True,
                include_temporal_features=True
            )
            
            # Multi-scale spatial context integration
            spatial_context = db_integration.query_spatial_geological_context(
                latitude=self._extract_latitude_from_features(features),
                longitude=self._extract_longitude_from_features(features),
                search_radius_km=50,
                include_historical_data=True
            )
            
            # Combine features with spatial context
            contextual_features = self._merge_features_with_spatial_context(
                enhanced_features, spatial_context
            )
            
            # Multi-model predictions with uncertainty quantification
            model_predictions = {}
            prediction_uncertainties = {}
            
            for model_name, model in loaded_models.items():
                if model is not None:
                    try:
                        # Model-specific feature preprocessing
                        processed_features = self._preprocess_features_for_model(
                            contextual_features, model_name, model_metadata[model_name]
                        )
                        
                        # Generate prediction with uncertainty
                        if hasattr(model, 'predict_proba'):
                            # Probabilistic models
                            prediction = model.predict_proba(processed_features)[0]
                            uncertainty = self._calculate_prediction_uncertainty(
                                model, processed_features, method='entropy'
                            )
                        else:
                            # Non-probabilistic models with uncertainty estimation
                            prediction = model.predict(processed_features)[0]
                            uncertainty = self._estimate_model_uncertainty(
                                model, processed_features, model_name
                            )
                        
                        model_predictions[model_name] = prediction
                        prediction_uncertainties[model_name] = uncertainty
                        
                    except Exception as e:
                        self._log_error(f"Prediction failed for {model_name}: {str(e)}")
                        model_predictions[model_name] = None
                        prediction_uncertainties[model_name] = 1.0
            
            # Advanced ensemble fusion with adaptive weighting
            ensemble_weights = self._calculate_adaptive_ensemble_weights(
                model_predictions, 
                prediction_uncertainties,
                model_metadata,
                contextual_features
            )
            
            # Bayesian model averaging with geological constraints
            bayesian_probabilities = self._bayesian_model_averaging(
                model_predictions, 
                ensemble_weights,
                prior_geological_knowledge=spatial_context.get('rock_type_priors', {})
            )
            
            # Post-processing with geological domain knowledge
            refined_probabilities = self._apply_geological_domain_constraints(
                bayesian_probabilities,
                spatial_context,
                enhanced_features
            )
            
            # Active learning feedback mechanism
            confidence_score = self._calculate_ensemble_confidence(
                refined_probabilities, prediction_uncertainties
            )
            
            if confidence_score < 0.7:  # Low confidence threshold
                self._trigger_active_learning_feedback(
                    features, refined_probabilities, confidence_score
                )
            
            # Real-time model performance monitoring
            self._update_model_performance_metrics(
                ensemble_models.values(), 
                refined_probabilities,
                confidence_score
            )
            
            # Cache results for future use
            cache_key = self._generate_prediction_cache_key(contextual_features)
            self._cache_prediction_result(cache_key, refined_probabilities, ttl_hours=24)
            
            # Convert to standard rock type format
            standardized_results = self._standardize_rock_type_probabilities(
                refined_probabilities, 
                include_geological_metadata=True
            )
            
            return standardized_results
            
        except Exception as e:
            self._log_error(f"Advanced ensemble classification failed: {str(e)}")
            # Fallback to simplified classification with error tracking
            self._track_prediction_failure('ensemble_classification', str(e))
            return self._fallback_rock_classification(features)
    
