    def _apply_geochemical_constraints(self, probabilities: Dict[str, float], 
                                     geochemical_data: Dict) -> Dict[str, float]:
        """Apply geochemical constraints to refine rock type probabilities"""
        try:
            refined = probabilities.copy()
            sio2 = geochemical_data.get('sio2_content', 50.0)
            mgo = geochemical_data.get('mgo_content', 5.0)
            cao = geochemical_data.get('cao_content', 10.0)
            
            # Geochemical compatibility matrix
            compatibility_matrix = {
                'volcanic_basaltic': {'sio2': (45, 52), 'mgo': (6, 15), 'cao': (8, 14)},
                'volcanic_andesitic': {'sio2': (54, 62), 'mgo': (2, 8), 'cao': (5, 10)},
                'volcanic_rhyolitic': {'sio2': (68, 78), 'mgo': (0, 2), 'cao': (0.5, 3)},
                'igneous_granite': {'sio2': (65, 75), 'mgo': (0, 3), 'cao': (1, 4)},
                'sedimentary_limestone': {'sio2': (5, 25), 'mgo': (0.5, 5), 'cao': (40, 55)}
            }
            
            for rock_type, constraints in compatibility_matrix.items():
                if rock_type in refined:
                    compatibility_score = 1.0
                    for element, (min_val, max_val) in constraints.items():
                        if element == 'sio2':
                            value = sio2
                        elif element == 'mgo':
                            value = mgo
                        else:  # cao
                            value = cao
                        
                        if min_val <= value <= max_val:
                            compatibility_score *= 1.2
                        else:
                            deviation = min(abs(value - min_val), abs(value - max_val))
                            compatibility_score *= max(0.1, 1.0 - deviation / 20.0)
                    
                    refined[rock_type] *= compatibility_score
            
            # Renormalize
            total = sum(refined.values())
            return {k: v/total for k, v in refined.items()} if total > 0 else refined
            
        except Exception:
            return probabilities
    
