    # Helper methods for ML classifier creation
    def _create_oceanic_classifier(self):
        """Create oceanic location classifier"""
        try:
            if TORCH_AVAILABLE:
                # Neural network for oceanic classification
                from torch import nn
                model = nn.Sequential(
                    nn.Linear(10, 64),  # Features: lat, lon, bathymetry, gravity, etc.
                    nn.ReLU(),
                    nn.Dropout(0.2),
                    nn.Linear(64, 32),
                    nn.ReLU(), 
                    nn.Dropout(0.2),
                    nn.Linear(32, 1),
                    nn.Sigmoid()
                )
                return model
            else:
                # Fallback to sklearn
                from sklearn.ensemble import RandomForestClassifier
                return RandomForestClassifier(n_estimators=100, random_state=42)
        except Exception:
            return None
    
    def _create_mountain_classifier(self):
        """Create mountain belt classifier"""
        try:
            if TORCH_AVAILABLE:
                from torch import nn
                model = nn.Sequential(
                    nn.Linear(15, 128),  # More features for topographic analysis
                    nn.ReLU(),
                    nn.BatchNorm1d(128),
                    nn.Dropout(0.3),
                    nn.Linear(128, 64),
                    nn.ReLU(),
                    nn.Dropout(0.2),
                    nn.Linear(64, 1),
                    nn.Sigmoid()
                )
                return model
            else:
                from sklearn.ensemble import GradientBoostingClassifier
                return GradientBoostingClassifier(n_estimators=100, random_state=42)
        except Exception:
            return None
    
    def _create_shield_classifier(self):
        """Create shield location classifier"""
        try:
            if TORCH_AVAILABLE:
                from torch import nn
                model = nn.Sequential(
                    nn.Linear(12, 96),  # Age, thickness, stability features
                    nn.ReLU(),
                    nn.BatchNorm1d(96),
                    nn.Dropout(0.25),
                    nn.Linear(96, 48),
                    nn.ReLU(),
                    nn.Dropout(0.2),
                    nn.Linear(48, 1),
                    nn.Sigmoid()
                )
                return model
            else:
                from sklearn.ensemble import RandomForestClassifier
                return RandomForestClassifier(n_estimators=150, random_state=42)
        except Exception:
            return None
    
    def _create_basin_classifier(self):
        """Create sedimentary basin classifier"""
        try:
            if TORCH_AVAILABLE:
                from torch import nn
                model = nn.Sequential(
                    nn.Linear(18, 144),  # Complex basin analysis features
                    nn.ReLU(),
                    nn.BatchNorm1d(144),
                    nn.Dropout(0.3),
                    nn.Linear(144, 72),
                    nn.ReLU(),
                    nn.Dropout(0.25),
                    nn.Linear(72, 36),
                    nn.ReLU(),
                    nn.Dropout(0.2),
                    nn.Linear(36, 1),
                    nn.Sigmoid()
                )
                return model
            else:
                from sklearn.ensemble import GradientBoostingClassifier
                return GradientBoostingClassifier(n_estimators=120, random_state=42)
        except Exception:
            return None
    
    def _create_boundary_classifier(self):
        """Create plate boundary classifier"""
        try:
            if TORCH_AVAILABLE:
                from torch import nn
                model = nn.Sequential(
                    nn.Linear(20, 160),  # Comprehensive tectonic features
                    nn.ReLU(),
                    nn.BatchNorm1d(160),
                    nn.Dropout(0.35),
                    nn.Linear(160, 80),
                    nn.ReLU(),
                    nn.Dropout(0.3),
                    nn.Linear(80, 40),
                    nn.ReLU(),
                    nn.Dropout(0.25),
                    nn.Linear(40, 1),
                    nn.Sigmoid()
                )
                return model
            else:
                from sklearn.ensemble import RandomForestClassifier
                return RandomForestClassifier(n_estimators=200, random_state=42)
        except Exception:
            return None
    
    def _create_ensemble_classifier(self):
        """Create ensemble classifier combining all geological classifiers"""
        try:
            if hasattr(self, 'geological_classifier_models') and self.geological_classifier_models:
                # Ensemble combining all individual classifiers
                ensemble_config = {
                    'voting_strategy': 'soft',
                    'weight_by_confidence': True,
                    'uncertainty_weighted': True
                }
                return ensemble_config
            return None
        except Exception:
            return None
    
    def _create_bootstrap_estimator(self):
        """Create bootstrap uncertainty estimator"""
        try:
            return {
                'n_bootstrap_samples': 100,
                'confidence_intervals': [0.05, 0.95],
                'random_state': 42
            }
        except Exception:
            return {}
    
    def _create_monte_carlo_estimator(self):
        """Create Monte Carlo uncertainty estimator"""
        try:
            return {
                'n_mc_samples': 1000,
                'dropout_probability': 0.1,
                'temperature_scaling': True
            }
        except Exception:
            return {}
    
    def _create_bayesian_estimator(self):
        """Create Bayesian uncertainty estimator"""
        try:
            return {
                'prior_distribution': 'normal',
                'inference_method': 'variational',
                'n_posterior_samples': 500
            }
        except Exception:
            return {}
    
