    def query_plate_boundaries(self, latitude: float, longitude: float) -> Optional[Dict]:
        """Query plate boundary database with caching"""
        try:
            if not self.model_database:
                return None
            
            # Check cache first
            cache_key = f"plate_boundaries_{latitude:.4f}_{longitude:.4f}"
            
            # Try to get from model database
            cached_data = self._get_cached_plate_boundary_data(cache_key)
            if cached_data:
                return cached_data
            
            # If not in cache, perform analysis and store
            plate_data = self._perform_plate_boundary_analysis(latitude, longitude)
            if plate_data:
                self._cache_plate_boundary_data(cache_key, plate_data)
            
            return plate_data
            
        except Exception as e:
            self.logger.error(f"Plate boundary query failed: {e}")
            return None
    
    def cache_tectonic_analysis(self, latitude: float, longitude: float, results: Dict):
        """Cache tectonic analysis results in model database"""
        try:
            if not self.model_database:
                return
            
            # Create metadata for tectonic analysis
            from datetime import datetime, timezone
            metadata = {
                'type': 'tectonic_analysis',
                'location': {'latitude': latitude, 'longitude': longitude},
                'timestamp': datetime.now(timezone.utc).isoformat(),
                'version': '1.0',
                'confidence': results.get('confidence', 0.0),
                'data_sources': results.get('data_sources', []),
                'results': results
            }
            
            # Store in database (simplified - would use proper model registration)
            cache_key = f"tectonic_{latitude:.4f}_{longitude:.4f}"
            self._store_analysis_result(cache_key, metadata)
            
        except Exception as e:
            self.logger.error(f"Failed to cache tectonic analysis: {e}")
    
