    def _analyze_temporal_earthquake_distribution(self, earthquake_data: List) -> Dict[str, Any]:
        """Analyze temporal distribution of earthquakes"""
        try:
            from datetime import datetime
            import collections
            
            # Extract timestamps
            timestamps = []
            for eq in earthquake_data:
                if hasattr(eq, 'timestamp'):
                    timestamps.append(eq.timestamp)
            
            if not timestamps:
                return {'status': 'no_temporal_data'}
            
            # Sort timestamps
            timestamps.sort()
            
            # Calculate inter-event times
            inter_event_times = []
            for i in range(1, len(timestamps)):
                dt = (timestamps[i] - timestamps[i-1]).total_seconds() / 3600  # hours
                inter_event_times.append(dt)
            
            # Temporal clustering analysis
            hourly_counts = collections.defaultdict(int)
            daily_counts = collections.defaultdict(int)
            
            for ts in timestamps:
                hourly_counts[ts.hour] += 1
                daily_counts[ts.date()] += 1
            
            return {
                'total_events': len(timestamps),
                'time_span_days': (timestamps[-1] - timestamps[0]).days if len(timestamps) > 1 else 0,
                'mean_inter_event_time_hours': sum(inter_event_times) / len(inter_event_times) if inter_event_times else 0,
                'hourly_distribution': dict(hourly_counts),
                'daily_event_counts': len(daily_counts),
                'temporal_clustering_coefficient': self._calculate_temporal_clustering_coefficient(inter_event_times)
            }
            
        except Exception as e:
            return {'status': 'analysis_failed', 'error': str(e)}
    
    def _analyze_spatial_earthquake_clustering(self, earthquake_data: List) -> Dict[str, Any]:
        """Analyze spatial clustering of earthquakes"""
        try:
            import numpy as np
            from math import radians, cos, sin, asin, sqrt
            
            # Extract coordinates
            coordinates = []
            for eq in earthquake_data:
                if hasattr(eq, 'coordinates') and len(eq.coordinates) >= 2:
                    lat, lon = eq.coordinates[0], eq.coordinates[1]
                    coordinates.append((lat, lon))
            
            if len(coordinates) < 2:
                return {'status': 'insufficient_spatial_data'}
            
            # Calculate pairwise distances using haversine formula
            distances = []
            n_events = len(coordinates)
            
            for i in range(n_events):
                for j in range(i+1, n_events):
                    lat1, lon1 = coordinates[i]
                    lat2, lon2 = coordinates[j]
                    
                    # Haversine formula for distance
                    lat1, lon1, lat2, lon2 = map(radians, [lat1, lon1, lat2, lon2])
                    dlat = lat2 - lat1
                    dlon = lon2 - lon1
                    a = sin(dlat/2)**2 + cos(lat1) * cos(lat2) * sin(dlon/2)**2
                    distance = 2 * asin(sqrt(a)) * 6371  # Earth radius in km
                    distances.append(distance)
            
            # Nearest neighbor analysis
            nearest_neighbor_distances = []
            for i in range(n_events):
                min_dist = float('inf')
                lat1, lon1 = coordinates[i]
                
                for j in range(n_events):
                    if i != j:
                        lat2, lon2 = coordinates[j]
                        lat1_r, lon1_r, lat2_r, lon2_r = map(radians, [lat1, lon1, lat2, lon2])
                        dlat = lat2_r - lat1_r
                        dlon = lon2_r - lon1_r
                        a = sin(dlat/2)**2 + cos(lat1_r) * cos(lat2_r) * sin(dlon/2)**2
                        distance = 2 * asin(sqrt(a)) * 6371
                        min_dist = min(min_dist, distance)
                
                nearest_neighbor_distances.append(min_dist)
            
            return {
                'num_events': n_events,
                'mean_distance_km': np.mean(distances),
                'std_distance_km': np.std(distances),
                'mean_nearest_neighbor_km': np.mean(nearest_neighbor_distances),
                'spatial_extent_km': max(distances) if distances else 0,
                'clustering_index': np.std(distances) / np.mean(distances) if np.mean(distances) > 0 else 0
            }
            
        except Exception as e:
            return {'status': 'analysis_failed', 'error': str(e)}
    
    def _correlate_detection_with_seismicity(self, beam_result: Dict, earthquake_data: List) -> Dict[str, Any]:
        """Correlate beam detection with regional seismicity patterns"""
        try:
            beam_location = beam_result.get('location', {})
            beam_lat = beam_location.get('latitude', 0)
            beam_lon = beam_location.get('longitude', 0)
            
            if not beam_lat and not beam_lon:
                return {'status': 'no_beam_location'}
            
            # Find closest earthquakes
            from math import radians, cos, sin, asin, sqrt
            
            nearby_events = []
            for eq in earthquake_data:
                if hasattr(eq, 'coordinates') and len(eq.coordinates) >= 2:
                    eq_lat, eq_lon = eq.coordinates[0], eq.coordinates[1]
                    
                    # Calculate distance
                    lat1, lon1, lat2, lon2 = map(radians, [beam_lat, beam_lon, eq_lat, eq_lon])
                    dlat = lat2 - lat1
                    dlon = lon2 - lon1
                    a = sin(dlat/2)**2 + cos(lat1) * cos(lat2) * sin(dlon/2)**2
                    distance_km = 2 * asin(sqrt(a)) * 6371
                    
                    if distance_km <= 50:  # Within 50km
                        event_info = {
                            'distance_km': distance_km,
                            'magnitude': eq.properties.get('magnitude', 0) if hasattr(eq, 'properties') else 0,
                            'timestamp': eq.timestamp if hasattr(eq, 'timestamp') else None
                        }
                        nearby_events.append(event_info)
            
            # Calculate correlation metrics
            if nearby_events:
                distances = [ev['distance_km'] for ev in nearby_events]
                magnitudes = [ev['magnitude'] for ev in nearby_events if ev['magnitude'] > 0]
                
                correlation_metrics = {
                    'nearby_events_count': len(nearby_events),
                    'closest_event_distance_km': min(distances),
                    'mean_nearby_distance_km': sum(distances) / len(distances),
                    'nearby_magnitude_range': [min(magnitudes), max(magnitudes)] if magnitudes else [0, 0],
                    'correlation_strength': 'high' if len(nearby_events) > 5 else 'moderate' if len(nearby_events) > 2 else 'low'
                }
            else:
                correlation_metrics = {
                    'nearby_events_count': 0,
                    'correlation_strength': 'none'
                }
            
            return correlation_metrics
            
        except Exception as e:
            return {'status': 'correlation_failed', 'error': str(e)}
    
    def _calculate_satellite_temporal_span(self, satellite_data: List) -> Dict[str, Any]:
        """Calculate temporal span of satellite data coverage"""
        try:
            from datetime import datetime
            
            timestamps = []
            for sat in satellite_data:
                if hasattr(sat, 'timestamp'):
                    timestamps.append(sat.timestamp)
            
            if not timestamps:
                return {'status': 'no_temporal_data'}
            
            timestamps.sort()
            
            return {
                'earliest_image': timestamps[0].isoformat(),
                'latest_image': timestamps[-1].isoformat(),
                'temporal_span_days': (timestamps[-1] - timestamps[0]).days,
                'image_frequency_days': (timestamps[-1] - timestamps[0]).days / len(timestamps) if len(timestamps) > 1 else 0,
                'temporal_coverage': 'excellent' if len(timestamps) > 10 else 'good' if len(timestamps) > 5 else 'limited'
            }
            
        except Exception as e:
            return {'status': 'calculation_failed', 'error': str(e)}
    
    def _calculate_temporal_clustering_coefficient(self, inter_event_times: List[float]) -> float:
        """Calculate temporal clustering coefficient for earthquake sequences"""
        try:
            import numpy as np
            
            if len(inter_event_times) < 2:
                return 0.0
            
            # Calculate coefficient of variation
            mean_time = np.mean(inter_event_times)
            std_time = np.std(inter_event_times)
            
            if mean_time == 0:
                return 0.0
            
            cv = std_time / mean_time
            
            # Convert to clustering coefficient (higher CV indicates more clustering)
            clustering_coeff = min(1.0, cv / 2.0)  # Normalize to 0-1 range
            
            return clustering_coeff
            
        except Exception:
            return 0.0
    
