    def _calculate_aspect_entropy(self, aspects: List[float]) -> float:
        """Calculate entropy of aspect distribution"""
        if not aspects:
            return 0
        
        # Bin aspects into 8 compass directions
        bins = np.histogram(aspects, bins=8, range=(0, 360))[0]
        # Normalize to probabilities
        probs = bins / np.sum(bins) if np.sum(bins) > 0 else np.ones(8) / 8
        # Calculate entropy
        entropy = -np.sum(probs * np.log2(probs + 1e-10))
        return entropy / 3  # Normalize to 0-1
    
    def _calculate_aspect_diversity_uncertainty(self, entropy: float, variance: float, roughness: float) -> float:
        """Calculate uncertainty in aspect diversity analysis"""
        # Higher uncertainty when metrics disagree
        metric_agreement = 1 - np.std([entropy, variance, roughness])
        return max(0.1, 1 - metric_agreement)
    
