    def _calculate_drainage_density_uncertainty(self, hydro_data: Dict, stream_network: List, watershed_analysis: Dict) -> float:
        """Calculate uncertainty in drainage density estimation"""
        data_quality_factor = len(hydro_data) / 10  # More data = less uncertainty
        network_complexity = len(stream_network) / 100 if stream_network else 0
        return max(0.1, 1 - min(data_quality_factor + network_complexity, 1))
    
