    def _calculate_structural_complexity_uncertainty(self, ml_pred: float, traditional_pred: float, models: Dict) -> float:
        """Calculate uncertainty in structural complexity estimation"""
        prediction_agreement = 1 - abs(ml_pred - traditional_pred)
        model_availability = len(models) / 3  # Expected 3 models
        return max(0.1, 1 - (prediction_agreement + model_availability) / 2)
    
